insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى: {يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنْصَابُ وَالأَزْلاَمُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ. إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللَّهِ وَعَنِ الصَّلاَةِ فَهَلْ أَنْتُمْ مُنْتَهُونَ} [المائدة : ٩٠، ٩١] (ن)', 'പരിശുദ്ധനും ഉന്നതനുമായ അല്ലാഹു പറയുന്നു: ''വിശ്വാസികളേ, മദ്യവും ചൂതാട്ടവും ശിലാപൂജയും അസ്ത്രമേറുമെല്ലാം പിശാചിന്റെ മലിനവൃത്തികളാണ്. ആയതിനാൽ നിങ്ങളവ വർജ്ജിക്കുക, എങ്കിൽ നിങ്ങൾ വിജയികളായേക്കാം. മദ്യവും ചൂതാട്ടവും വഴി നിങ്ങൾക്കിടയിൽ ശത്രുതയും വിദ്വേഷവും ഉണ്ടാക്കുവാനും ദൈവസ്മരണയിൽനിന്നും നമസ്കാരത്തിൽനിന്നും നിങ്ങളെ തെറ്റിക്കാനുമാണ് പിശാച് ഉദ്ദേശിക്കുന്നത്. ഇനിയെങ്കിലും നിങ്ങൾ അവയിൽനിന്ന് വിരമിക്കുന്നില്ലേ.'' (അൽമാഇദ: 90,91) (ന)', null, 'പരിശുദ്ധനും ഉന്നതനുമായ അല്ലാഹു പറയുന്നു', null, null, array['ن']::text[], array['ന']::text[], 'المائدة : ٩٠، ٩١', null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ مُسْكِرٍ خَمْرٌ، وَكُلُّ مُسْكِرٍ حَرَامٌ، وَمَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، فَمَاتَ وَهُوَ يُدْمِنُهَا، لَمْ يَشْرَبْهَا فِي الْآخِرَةِ." حَسَنٌ صَحِيحٌ. (م,د,ت,ن)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം മദ്യമാകുന്നു. ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധവുമാണ്. ആരെങ്കിലും ഇഹലോകത്ത് മദ്യം കഴിക്കുകയും അത് തുടർന്നുകൊണ്ടിരിക്കെ മരണപ്പെടുകയും ചെയ്താൽ പരലോകത്ത് അവനത് പാനം ചെയ്യുകയില്ല." (മു,ദ,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَىٰ} وَ: {يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ} [البقرة: ١٩] نَسَخَتْهُمَا الَّتِي فِي الْمَائِدَةِ.[٩٠]: {إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ} الْآيَةَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ''സത്യവിശ്വാസികളേ, ഉന്മത്തരായി നിങ്ങൾ നമസ്കാരത്തോടടുക്കരുത്.'' (നിസാഅ്:43) ''മദ്യത്തെയും ചൂതാട്ടത്തെയും സംബന്ധിച്ച് താങ്കളോടവർ ചോദിക്കുന്നു; പറയുക, മനുഷ്യർക്ക് അവ രണ്ടിലും വലിയ ദോഷമുണ്ട്. ചിലപ്രയോജനങ്ങളുമുണ്ട്.'' (അൽബഖറ: 19). ഈ രണ്ട് സൂക്തങ്ങളെയും ''മദ്യവും ചൂതും പ്രതിഷ്ഠകളും'' എന്ന അൽമാഇദയിലെ 90 ാമത്തെ സൂക്തം ദുർബലപ്പെടുത്തിയിരിക്കുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], '٩٠', null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَرِبَ الْخَمْرَ لَمْ يَقْبَلِ اللَّهُ لَهُ صَلَاةً أَرْبَعِينَ صَبَاحًا، فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ. فَإِنْ عَادَ لَمْ يَقْبَلِ اللَّهُ لَهُ صَلَاةً أَرْبَعِينَ صَبَاحًا، فَإِنْ تَابَ اللهُ عَلَيْهِ. فَإِنْ عَادَ لَمْ يَقْبَلِ اللهُ لَهُ صَلَاةَ أَرْبَعِينَ صَبَاحًا، فَإِنْ تَابَ تَابَ اللهُ عَلَيْهِ. فَإِنْ عَادَ الرَّابِعَةَ لَمْ يَقْبَلِ اللهُ لَهُ صَلَاةَ أَرْبَعِينَ صَبَاحًا، فَإِنْ تَابَ لَمْ يَتُبِ اللهُ عَلَيْهِ، وَسَقَاهُ مِنْ نَهْرِ الْخَبَالِ" قِيلَ: يَا أَبَا عَبْدِ الرَّحْمَنِ، وَمَا نَهْرُ الْخَبَالِ؟ قَالَ: نَهْرٌ مِنْ صَدِيدِ أَهْلِ النَّارِ. حَسَنٌ (ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്‌നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും കള്ള് കുടിച്ചാൽ അല്ലാഹു അവന്റെ നാല്പത് ദിവസത്തെ പ്രഭാത നമസ്കാരം സ്വീകരിക്കുകയില്ല. അവൻ പശ്ചാത്തപിച്ചാൽ അല്ലാഹു അവന്റെ പശ്ചാത്താപം സ്വീകരിക്കുന്നതാണ്. അവൻ വീണ്ടും (കള്ളിലേക്ക്) മടങ്ങിയാൽ അല്ലാഹു അവന്റെ നാല്പത് ദിവസത്തെ നമസ്കാരം സ്വീകരിക്കുകയില്ല. അവൻ പശ്ചാത്തപിച്ചാൽ അല്ലാഹു അവന്റെ പശ്ചാത്താപം സ്വീകരിക്കുന്നതാണ്. വീണ്ടും അവൻ മടങ്ങിയാൽ അല്ലാഹു അവന്റെ നാല്പത് ദിവസത്തെ നമസ്കാരം സ്വീകരിക്കുകയില്ല. അവൻ പശ്ചാത്തപിച്ചാൽ അല്ലാഹു അവന്റെ പശ്ചാത്താപം സ്വീകരിക്കുന്നതാണ്. ഇനി നാലാം പ്രാവശ്യവും മടങ്ങിയാൽ അല്ലാഹു അവന്റെ നാല്പത് ദിവസത്തെ നമസ്കാരം സ്വീകരിക്കുകയില്ല. അവൻ ഖേദിച്ചു മടങ്ങിയാൽ അല്ലാഹു മാപ്പുകൊടുക്കുകയുമില്ല, ''ഖബാൽ'' എന്ന നദിയിൽനിന്നും അല്ലാഹു അവനെ കുടിപ്പിക്കുന്നതുമാണ്." ചോദിക്കപ്പെട്ടു: അബ്ദുർറഹ്മാന്റെ പിതാവേ! എന്താണ് ഖബാൽ നദി? അവിടുന്ന് പറഞ്ഞു: "നരകവാസികളുടെ ചലത്തി (പഴുപ്പ്) നാലുള്ള ഒരു നദിയാണത്." (തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്‌നു ഉമർ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 591, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ سَاقِيَ الْقَوْمِ حَيْثُ حُرِّمَتِ الْخَمْرُ فِي مَنْزِلِ أَبِي طَلْحَةَ، وَمَا شَرَابُنَا يَوْمَئِذٍ إِلَّا الْفَضِيخُ، فَدَخَلَ عَلَيْنَا رَجُلٌ فَقَالَ: إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ وَنَادَى مُنَادِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَا: هَذَا مُنَادِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'അനസ്(റ): മദ്യം നിഷിദ്ധമാക്കപ്പെട്ട സന്ദർഭത്തിൽ അബൂത്വൽഹയുടെ ഭവനത്തിൽ കുറേ പേർക്ക് ഞാൻ മദ്യം ഒഴിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. ഞങ്ങളുടെ പാനീയം ഈത്തപ്പഴനീരായിരുന്നു. അപ്പോൾ ഒരാൾ ഞങ്ങളുടെയടുക്കൽ പ്രവേശിച്ചിട്ട് പറഞ്ഞു: മദ്യം നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കുന്നു. റസൂൽ(സ)യുടെ വിളംബരം ചെയ്യുന്ന വ്യക്തി വിളിച്ച് പറയുകയും ചെയ്തു. ഞങ്ങളപ്പോൾ പറഞ്ഞു: ഇദ്ദേഹം റസൂൽ(സ)യുടെ വിളംബരം ചെയ്യുന്നയാളാണ്. (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَ تَحْرِيمُ الْخَمْرِ قَالَ عُمَرُ: اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً، فَنَزَلَتِ الْآيَةُ الَّتِي فِي الْبَقَرَةِ [٢١٩] { يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ } الْآيَةَ قَالَ: فَدُعِيَ عُمَرُ، فَقُرِئَتْ عَلَيْهِ، قَالَ: اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً، فَنَزَلَتِ الْآيَةُ الَّتِي فِي النِّسَاءِ [٤٣] { يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى } فَكَانَ مُنَادِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أُقِيمَتِ الصَّلَاةُ يُنَادِي: أَلَا لَا يَقْرَبَنَّ الصَّلَاةَ سَكْرَانُ. فَدُعِيَ عُمَرُ فَقُرِئَتْ عَلَيْهِ، فَقَالَ: اللَّهُمَّ بَيِّنْ لَنَا فِي الْخَمْرِ بَيَانًا شِفَاءً، فَنَزَلَتْ هَذِهِ الْآيَةُ [المائدة: ٩١] { فَهَلْ أَنْتُمْ مُنْتَهُونَ } قَالَ عُمَرُ: انْتَهَيْنَا. (د,ت,ن)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): മദ്യം നിഷിദ്ധമാക്കുന്ന സൂക്തം അവതരിച്ചപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവേ, മദ്യത്തിന്റെ വിഷയത്തിൽ തൃപ്തികരമായ വിശദീകരണം നീ ഞങ്ങൾക്ക് നൽകിയാലും. അപ്പോൾ അൽ ബഖറയിലെ 219 ാം സൂക്തം ഇറങ്ങി: ''മദ്യത്തെയും ചൂതാട്ടത്തെയും കുറിച്ച് അവർ താങ്കളോട് ചോദിക്കുന്നു. പറയുക, മനുഷ്യർക്ക് അവ രണ്ടിലും ദോഷമുണ്ട്.'' അദ്ദേഹം പറയുന്നു: ഉമർ(റ) വിളിക്കപ്പെടുകയും ഓതിക്കേൾപ്പിക്കപ്പെടുകയും ചെയ്തു. ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവേ മദ്യത്തിന്റെ വിഷയത്തിൽ തൃപ്തികരമായ വിശദീകരണം നീ ഞങ്ങൾക്ക് നൽകണേ. അപ്പോൾ അന്നിസാഅ് സൂറത്തിലെ ''സത്യവിശ്വാസികളേ ലഹരി ബാധിതരായി നിങ്ങൾ നമസ്കാരത്തോടടുക്കരുത്.'' (നിസാഅ്: 43) എന്നസൂക്തം അവതരിച്ചു. അനന്തരം നമസ്കാരത്തിന് ഇഖാമത്ത് കൊടുത്താൽ പ്രവാചകന്റെ വിളിച്ചുപറയുന്ന ആൾ വിളംബരം ചെയ്യും: അറിയുക, ലഹരിബാധിതൻ നമസ്കാരത്തെ തീർച്ചയായും സമീപിക്കരുത്. ശേഷം ഉമർ(റ) ക്ഷണിക്കപ്പെടുകയും പാരായണം ചെയ്യപ്പെടുകയും ചെയ്തു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവേ, മദ്യത്തെക്കുറിച്ച് തൃപ്തികരമായി നീ ഞങ്ങളോടു വിശദീകരിച്ചാലും. തുടർന്ന് ''ഇനിയെങ്കിലും നിങ്ങൾ വിരമിക്കുന്നില്ലേ'' (അൽമാഇദ: 91) എന്നസൂക്തം അവതരിച്ചു. ഉമർ(റ) പറഞ്ഞു: ഞങ്ങൾ വിരമിച്ചു. (ദ,തു,ന)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], 'المائدة: ٩١', null, 592, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا مِنَ الْأَنْصَارِ دَعَاهُ وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ فَسَقَاهُمَا، قَبْلَ تَحْرِيمِ الْخَمْرِ، فَأَمَّهُمْ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ فِي الْمَغْرِبِ فَقَرَأَ: {قُلْ يَا أَيُّهَا الْكَافِرُونَ} فَخَلَطَ فِيهَا: فَنَزَلَتْ: {لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى حَتَّى تَعْلَمُوا مَا تَقُولُونَ} [النساء: ٤٣] (د,ت)', 'അലിയ്യിബ്നു അബീത്വാലിബ്(റ): അൻസാരിയായ ഒരാൾ അലി(റ)വിനെയും അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ)വിനെയും ക്ഷണിക്കുകയും അവരെ മദ്യം കുടിപ്പിക്കുകയും ചെയ്തു. അന്ന് മദ്യം ഹറാമാക്കിയിരുന്നില്ല. അനന്തരം അലി(റ) മഗ്‌രിബ് നമസ്കാരത്തിന് നേതൃത്വം കൊടുക്കുകയും ''കാഫിറൂൻ'' എന്ന സൂക്തം ഓതുകയും അതിൽ പിഴവ് വരുത്തുകയും ചെയ്തു. അപ്പോൾ അവതരിച്ചു: ''സത്യവിശ്വാസികളേ, ഉന്മത്തരായി നിങ്ങൾ നമസ്കാരത്തോടടുക്കരുത്. നിങ്ങൾ പറയുന്നതിൽ നിങ്ങൾക്ക് സ്വബോധം ഉണ്ടാകുന്നത് വരെ.'' (അന്നിസാഅ്: 43). (ദ,തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യിബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'النساء: ٤٣', null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَبْدِاللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، ثُمَّ لَمْ يَتُبْ مِنْهَا، حُرِمَهَا فِي الْآخِرَةِ". (خ)', 'അബ്ദുള്ളാഇബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഇഹലോകത്ത് മദ്യം സേവിച്ച് അതിൽനിന്ന് ഖേദിച്ചു മടങ്ങിയില്ലെങ്കിൽ പരലോകത്ത് അവനത് തടയപ്പെടും." (ബു)', 'عَبْدِاللَّهِ بْنِ عُمَرَ', 'അബ്ദുള്ളാഇബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ: قَالَ: كَانَتْ لِي شَارِفٌ مِنْ نَصِيبِي مِنَ الْمَغْنَمِ يَوْمَ بَدْرٍ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَانِي شَارِفًا مِنَ الْخُمُسِ يَوْمَئِذٍ، فَلَمَّا أَرَدْتُ أَنْ أَبْتَنِيَ بِفَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاعَدْتُ رَجُلًا صَوَّاغًا مِنْ بَنِي قَيْنُقَاعَ يَرْتَحِلُ مَعِي، فَنَأْتِيَ بِإِذْخِرٍ أَرَدْتُ أَنْ أَبِيعَهُ مِنَ الصَّوَّاغِينَ، فَأَسْتَعِينَ بِهِ فِي وَلِيمَةِ عُرْسِي، فَبَيْنَا أَنَا أَجْمَعُ لِشَارِفَيَّ مَتَاعًا مِنَ الْأَقْتَابِ وَالْغَرَائِرِ وَالْحِبَالِ، وَشَارِفَايَ مُنَاخَانِ إِلَى جَنْبِ حُجْرَةِ رَجُلٍ مِنَ الْأَنْصَارِ، وَجَمَعْتُ حِينَ جَمَعْتُ مَا جَمَعْتُ فَإِذَا شَارِفَايَ قَدِ اجْتُبَّتْ أَسْنِمَتُهُمَا، وَبُقِرَتْ خَوَاصِرُهُمَا وَأُخِذَ مِنْ أَكْبَادِهِمَا، فَلَمْ أَمْلِكْ عَيْنَيَّ حِينَ رَأَيْتُ ذَلِكَ الْمَنْظَرَ مِنْهُمَا، قُلْتُ: مَنْ فَعَلَ هَذَا؟ قَالُوا: فَعَلَهُ حَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ، وَهُوَ فِي هَذَا الْبَيْتِ فِي شَرْبٍ مِنَ الْأَنْصَارِ، غَنَّتْهُ قَيْنَةٌ وَأَصْحَابَهُ، فَقَالَتْ فِي غِنَائِهَا: أَلَا يَا حَمْزُ لِلشُّرُفِ النِّوَاءِ، فَقَامَ حَمْزَةُ بِالسَّيْفِ فَاجْتَبَّ أَسْنِمَتَهُمَا، وَبَقَرَ خَوَاصِرَهُمَا فَأَخَذَ مِنْ أَكْبَادِهِمَا. فَقَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ: فَانْطَلَقْتُ حَتَّى أَدْخُلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ زَيْدُ بْنُ حَارِثَةَ، قَالَ: فَعَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي وَجْهِيَ الَّذِي لَقِيتُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا لَكَ؟". قُلْتُ: يَا رَسُولَ اللَّهِ، وَاللَّهِ مَا رَأَيْتُ كَالْيَوْمِ قَطُّ، عَدَا حَمْزَةُ عَلَى نَاقَتَيَّ فَاجْتَبَّ أَسْنِمَتَهُمَا وَبَقَرَ خَوَاصِرَهُمَا، وَهَا هُوَ ذَا فِي بَيْتٍ مَعَهُ شَرْبٌ. قَالَ: فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرِدَائِهِ فَارْتَدَاهُ ثُمَّ انْطَلَقَ يَمْشِي، وَاتَّبَعْتُهُ أَنَا وَزَيْدُ بْنُ حَارِثَةَ حَتَّى جَاءَ الْبَابَ الَّذِي فِيهِ حَمْزَةُ، فَاسْتَأْذَنَ فَأُذِنُوا لَهُ، فَإِذَا هُمْ شَرْبٌ، فَطَفِقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلُومُ حَمْزَةَ فِيمَا فَعَلَ فَإِذَا حَمْزَةُ مُحْمَرَّةٌ عَيْنَاهُ، فَنَظَرَ حَمْزَةُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَعَّدَ النَّظَرَ إِلَى رُكْبَتَيْهِ، ثُمَّ صَعَّدَ النَّظَرَ فَنَظَرَ فَنَظَرَ إِلَى سُرَّتِهِ، ثُمَّ صَعَّدَ النَّظَرَ فَنَظَرَ فَنَظَرَ إِلَى وَجْهِهِ، فَقَالَ حَمْزَةُ: وَهَلْ أَنْتُمْ إِلَّا عَبِيدٌ لِأَبِي؟ فَعَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ ثَمِلٌ، فَنَكَصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَقِبَيْهِ الْقَهْقَرَى، وَخَرَجَ وَخَرَجْنَا مَعَهُ. (ق)', 'അലിയ്യിബ്നു അബീത്വാലിബ്(റ): ബദർ ദിനത്തിലെ യുദ്ധാർജ്ജിത സ്വത്തിൽ നിന്നു പ്രായം ചെന്ന ഒരു പെൺഒട്ടകം എനിക്ക് ലഭിച്ചു. നബി(സ)ക്കുള്ള അഞ്ചിലൊന്നിൽ നിന്ന് പ്രായംചെന്ന ഒരു പെൺ ഒട്ടകത്തേയും കൂടി അന്നേ ദിവസം എനിക്ക് നബി(സ) നൽകിയിരുന്നു. പ്രവാചകന്റെ മകളായ ഫാത്തിമ(റ)യുമായി വീടുകൂടാൻ ഉദ്ദേശിച്ചപ്പോൾ ബനൂഖയ്നുഖാഅ് ഗോത്രത്തിൽപ്പെട്ട ഒരു ആഭരണപ്പണിക്കാരനോട് എന്റെ കൂടെ അനുഗമിക്കാൻ ഉടമ്പടി ചെയ്തു. അങ്ങനെ ഞാൻ ഇദ്ഖിർ (ഇഞ്ചിപ്പുല്ല്) പുല്ല് കൊണ്ടുവന്നു. ഞാനതിനെ ചില ആഭരണപ്പണിക്കാർക്ക് വിൽക്കുവാനും അതുമുഖേന കല്യാണസദ്യക്ക് സഹായം തേടുവാനും ഉദ്ദേശിച്ചു. ജീനികൾ, ചാക്കുകൾ, കയറുകൾ തുടങ്ങിയ ചരക്കുകൾ ഞാൻ ഒരുമിച്ച് കൂട്ടുമ്പോൾ എന്റെ പ്രയം ചെന്ന രണ്ട് പെൺ ഒട്ടകങ്ങളും ഒരു അൻസാരിയുടെ വീടിന്റെ ഭാഗത്ത് നിൽക്കുകയായിരുന്നു. ചരക്കുകളെല്ലാം ഒരുമിച്ചുകൂട്ടി ഞാൻ മടങ്ങിയെത്തിയപ്പോഴോതാ എന്റെ പ്രായംചെന്ന രണ്ട് പെൺ ഒട്ടകങ്ങളുടെയും പൂഞ്ഞകൾ മുറിച്ചെടുക്കപ്പെടുകയും ഊര കീറി കരൾ പുറത്തെടുക്കുകയും ചെയ്തിരിക്കുന്നു. ആ ദൃശ്യം കണ്ട വേളയിൽ എന്റെ നയനങ്ങളെ എനിക്ക് നിയന്ത്രിക്കാനായില്ല. ഞാൻ ചോദിച്ചു: ആരാണ് ഇത് ചെയ്തത്? അവർ പറഞ്ഞു: ഹംസത്തുബ്നു അബ്ദിൽ മുത്വലിബ് ആണ് ഈ കൃത്യം നിർവ്വഹിച്ചത്. അദ്ദേഹം അൻസാരികളിൽ നിന്നുള്ള മദ്യാസക്തരോടൊപ്പം ഈ ഭവനത്തിലുണ്ട്. അദ്ദേഹത്തിന്റേയും സഖാക്കളുടെയും സന്നിധിയിൽ ഒരു ഗായിക ഗാനം ആലപിക്കുന്നുണ്ട്. തന്റെ ഗാനത്തിൽ അവൾ പറഞ്ഞു: ഓ ഹംസ, ഈ തടിച്ച ഒട്ടകങ്ങളെ ശ്രദ്ധിക്കുക, അവയെ പിടിച്ചെടുക്കുക. ഉടനെ ഹംസ വാളുമായി ചാടി എഴുന്നേറ്റ് അവയുടെ പൂഞ്ഞക്ക് വെട്ടുകയും വയർ കുത്തിക്കീറി രണ്ടിന്റെയും കരൾ മുറിച്ചെടുക്കുകയും ചെയ്തു. അലി(റ) പറയുന്നു: ഞാൻ നടന്ന് അങ്ങനെ റസൂൽ(സ)യുടെ സന്നിധിയിലെത്തി. തിരുമേനി(സ)യുടെ അടുത്ത് സൈദിബ്നു ഹാരിസയുമുണ്ടായിരുന്നു. അലി(റ) പറയുന്നു: ഞാൻ അഭിമുഖീകരിച്ചതിനെ റസൂൽ(സ) എന്റെ മുഖത്തുനിന്നും തിരിച്ചറിഞ്ഞു. ഉടനെ റസൂൽ(സ) ചോദിച്ചു: നിനക്കെന്തുപറ്റി? ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹു തന്നെ സത്യം! ഇത്പോലൊരു ദിവസം എന്റെ ജീവിതത്തിലുണ്ടായിട്ടില്ല. ഹംസ എന്റെ രണ്ട് ഒട്ടകങ്ങളോടും അക്രമം പ്രവർത്തിച്ചിരിക്കുന്നു. അദ്ദേഹം അവയുടെ പൂഞ്ഞക്ക് വെട്ടുകയും വയർ കുത്തിക്കീറുകയും ചെയ്തു. അദ്ദേഹം അതാ ആ ഭവനത്തിലുണ്ട്. അദ്ദേഹത്തിനോടൊപ്പം മദ്യപാനികളുടെ സംഘവുമുണ്ട്. അലി(റ) പറയുന്നു: റസൂൽ(സ) മേലങ്കി ആവശ്യപ്പെട്ടു. അങ്ങനെ അത് അണിഞ്ഞതിനു ശേഷം കാൽ നടയായി അവിടന്ന് പുറപ്പെട്ടു. ഞാനും സൈദിബ്നു ഹാരിസയും അവിടത്തെ അനുഗമിച്ചു. അങ്ങനെ ഹംസയുള്ള വീടിന്റെ വാതിൽക്കൽ ചെന്ന് അനുവാദം തേടി. അവർ റസൂൽ(സ)ക്ക് അനുവാദം നൽകി. അപ്പോൾ അവർ കുടിച്ച് കൂത്താടുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) ഹംസയെ തന്റെ പ്രവർത്തനത്തിന്റെ പേരിൽ ആക്ഷേപിക്കാൻ തുടങ്ങി. തദവസരത്തിൽ ഹംസ തന്റെ ചുവന്ന രണ്ട് കണ്ണുമായി പ്രവാചകർ(സ)യെ നോക്കി. പിന്നീട് പ്രവാചകന്റെ രണ്ട് കാൽ മുട്ടിലേക്ക് നോക്കി. പിന്നെ കണ്ണുകളുയർത്തി ഊരയിലേക്ക് നോക്കി. ശേഷം ദൃഷ്ടി ഉയർത്തി പ്രവാചകന്റെ മുഖത്തേക്ക് നോക്കി. എന്നിട്ട് പറഞ്ഞു: നിങ്ങൾ എന്റെ പിതാവിന്റെ അടിമകളല്ലാതെ മറ്റാരാണ്? ഹംസ ലഹരി ബാധിതനാണെന്ന് റസൂൽ(സ) മനസ്സിലാക്കിയപ്പോൾ ഉടനെ കാൽ പിന്നോട്ടുവെച്ച് മടങ്ങി. അങ്ങനെ നബി(സ)യും ഞങ്ങളും അവിടെനിന്ന് പുറപ്പെട്ടു. (ബു,മു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യിബ്നു അബീത്വാലിബ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 593, 594, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَوْصَانِي خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَشْرَبِ الْخَمْرَ فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ“. (جه)', 'അബൂദ്ദർദാഅ്(റ): എന്റെ ആത്മമിത്രം (പ്രവാചകൻ) എന്നെ ഉപദേശിച്ചു: “നീ മദ്യം കുടിക്കരുത്, കാരണം നിശ്ചയമത് എല്ലാ തിന്മകളുടെയും താക്കോലാണ്.” (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 594, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ خَبَّابِ بْنِ الْأَرَتِّ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: ”إِيَّاكَ وَالْخَمْرَ، فَإِنَّ خَطِيئَتَهَا تَفْرَعُ الْخَطَايَا، كَمَا أَنَّ شَجَرَتَهَا تَفْرَعُ الشَّجَرَ“. [ز: في سنده ضعيف] (جه)', 'ഖബ്ബാബുബ്നു അറത്ത്(റ): റസൂൽ(സ) അരുളി: “നിന്നെയും മദ്യത്തേയും നീ സൂക്ഷിക്കുക, കാരണം ചെടി(മുന്തിരച്ചെടി)കൾ മറ്റു ചെടികളിലേക്ക് പടർന്നു കയറുന്നതുപോലെ മദ്യത്തിന്റെ തെറ്റുകൾ മറ്റുതെറ്റുകളിലേക്ക് പടർന്നു കയറും.” (പരമ്പരയിൽ ബലഹീതയുണ്ട്). (ജ)', 'خَبَّابِ بْنِ الْأَرَتِّ', 'ഖബ്ബാബുബ്നു അറത്ത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 595, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَرَّبَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ رَبِيعَةَ بْنَ أُمَيَّةَ فِي الْخَمْرِ إِلَى خَيْبَرَ، فَلَحِقَ بِهِرَقْلَ فَتَنَصَّرَ، فَقَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: لَا أُغَرِّبُ بَعْدَهُ مُسْلِمًا. (ن)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): ഉമർ(റ) മദ്യസംബന്ധമായ വിഷയത്തിൽ ഉമയ്യയുടെ മകൻ റബീഅയെ ഖൈബറിലേക്ക് നാടുകടത്തി. അനന്തരം അദ്ദേഹം ഹിർഖലുമായി ബന്ധപ്പെടുകയും ക്രിസ്ത്യാനിയാവുകയും ചെയ്തു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അദ്ദേഹത്തിനു ശേഷം ഒരു മുസ്‌ലിമിനെയും ഞാൻ നാടുകടത്തുകയില്ല. (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 595, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”لَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ، وَلَا يَشْرَبُ الْخَمْرَ شَارِبُهَا حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ، وَلَا يَسْرِقُ السَّارِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ، وَلَا يَنْتَهِبُ نُهْبَةً - ذَاتَ شَرَفٍ - يَرْفَعُ النَّاسُ - الْمُسْلِمُونَ - إِلَيْهِ فِيهَا أَبْصَارَهُمْ حِينَ يَنْتَهِبُهَا وَهُوَ مُؤْمِنٌ“. (خ,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അരുളി: “വിശ്വാസിയായി ഒരാൾ വ്യഭിചരിക്കുകയില്ല, വിശ്വാസിയായി ഒരാൾ കള്ള് കുടിക്കുകയില്ല, വിശ്വാസിയായി ഒരാൾ മോഷ്ടിക്കുകയില്ല, വിശ്വാസിയായി ഒരാൾ ജനങ്ങൾ (വിശ്വാസികൾ) നോക്കിനിൽക്കുന്ന സന്ദർഭത്തിൽ മാന്യമായതിനെ പിടിച്ചുപറിക്കുകയില്ല.” (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 595, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عُمَرَ وَنَفَرٍ مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - رَضِيَ اللَّهُ عَنْهُمْ - قَالُوا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ، ثُمَّ إِنْ شَرِبَ فَاجْلِدُوهُ، ثُمَّ إِنْ شَرِبَ فَاجْلِدُوهُ، ثُمَّ إِنْ شَرِبَ فَاقْتُلُوهُ“. (ن)', 'ഇബ്‌നുഉമർ(റ) നിന്നും മുഹമ്മദ് നബി(സ)യുടെ അനുചരന്മാരിൽ ഒരു വിഭാഗത്തിൽ നിന്നും നിവേദനം: റസൂൽ(സ) അരുളി: “ആരെങ്കിലും മദ്യപിച്ചാൽ നിങ്ങളവനെ (ചാട്ടവാറുകൊണ്ട്) അടിക്കുക. വീണ്ടും കുടിച്ചാൽ അപ്പോഴും അടിക്കുക. ഇനിയും മദ്യപിച്ചാൽ നിങ്ങളവനെ അടിക്കുക, വീണ്ടും അവൻ മദ്യപിച്ചാൽ നിങ്ങളവനെ വധിക്കുക.” (ന)', 'ابْنِ عُمَرَ وَنَفَرٍ مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 595, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا سَكِرَ فَاجْلِدُوهُ ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ، ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ. ثُمَّ قَالَ فِي الرَّابِعَةِ: فَاضْرِبُوا عُنُقَهُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ലഹരി ബാധിതനായാൽ നിങ്ങളവനെ (ചാട്ടവാർ കൊണ്ട്) അടിക്കുക. വീണ്ടും അവൻ ലഹരി ബാധിതനായാൽ അപ്പോഴും നിങ്ങളവനെ അടിക്കുക. പിന്നീടും അവൻ ലഹരി ബാധിതനായാൽ നിങ്ങളവനെ അടിക്കുക." ശേഷം നാലാം പ്രാവശ്യം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളവന്റെ കഴുത്തു വെട്ടുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 596, 596, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ أَنَّهُ كَانَ يَقُولُ: مَا أُبَالِي: شَرِبْتُ الْخَمْرَ، أَوْ عَبَدْتُ هَذِهِ السَّارِيَةَ مِنْ دُونِ اللَّهِ عَزَّ وَجَلَّ. (ن)', 'അബൂമൂസ(റ): അദ്ദേഹം പറയാറുണ്ടായിരുന്നു: ഞാൻ മദ്യപിക്കുന്നതിനെയോ, അല്ലാഹുവിനെ കൂടാതെ ഈ തൂണിനെ ആരാധിക്കുന്നതിനെയോ ഞാൻ പരിഗണിക്കുന്നില്ല (രണ്ടും തമ്മിൽ വ്യത്യാസമില്ല). (ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 596, 596, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنْ جَيْشَانَ - وَجَيْشَانُ مِنَ الْيَمَنِ - قَدِمَ فَسَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ شَرَابٍ يَشْرَبُونَهُ بِأَرْضِهِمْ مِنَ الذُّرَةِ، يُقَالُ لَهُ الْمِزْرُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمُسْكِرٌ هُوَ؟" قَالَ: نَعَمْ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ مُسْكِرٍ حَرَامٌ، إِنَّ اللهَ عَزَّ وَجَلَّ عَهْدٌ لِمَنْ شَرِبَ الْمُسْكِرَ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ". قَالُوا: يَا رَسُولَ اللهِ، وَمَا طِينَةُ الْخَبَالِ؟ قَالَ: "عَرَقُ أَهْلِ النَّارِ. أَوْ قَالَ: عُصَارَةُ أَهْلِ النَّارِ". (ن)', 'ജാബിർ(റ): ജയ്ശാൻകാരനായ ഒരാൾ (ജയ്ശാൻ, യമനിലെ ഒരുസ്ഥലമാണ്) വന്നിട്ട് അവരുടെ നാട്ടിൽ കുടിക്കാറുള്ള ചോളത്തിന്റെ പാനീയത്തെക്കുറിച്ച്, ''മിസ്ർ'' എന്നാണതിന്റെ പേര്, പ്രവാചകനോടു ചോദിച്ചു: അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അത് ലഹരിയുണ്ടാക്കുന്നതാണോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) അരുളി: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധമാണ്. ലഹരിയുണ്ടാക്കുന്നത് കുടിക്കുന്നവനെ ''ത്വീനതുൽ ഖബാലി''ൽ നിന്നും കുടിപ്പിക്കാൻ അല്ലാഹു ഉടമ്പടി ചെതിരിക്കുന്നു." അവർ ചോദിച്ചു: പ്രവാചകരെ, എന്താണ് ത്വീനത്തുൽ ഖബാൽ? റസൂൽ(സ) അരുൾ ചെയ്തു: "നരകവാസികളുടെ വിയർപ്പ്. അല്ലെങ്കിൽ നരകവാസികളുടെ ചീഞ്ചലം." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 596, 596, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَنْ شَرِبَ الْخَمْرَ فَلَمْ يَنْتَشِ لَمْ تُقْبَلْ لَهُ صَلَاةٌ مَا دَامَ فِي جَوْفِهِ أَوْ عُرُوقِهِ مِنْهَا شَيْءٌ، وَإِنْ مَاتَ مَاتَ كَافِرًا، وَإِنِ انْتَشَى لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً، وَإِنْ مَاتَ فِيهَا مَاتَ كَافِرًا. (ن)', 'ഇബ്നുഉമർ(റ): ഒരാൾ മദ്യപിച്ചിട്ട് ലഹരിയുണ്ടായിട്ടില്ലെങ്കിൽ, അവന്റെ ശരീരത്തിൽ മദ്യത്തിൽ നിന്ന് ഒരംശം ബാക്കിനിൽക്കെ അവന്റെ നമസ്കാരം സ്വീകരിക്കപ്പെടുകയില്ല. അവൻ മരിച്ചാൽ കാഫിറായി മരിക്കുന്നതാണ്. മറിച്ച് അവന് ലഹരിയുണ്ടായാൽ നാൽപ്പത് ദിവസം അവന്റെ ഒരു നമസ്കാരവും സ്വീകരിക്കപ്പെടുകയില്ല, അവൻ മരിച്ചാൽ കാഫിറായിട്ടായിരിക്കും മരിക്കുക. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 596, 596, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ شَرِبَ الْخَمْرَ فَجَعَلَهَا فِي بَطْنِهِ لَمْ يَقْبَلِ اللهُ مِنْهُ صَلَاةً سَبْعًا، إِنْ مَاتَ فِيهَا - فِيهِنَّ - مَاتَ كَافِرًا، فَإِنْ أَذْهَبَتْ عَقْلَهُ عَنْ شَيْءٍ مِنَ الْفَرَائِضِ - الْقُرْآنِ - لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ يَوْمًا، إِنْ مَاتَ فِيهَا - فِيهِنَّ - مَاتَ كَافِرًا". (ن)', 'അബ്ദുല്ലാഹിബ്നു അമ്ര് (റ): റസൂൽ(സ) അരുളി: "ആരെങ്കിലും മദ്യം ഉദരത്തിലാക്കിയാൽ അല്ലാഹു അവനിൽ നിന്ന് ഏഴു നമസ്കാരം സ്വീകരിക്കുകയില്ല. ആ അവസ്ഥയിൽ അവൻ മരണപ്പെട്ടാൽ സത്യനിഷേധിയായിട്ടായിരിക്കും അവന്റെ മരണം. നിർബന്ധ ബാധ്യതകളിൽ ഏതിനെയെങ്കിലും സംബന്ധിച്ചു അവന്റെ ബോധത്തെ അത് നഷ്ടപ്പെടുത്തിയാൽ അല്ലാഹു അവന്റെ നാല്പത് ദിവസത്തെ നമസ്കാരം സ്വീകരിക്കുകയില്ല. ഈ അവസ്ഥയിൽ മരണപ്പെട്ടാൽ സത്യനിഷേധിയായിട്ടാണ് അവൻ മരണപ്പെടുന്നത്."
(ന)', 'ابْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അമ്ര് (റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 596, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: اجْتَنِبُوا الْخَمْرَ، فَإِنَّهَا أُمُّ الْخَبَائِثِ، إِنَّهُ كَانَ رَجُلٌ مِمَّنْ خَلَا قَبْلَكُمْ تَعَبَّدَ، فَعَلِقَتْهُ امْرَأَةٌ غَوِيَّةٌ، فَأَرْسَلَتْ إِلَيْهِ جَارِيَتَهَا فَقَالَتْ لَهُ: إِنَّا نَدْعُوكَ لِلشَّهَادَةِ. فَانْطَلَقَ مَعَ جَارِيَتِهَا، فَطَفِقَتْ كُلَّمَا دَخَلَ بَابًا أَغْلَقَتْهُ دُونَهُ حَتَّى أَفْضَى إِلَى امْرَأَةٍ وَضِيئَةٍ، عِنْدَهَا غُلَامٌ وَبَاطِيَةُ خَمْرٍ، فَقَالَتْ: إِنِّي وَاللَّهِ مَا دَعَوْتُكَ لِلشَّهَادَةِ، وَلَكِنْ دَعَوْتُكَ لِتَقَعَ عَلَيَّ أَوْ تَشْرَبَ مِنْ هَذِهِ الْخَمْرَةِ كَأْسًا أَوْ تَقْتُلَ هَذَا الْغُلَامَ. قَالَ: فَاسْقِينِي مِنْ هَذَا الْخَمْرِ كَأْسًا. فَسَقَتْهُ كَأْسًا، قَالَ: زِيدُونِي. فَلَمْ يَرِمْ حَتَّى وَقَعَ عَلَيْهَا. وَقَتَلَ النَّفْسَ. فَاجْتَنِبُوا الْخَمْرَ، فَإِنَّهَا وَاللَّهِ لَا يَجْتَمِعُ الْإِيمَانُ وَإِدْمَانُ الْخَمْرِ إِلَّا لَيُوشِكُ أَنْ يُخْرِجَ أَحَدُهُمَا صَاحِبَهُ. (ن)', 'ഉസ്മാൻ(റ): നിങ്ങൾ മദ്യം വർജ്ജിക്കുക, കാരണമത് വൃത്തികേടുകളുടെ മാതാവാണ്. നിങ്ങളുടെ മുൻഗാമികളിൽ ആരാധനാനിമഗ്നനായ ഒരു വ്യക്തിയുണ്ടായിരുന്നു. അദ്ദേഹത്തോടു ഒരു വേശ്യക്ക് ഗാഢമായ അനുരാഗം തോന്നി. അങ്ങനെയവൾ തന്റെ തോഴിയെ അദ്ദേഹത്തിന്റെയടുക്കൽ അയച്ചിട്ട് നാം താങ്കളെ സത്യസാക്ഷ്യത്തിനുവേണ്ടി ക്ഷണിക്കുന്നുവെന്നു പറഞ്ഞു. അനന്തരമദ്ദേഹം അവരുടെ കൂടെ പോയി. അദ്ദേഹം ഓരോ വാതിൽ കടക്കുമ്പോഴും അവൾ ആ വാതിൽ അടച്ചുകൊണ്ടിരുന്നു. അങ്ങനെയദ്ദേഹം സുന്ദരിയായ ഒരു സ്ത്രീയുടെ അടുക്കൽ എത്തിച്ചേർന്നു. അവളുടെയടുക്കൽ ഒരടിമയും മദ്യത്തിന്റെ വലിയ സ്ഫടികപാത്രവും ഉണ്ട്. അവൾ പറഞ്ഞു: അല്ലാഹു സത്യം! തീർച്ചയായും ഞാൻ താങ്കളെ സത്യസാക്ഷ്യത്തിനുവേണ്ടിയല്ല ക്ഷണിച്ചത്. മറിച്ച് താങ്കൾ ഞാനുമായി (ലൈംഗിക) ബന്ധത്തിലേർപ്പെടുന്നതിനു വേണ്ടിയോ ഈമദ്യത്തിൽ നിന്ന് അൽപം നുകരുന്നതിനു വേണ്ടിയോ, ഈ അടിമയെ കൊല്ലുന്നതിനു വേണ്ടിയോ ആണ് ഞാൻ താങ്കളെ ക്ഷണിച്ചത്. അദ്ദേഹം പറഞ്ഞു: നീ ഈ മദ്യത്തിൽ നിന്ന് ഒരുകോപ്പ എന്നെകുടിപ്പിച്ചാലും. അങ്ങനെയവൾ അദ്ദേഹത്തെ ഒരു കോപ്പ കുടിപ്പിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഇനിയും തരൂ. അവളുമായി (ലൈംഗികമായി) ബന്ധപ്പെടുന്നതുവരെയും അടിമയെ വധിക്കുന്നതു വരെയും അദ്ദേഹം മദ്യപാനം തുടർന്നു. ആയതിനാൽ നിങ്ങൾ മദ്യം വർജ്ജിക്കുക. കാരണം അല്ലാഹു സത്യം, വിശ്വാസവും നിത്യ മദ്യസേവയും, ഒന്ന് മറ്റൊന്നിനെ സമീപ ഭാവിയിൽതന്നെ പുറത്താക്കിയിട്ടല്ലാതെ, ഒരുമിച്ചു കൂടുകയില്ല. (ന)', 'عُثْمَانَ', 'ഉസ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 597, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مُدْمِنُ الْخَمْرِ كَعَابِدِ وَثَنٍ" (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മദ്യം പതിവാക്കിയവൻ വിഗ്രഹാരാധകനെപ്പോലെയാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 597, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْجَنَّةَ مَنَّانٌ، وَلَا عَاقٌ، وَلَا مُدْمِنُ خَمْرٍ". وَفِي رِوَايَةٍ قَالَ: "مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، فَمَاتَ وَهُوَ يُدْمِنُهَا لَمْ يَتُبْ مِنْهَا، لَمْ يَشْرَبْهَا فِي الْآخِرَةِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) അരുളി: "ചെയ്ത ഉപകാരം വിളിച്ചുപറയുന്നവനും മാതാപിതാക്കളോടു അനുസരണക്കേട് കാണിക്കുന്നവനും മദ്യം നിത്യമായി സേവിക്കുന്നവനും സ്വർഗത്തിൽ പ്രവേശിക്കുകയില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=22), 1, 'وَفِي رِوَايَةٍ قَالَ: "مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا، فَمَاتَ وَهُوَ يُدْمِنُهَا لَمْ يَتُبْ مِنْهَا، لَمْ يَشْرَبْهَا فِي الْآخِرَةِ". (ن)', 'മറ്റൊരു നിവേദനം: "ആരെങ്കിലും ഇഹലോകത്ത് മദ്യപിക്കുകയും അതിൽനിന്നും ഖേദിച്ചുമടങ്ങാതെ അത് നിത്യമാക്കിയ നിലയിൽ മരണപ്പെടുകയും ചെയ്താൽ പരലോകത്തവൻ മദ്യം കുടിക്കുകയില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ مَالِكِ بْنِ أَبِي مَرْيَمَ قَالَ: دَخَلَ عَلَيْنَا عَبْدُ الرَّحْمَنِ بْنُ غَنْمٍ، فَتَذَاكَرْنَا الطِّلاَءَ، فَقَالَ: حَدَّثَنِي أَبُو مَالِكٍ الْأَشْعَرِيُّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيَشْرَبَنَّ نَاسٌ مِنْ أُمَّتِي الْخَمْرَ يُسَمُّونَهَا بِغَيْرِ اسْمِهَا". (د,جه)', 'മാലിക്ബ്നു അബീമർയം: ഞങ്ങളുടെയടുത്തേക്ക് അബ്ദുറഹ്മാനുബ്നു ഗനം കടന്നുവന്നു. അപ്പോൾ ഞങ്ങൾ ''തിലാഇ'' (ചൂടാക്കപ്പെട്ട മുന്തിരിച്ചാറ്) നെക്കുറിച്ചു കൂടിയാലോചിച്ചു. റസൂൽ(സ) പറയുന്നതു കേട്ടതായി അബൂമാലികിൽ അശ്അരി(റ) തന്നോടു ഉദ്ധരിച്ചത് തദവസരത്തിൽ അദ്ദേഹം പരാമർശിക്കുകയുണ്ടായി: "തീർച്ചയായും എന്റെ സമുദായത്തിൽ നിന്നൊരുവിഭാഗം മദ്യത്തിന് അതല്ലാത്തപേര് നൽകി അത് പാനംചെയ്യുന്നതാണ്." (ദ,ജ)', 'مَالِكِ بْنِ أَبِي مَرْيَمَ قَالَ', 'മാലിക്ബ്നു അബീമർയം', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "لَا تَذْهَبُ اللَّيَالِي وَالْأَيَّامُ حَتَّى تَشْرَبَ فِيهَا طَائِفَةٌ مِنْ أُمَّتِي الْخَمْرَ، يُسَمُّونَهَا بِغَيْرِ اسْمِهَا". [ز: في سنده ضعيف] (جه)', 'അബൂഉമാമതൽ ബാഹിലി(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ നിന്ന് ഒരു വിഭാഗം മദ്യത്തിനു മറ്റുനാമങ്ങൾ നൽകിക്കൊണ്ട് മദ്യം പാനം ചെയ്യുന്നത് വരെ കാലം കഴിഞ്ഞു പോവുകയില്ല." (സനദിൽ ബലഹീനതയുണ്ട്). (ജ)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതൽ ബാഹിലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنِ ابْنِ سِيرِينَ قَالَ: جَاءَ رَجُلٌ إِلَى ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: إِنَّ أَهْلَنَا يَنبِذُونَ لَنَا شَرَابًا عَشِيًّا، فَإِذَا أَصْبَحْنَا شَرِبْنَا. قَالَ: أَنْهَاكَ عَنِ الْمُسْكِرِ قَلِيلِهِ وَكَثِيرِهِ، وَأُشْهِدُ اللهَ عَلَيْكَ. أَنْهَاكَ عَنِ الْمُسْكِرِ قَلِيلِهِ وَكَثِيرِهِ، وَأُشْهِدُ اللهَ عَلَيْكَ. إِنَّ أَهْلَ خَيْبَرَ يَنْتَبِذُونَ شَرَابًا مِنْ كَذَا وَكَذَا، وَيُسَمُّونَهُ كَذَا وَكَذَا، وَهِيَ الْخَمْرُ. وَإِنَّ أَهْلَ فَدَكٍ يَنْتَبِذُونَ شَرَابًا مِنْ كَذَا وَكَذَا، يُسَمُّونَهُ كَذَا وَكَذَا، وَهِيَ الْخَمْرُ. حَتَّى عَدَّ أَشْرِبَةً أَرْبَعَةً أَحَدُهَا الْعَسَلُ. (ن)', 'ഇബ്നുസീരീൻ(റ): ഇബ്നുഉമർ(റ)വിന്റെയടുക്കൽ ഒരാൾ വന്നിട്ടു പറഞ്ഞു: ഞങ്ങളുടെ കുടുംബക്കാർ ഞങ്ങൾക്ക് വൈകുന്നേരം വീഞ്ഞുണ്ടാക്കുകയും പ്രഭാതത്തിൽ ഞങ്ങളത് പാനം ചെയ്യുകയും ചെയ്യാറുണ്ട്. ഇബ്നുഉമർ(റ) പറഞ്ഞു: അൽപമായാലും അധികമായാലും ലഹരിയുണ്ടാക്കുന്നതിനെ ഞാൻ നിരോധിക്കുകയും അല്ലാഹുവിനെ നിന്റെമേൽ സാക്ഷിയാക്കുകയും ചെയ്യുന്നു. അൽപമായാലും അധികമായാലും ലഹരിയുണ്ടാക്കുന്നതിനെ ഞാൻ നിരോധിക്കുകയും അല്ലാഹുവിനെ നിന്റെമേൽ സാക്ഷിയാക്കുകയും ചെയ്യുന്നു. നിശ്ചയം, ഖൈബർ വാസികൾ പലപല വസ്തുക്കളിൽനിന്ന് വീഞ്ഞുണ്ടാക്കുകയും അതിന് പലവിധത്തിലുള്ള പേരുകൾ നൽകുകയും ചെയ്യുന്നു. എന്നാലവ മദ്യമാകുന്നു. ഫദക് നിവാസികൾ ഇന്നയിന്ന വസ്തുക്കളിൽ നിന്ന് വീഞ്ഞുണ്ടാക്കുകയും അതിന് ഇന്നയിന്ന നാമങ്ങൾ നൽകുകയും ചെയ്യുന്നു. എന്നാലവ മദ്യമാകുന്നു. അങ്ങനെയദ്ദേഹം നാല് പാനീയങ്ങളെണ്ണി. അവയിലൊന്ന് തേനായിരുന്നു. (ന)', 'ابْنِ سِيرِينَ قَالَ', 'ഇബ്നുസീരീൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 598, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "لُعِنَتِ الْخَمْرُ عَلَى عَشَرَةِ أَوْجُهٍ: بِعَيْنِهَا، وَعَاصِرِهَا، وَمُعْتَصِرِهَا، وَبَائِعِهَا، وَمُبْتَاعِهَا، وَحَامِلِهَا، وَالْمَحْمُولَةِ إِلَيْهِ، وَآكِلِ ثَمَنِهَا، وَشَارِبِهَا، وَسَاقِيهَا". (د,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മദ്യം സ്വന്തംനിലക്ക്, അതുവാറ്റുന്നവൻ, വാറ്റിക്കുന്നവൻ, വിൽക്കുന്നവൻ, വാങ്ങുന്നവൻ, ചുമക്കുന്നവൻ, അത് ചുമക്കപ്പെടുന്നവർ, അതിന്റെ ഫലം കഴിക്കുന്നവർ, കുടിക്കുന്നവൻ, കുടിപ്പിക്കുന്നവൻ എന്നീ പത്ത് നിലക്ക് മദ്യം അഭിശപ്തമാണ്." (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ فِي الْخَمْرِ عَشَرَةً: عَاصِرَهَا، وَمُعْتَصِرَهَا، وَالْمَعْصُورَةَ لَهُ، وَحَامِلَهَا، وَالْمَحْمُولَةَ لَهُ، وَبَائِعَهَا، وَالْمَبْيُوعَةَ لَهُ، وَسَاقِيَهَا، وَالْمُسْتَقَاةَ لَهُ، حَتَّى عَدَّ عَشَرَةً مِنْ هَذَا الضَّرْبِ. (ت,جه)', 'അനസുബ്നുമാലിക്(റ): മദ്യത്തിന്റെ വിഷയത്തിൽ പത്ത് പേരെ റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു: വാറ്റുന്നവൻ, വാറ്റിക്കുന്നവൻ, ആർക്കുവേണ്ടിയാണോ വാറ്റുന്നത് അവൻ, മദ്യം ചുമക്കുന്നവൻ, ആർക്കുവേണ്ടിയാണോ ചുമക്കുന്നത് അവൻ, മദ്യം വിൽക്കുന്നവൻ, ആർക്കുവേണ്ടിയാണോ വിൽക്കുന്നത് അവൻ, കുടിപ്പിക്കുന്നവൻ, ആർക്കുവേണ്ടിയാണോ കുടിപ്പിക്കുന്നത് അവൻ. ഇങ്ങനെ പത്ത് വിഭാഗം ആളുകളെ അദ്ദേഹം എണ്ണി. (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ أَبَا طَلْحَةَ -رَضِيَ اللهُ عَنْهُمْ- سَأَلَ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَنْ أَيْتَامٍ وَرِثُوا خَمْرًا، قَالَ: "أَهْرِقْهَا". قَالَ: أَفَلَا أَجْعَلُهَا خَلًّا؟ قَالَ: "لَا". (م,د,ت)', 'അനസുബ്നു മാലിക്(റ): അബൂത്വൽഹ(റ) അനാഥകൾക്ക് അനന്തരാവകാശമായി ലഭിച്ച മദ്യത്തെക്കുറിച്ച് നബി(സ)യോടു ചോദിച്ചു: നബി(സ) പറഞ്ഞു: "അത് ഒഴിച്ചുകളയുക". അബൂത്വൽഹ(റ) ചോദിച്ചു; അത്. നിക്ക് സുർക്കയാക്കാമോ? റസൂൽ(സ) അരുളി: "ഇല്ല." (മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 599, 599, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ عَلَى مِنْبَرِ رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ قَدْ نَزَلَ تَحْرِيمُ الْخَمْرِ وَهِيَ مِنْ خَمْسَةِ أَشْيَاءَ الْعِنَبِ، وَالتَّمْرِ، وَالْحِنْطَةِ، وَالشَّعِيرِ، وَالْعَسَلِ، وَالْخَمْرُ مَا خَامَرَ الْعَقْلَ، وَثَلَاثٌ وَدِدْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يُفَارِقْنَا حَتَّى يَعْهَدَ إِلَيْنَا عَهْدًا الْجَدُّ وَالْكَلَالَةُ وَأَبْوَابٌ مِنْ أَبْوَابِ الرِّبَا قَالَ: قُلْتُ يَا أَبَا عَمْرٍو فَشَيْءٌ يُصْنَعُ بِالسِّنْدِ مِنَ الْأَرُزِّ، قَالَ: ذَاكَ لَمْ يَكُنْ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَوْ قَالَ: عَلَى عَهْدِ عُمَرَ، وَقَالَ حَجَّاجٌ عَنْ حَمَّادٍ عَنْ أَبِي حَيَّانَ مَكَانَ الْعِنَبِ الزَّبِيبَ. (ق)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)യുടെ മിമ്പറിൽ കയറി ഉമർ(റ) പ്രസംഗിച്ചു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും പുകഴ്ത്തുകയും ചെയ്തതിനു ശേഷം ഉമർ(റ) പ്രസ്താവിച്ചു: അറിയുക, മദ്യം നിഷിദ്ധമാക്കുന്ന സൂക്തം അവതരിച്ചു. അത് മുന്തിരി, കാരക്ക, ഗോതമ്പ്, ബാർലി, തേൻ എന്നീ അഞ്ച് വസ്തുക്കളിൽ നിന്നാകുന്നു. ബുദ്ധിയെ മന്ദീഭവിപ്പിക്കുന്നതാകുന്നു മദ്യം. പിതാമഹൻ, കലാലത്ത്(പിതാവോ പുത്രനോ അനന്തരാവകാശിയായി ഇല്ലാത്തയാൾ), പലിശയുടെ ചില അദ്ധ്യായങ്ങൾ തുടങ്ങിയ മൂന്നു വിഷയങ്ങളിൽ റസൂൽ(സ) നമ്മോട് പിരിയുന്നതിന് മുമ്പ് നമുക്ക് വ്യക്തമായ തീരുമാനം അറിയിച്ചു തന്നിരുന്നെങ്കിൽ എന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു. നിവേദകൻ തുടരുന്നു: ഞാൻ ചോദിച്ചു. അബൂ അംറൊ, അപ്പോൾ അരിയിൽ നിന്ന് സിൻദിലുണ്ടാക്കുന്ന വസ്തുവോ? അവർ പറഞ്ഞു: നബി(സ)യുടെ കാലത്ത് അല്ലെങ്കിൽ ഉമർ(റ)വിന്റെ കാലത്ത്, അത് ഉണ്ടായിരുന്നില്ല.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ الْحِنْطَةِ خَمْرًا، وَمِنَ الشَّعِيرِ خَمْرًا، وَمِنَ التَّمْرِ خَمْرًا، وَمِنَ الزَّبِيبِ خَمْرًا، وَمِنَ الْعَسَلِ خَمْرًا" (د,ت,ن,جه)', 'നൂഅ്മാനുബ്നു ബഷീർ(റ): റസൂൽ(സ) അരുളി: "ഗോതമ്പ്കൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്, ബാർളികൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്, കാരക്കകൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്, ഉണക്കമുന്തിരികൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്, തേനുകൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്." (ദ,തു,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നൂഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ الْعِنَبِ خَمْرًا، وَإِنَّ مِنَ التَّمْرِ خَمْرًا، وَإِنَّ مِنَ الْعَسَلِ خَمْرًا، وَإِنَّ مِنَ الْبُرِّ خَمْرًا، وَإِنَّ مِنَ الشَّعِيرِ خَمْرًا". (د,ت,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുന്തിരികൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്, കാരക്കകൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്, തേനുകൊണ്ട് മദ്യമുണ്ടാക്കുന്നുണ്ട്, ധാന്യത്തിൽനിന്ന് മദ്യമുണ്ടാക്കുന്നുണ്ട്, ബാർളിയിൽ നിന്ന് മദ്യമുണ്ടാക്കുന്നുണ്ട്,." (ദ,തു,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الْخَمْرَ مِنَ الْعَصِيرِ، وَالتَّمْرِ، وَالْحِنْطَةِ، وَالشَّعِيرِ، وَالذُّرَةِ، وَإِنِّي أَنْهَاكُمْ عَنْ كُلِّ مُسْكِرٍ". (د)', 'നുഅ്മാനുബ്നു ബശീർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പിഴിഞ്ഞെടുത്തനീര്, ഉണക്കമുന്തിരി, കാരക്ക, ഗോതമ്പ്, ബാർലി, ചോളം എന്നിവയിൽ നിന്നുണ്ടാക്കുന്നതാകുന്നു മദ്യം. തീർച്ചയായും ലഹരിയുണ്ടാക്കുന്നതിനെയെല്ലാം ഞാൻ നിങ്ങൾക്ക് നിരോധിക്കുന്നു." (ദ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ: النَّخْلَةُ وَالْعِنَبَةُ". حَسَنٌ صَحِيحٌ . (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അരുളി: "മദ്യം ഈത്തപ്പന, മുന്തിരി എന്നീ രണ്ട് മരങ്ങളിൽ നിന്നാകുന്നു." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا أَنَا قَائِمٌ عَلَى الْحَيِّ - عَلَى عُمُومَتِي، وَأَنَا أَصْغَرُهُمْ سِنًّا - إِذْ جَاءَ رَجُلٌ فَقَالَ: إِنَّهَا قَدْ حُرِّمَتِ الْخَمْرُ. وَأَنَا قَائِمٌ عَلَيْهِمْ أَسْقِيهِمْ مِنْ فَضِيخٍ لَهُمْ، فَقَالُوا: اكْفَأْهَا. فَكَفَأْتُهَا. قِيلَ لِأَنَسٍ: مَا هُوَ؟ قَالَ الْبُسْرُ وَالتَّمْرُ. (ن)', 'അനസുബ്നു മാലിക്(റ): ഗോത്രത്തിൽ എന്റെ പിതൃസഹോദരന്മാരോടൊപ്പം അവരിൽ ഏറ്റവും പ്രായം കുറഞ്ഞവനായ ഞാൻ നിൽക്കുമ്പോൾ ഒരാൾ വന്നിട്ടു പറഞ്ഞു: നിശ്ചയം മദ്യം നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കുന്നു. ഞാൻ ആ സന്ദർഭത്തിൽ അവർക്ക് ഈത്തപ്പഴവീഞ്ഞ് കുടിപ്പിക്കുകയായിരുന്നു. അപ്പോൾ അവർ പറഞ്ഞു: നീയത് ഒഴിച്ച് കളയുക. അങ്ങനെ ഞാനത് ഒഴിച്ചുകളഞ്ഞു. അനസ്(റ)വിനോടു ചോദിച്ചു: അതെന്താണ്? അദ്ദേഹം മറുപടി നൽകി: പഴുക്കാത്ത ഈത്തപ്പഴവും കാരക്കയും. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 600, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَسْقِي أَبَا طَلْحَةَ وَأُبَيَّ بْنَ كَعْبٍ وَأَبَا دُجَانَةَ فِي رَهْطٍ مِنَ الْأَنْصَارِ، فَدَخَلَ عَلَيْنَا رَجُلٌ فَقَالَ: حَدَثَ خَبَرٌ، نَزَلَ تَحْرِيمُ الْخَمْرِ. فَكَفَأْنَا، قَالَ: وَمَا هِيَ يَوْمَئِذٍ إِلَّا الْفَضِيخُ: خَلِيطُ الْبُسْرِ وَالتَّمْرِ. وَقَالَ أَنَسٌ: لَقَدْ حُرِّمَتِ الْخَمْرُ وَإِنَّ عَامَّةَ خُمُورِهِمْ يَوْمَئِذٍ الْفَضِيخُ. وَفِي رِوَايَةٍ قَالَ: حُرِّمَتِ الْخَمْرُ حِينَ حُرِّمَتْ وَإِنَّهُ لَشَرَابُهُمُ: الْبُسْرُ وَالتَّمْرُ. (ن)', 'അനസ്(റ): അൻസാരികളുടെ ഒരു കൂട്ടത്തിൽ വെച്ച് അബൂത്വൽഹ(റ), ഉബയ്യുബ്നു കഅ്ബ്(റ), അബൂ ദുജാന(റ) എന്നിവർക്ക് ഞാൻ കുടിപ്പിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ വന്നുപറഞ്ഞു: ഒരു വാർത്തയുണ്ട്, മദ്യം നിഷിദ്ധമാക്കുന്ന സൂക്തം ഇറങ്ങിയിരിക്കുന്നു. അനസ്(റ) പറയുന്നു: അപ്പോൾ ഞങ്ങളത് ഒഴിച്ചുകളഞ്ഞു. അത് ഈത്തപ്പഴ വീഞ്ഞായിരുന്നു, പഴുക്കാത്ത ഈത്തപ്പഴത്തിന്റെയും കാരക്കയുടെയും മിശ്രിതം. മദ്യം നിഷിദ്ധമാക്കിയ സമയത്ത് ഈത്തപ്പഴ വീഞ്ഞായിരുന്നു കൂടുതൽ വ്യാപകമായ മദ്യം.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=35), 1, 'وَفِي رِوَايَةٍ قَالَ: حُرِّمَتِ الْخَمْرُ حِينَ حُرِّمَتْ وَإِنَّهُ لَشَرَابُهُمُ: الْبُسْرُ وَالتَّمْرُ. (ن)', 'മറ്റൊരു നിവേദനം: മദ്യം നിഷിദ്ധമാക്കപ്പെട്ടപ്പോൾ അവരുടെ പാനീയം പഴുക്കാത്ത ഈത്തപ്പഴത്തിന്റെയും കാരക്കയുടേതുമായിരുന്നു.(ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَلِيٍّ كَرَّمَ اللهُ وَجْهَهُ قَالَ: نَهَانِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ حَلْقَةِ الذَّهَبِ، وَالْقَسِّيِّ، وَالْمِيثَرَةِ، وَالْجِعَةِ. (ن)', 'അലി(റ): സ്വർണ്ണച്ചുറ്റും, പട്ടുകൊണ്ടു നെയ്തവസ്ത്രവും, പട്ടിന്റെ ജീനിയും ബാർലികൊണ്ടുണ്ടാക്കുന്ന മദ്യവും റസൂൽ(സ) എനിക്ക് നിരോധിച്ചിരുന്നു. (ന)', 'عَلِيٍّ كَرَّمَ اللهُ وَجْهَهُ قَالَ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 601, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ، فَقُلْتُ: يَا رَسُولَ اللهِ، إِنَّ بِهَا أَشْرِبَةً، فَمَا أَشْرَبُ وَمَا أَدَعُ؟ قَالَ: "وَمَا هِيَ؟". قُلْتُ: الْبِتْعُ، وَالْمِزْرُ. قَالَ: "وَمَا الْبِتْعُ وَالْمِزْرُ؟". قُلْتُ: أَمَّا الْبِتْعُ فَنَبِيذُ الْعَسَلِ، وَأَمَّا الْمِزْرُ فَنَبِيذُ الذُّرَةِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَشْرَبْ مُسْكِرًا، فَإِنِّي حَرَّمْتُ كُلَّ مُسْكِرٍ". وفي رواية قال: "وَمَا الْبِتْعُ وَالْمِزْرُ؟". قُلْتُ: شَرَابٌ يَكُونُ مِنَ الْعَسَلِ، وَالْمِزْرُ يَكُونُ مِنَ الشَّعِيرِ. قَالَ: "كُلُّ مُسْكِرٍ حَرَامٌ". (ن)', 'അബൂമൂസ(റ): റസൂൽ(സ) എന്നെ യമനിലേക്ക് നിയോഗിച്ചപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടെ വിവിധതരം പാനീയങ്ങളുണ്ട്, ഞാൻ കുടിക്കുകയും ഉപേക്ഷിക്കുകയും ചെയ്യേണ്ടത് ഏതെല്ലാമാണ്? റസൂൽ(സ) ചോദിച്ചു: "ആ പാനീയങ്ങൾ ഏതെല്ലാമാണ്?" ഞാൻ പറഞ്ഞു: ബിത്ളം മിസ്റും. റസൂൽ(സ) ചോദിച്ചു: "ബിത്ളം മിസ്റും എന്നാൽ എന്താണ്?" ഞാൻ പറഞ്ഞു: ബ്ത്അ് എന്നത് തേൻ വീഞ്ഞാണ്. മിസ്റ് എന്നത് ചോളത്തിന്റെ വീഞ്ഞാണ്. തദവസരം അവിടനരുളി: "ലഹരിയുണ്ടാക്കുന്നത് നീ കുടിക്കരുത്. തീർച്ചയായും ലഹരിയുണ്ടാക്കുന്നതെല്ലാം ഞാൻ നിഷിദ്ധമാക്കിയിരിക്കുന്നു."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=37), 1, 'وَفِي رِوَايَةٍ قال: "وَمَا الْبِتْعُ وَالْمِزْرُ؟". قُلْتُ: شَرَابٌ يَكُونُ مِنَ الْعَسَلِ، وَالْمِزْرُ يَكُونُ مِنَ الشَّعِيرِ. قَالَ: "كُلُّ مُسْكِرٍ حَرَامٌ". (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) ചോദിച്ചു: "എന്താണ് ബിത്ളം മിസ്റും" ഞാൻ പറഞ്ഞു: ബിത്അ് തേൻകൊണ്ടുണ്ടാക്കുന്ന പാനീയവും, മിസ്റ് ബാർലി ഉപയോഗിച്ചുണ്ടാക്കുന്ന പാനീയവും. തിരുമേനി(സ) പറഞ്ഞു: "ലഹരി ഉണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا نَزَلَتِ الْآيَاتُ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي الرِّبَا خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَرَّمَ التِّجَارَةَ فِي الْخَمْرِ. (ق,د,ن,جه)', 'ആയിശ(റ): അൽബഖറ സൂറത്തിലെ പലിശ സംബന്ധമായ സൂക്തങ്ങൾ അവതരിച്ചപ്പോൾ റസൂൽ(സ) പുറത്തുവന്നു മദ്യവ്യാപാരം നിഷിദ്ധമാക്കി. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَلَغَ عُمَرَ أَنَّ سَمُرَةَ بَاعَ خَمْرًا، فَقَالَ: قَاتَلَ اللَّهُ سَمُرَةَ، أَلَمْ يَعْلَمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَعَنَ اللَّهُ الْيَهُودَ، حُرِّمَتْ عَلَيْهِمُ الشُّحُومُ، فَجَمَلُوهَا فَبَاعُوهَا". (ق,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): സമറത്ത് മദ്യം വിറ്റുവെന്ന റിപ്പോർട്ട് ഉമർ(റ)വിന് ലഭിച്ചപ്പോൾ ഉമർ(റ) പറഞ്ഞു: സമറയെ അല്ലാഹു നശിപ്പിക്കട്ടെ. "ജൂതന്മാരെ അല്ലാഹു ശപിച്ചു. കൊഴുപ്പ് അവർക്ക് നിഷിദ്ധമാക്കപ്പെട്ടു, പക്ഷെ അവരത് കൊണ്ടുനടക്കുകയും വിൽക്കുകയും ചെയ്തു" എന്ന് റസൂൽ(സ) പറഞ്ഞത് സമറക്കറിയില്ലേ? (ബു,മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ وَائِلٍ الْحَضْرَمِيِّ: أَنَّ طَارِقَ بْنَ سُوَيْدٍ الْجُعْفِيَّ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَمْرِ، فَنَهَاهُ - أَوْ كَرِهَ - أَنْ يَصْنَعَهَا، فَقَالَ: إِنَّمَا أَصْنَعُهَا لِلدَّوَاءِ، فَقَالَ: "إِنَّهُ لَيْسَ بِدَوَاءٍ وَلَكِنَّهُ دَاءٌ". (م)', 'വാഇലുൽ ഹള്റമി(റ): ത്വാരിഖ്ബ്നു സുവൈദുൽ ജുഅ്ഫി(റ) മദ്യത്തെക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിച്ചു. അതുണ്ടാക്കുന്നത് അവിടന്ന് നിരോധിച്ചു. അല്ലെങ്കിൽ അതിഷ്ടപ്പെട്ടില്ല. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അസുഖത്തിനുവേണ്ടി മാത്രമാണ് ഞാനത് ഉണ്ടാക്കുന്നത്. അപ്പോൾ റസൂൽ(സ) പ്രതിവചിച്ചു: "നിശ്ചയമത് ഔഷധമല്ല, രോഗമാണ്." (മു)', 'وَائِلٍ الْحَضْرَمِيِّ', 'വാഇലുൽ ഹള്റമി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَمُعَاذَ إِلَى الْيَمَنِ، فَقَالَ مُعَاذٌ: إِنَّكَ تَبْعَثُنَا إِلَى أَرْضٍ كَثِيرٌ شَرَابُ أَهْلِهَا، فَمَا أَشْرَبُ؟ قَالَ: "اشْرَبْ. وَلَا تَشْرَبْ مُسْكِرًا". (ن)', 'അബൂമൂസ(റ): റസൂൽ(സ) എന്നെയും മുആദിനെയും യമനിലേക്ക് അയച്ചു. അപ്പോൾ മുആദ് ചോദിച്ചു: അധികപേരും മദ്യം കഴിക്കുന്ന നാട്ടിലേക്കാണ് താങ്കൾ ഞങ്ങളെ നിയോഗിക്കുന്നത്. അപ്പോൾ ഞാനെന്ത് കുടിക്കും? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പാനം ചെയ്യുക, ലഹരിയുണ്ടാകുന്നത് കുടിക്കരുത്." (ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ مُسْكِرٍ خَمْرٌ، وَكُلُّ مُسْكِرٍ حَرَامٌ، وَمَنْ مَاتَ وَهُوَ يَشْرَبُ الْخَمْرَ يُدْمِنُهَا لَمْ يَشْرَبْهَا فِي الْآخِرَةِ". (م, د, ت, ن)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം മദ്യമാകുന്നു. ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധവുമാണ്. മദ്യം പതിവാക്കിയ നിലയിൽ ആരെങ്കിലും മരണപ്പെട്ടാൽ പരലോകത്തവനത് പാനം ചെയ്യുകയില്ല." (മു,ദ,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 602, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ مُخَمِّرٍ خَمْرٌ، وَكُلُّ مُسْكِرٍ حَرَامٌ، وَمَنْ شَرِبَ مُسْكِرًا بُخِسَتْ صَلَاتُهُ أَرْبَعِينَ صَبَاحًا، فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ، فَإِنْ عَادَ الرَّابِعَةَ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ". قِيلَ: وَمَا طِينَةُ الْخَبَالِ يَا رَسُولَ اللَّهِ؟ قَالَ: "صَدِيدُ أَهْلِ النَّارِ. وَمَنْ سَقَاهُ صَغِيرًا لَا يَعْرِفُ حَلَالَهُ مِنْ حَرَامِهِ كَانَ حَقًّا عَلَى اللَّهِ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ". (د,ت,جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ബുദ്ധിയെ ലഹരി പിടിപ്പിക്കുന്നതെല്ലാം മദ്യമാകുന്നു. ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധവുമാണ്. ആരെങ്കിലും ലഹരിയുണ്ടാക്കുന്നതിനെ പാനം ചെയ്താൽ നാല്പത് ദിവസത്തെ നമസ്കാരം അപൂർണ്ണമാകുന്നതാണ്. അവൻ പശ്ചാത്തപിച്ചാൽ അല്ലാഹു അവന്റെ പശ്ചാത്താപം സ്വീകരിക്കുന്നതാണ്. നാലാം പ്രാവശ്യം അവൻ മടങ്ങിയാൽ ''ത്വീനതുൽ ഖബാലി''ൽ നിന്നു അവനെ കുടിപ്പിക്കൽ അല്ലാഹുവിന്റെ ബാധ്യതയാണ്." ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ''ത്വീനതുൽ ഖബാൽ'' എന്നാലെന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "നരകവാസികളുടെ ചീഞ്ചലമാണത്. ഹലാലും ഹറാമും തിരിച്ചറിയാത്ത ചെറിയ കുട്ടിയെ ആരെങ്കിലും മദ്യം കുടിപ്പിച്ചാൽ ''ത്വീനത്തുൽ ഖബാലി''ൽ നിന്നും അവനെ കുടിപ്പിക്കൽ അല്ലാഹുവിന്റെ ബാധ്യതയാണ്." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلُّ مُسْكِرٍ حَرَامٌ عَلَى كُلِّ مُؤْمِنٍ". (جه)', 'മുആവിയ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ ശ്രവിച്ചു: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം എല്ലാ സത്യവിശ്വാസികൾക്കും നിഷിദ്ധമാണ്." (ജ)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبِتْعِ، فَقَالَ: "كُلُّ شَرَابٍ أَسْكَرَ فَهُوَ حَرَامٌ". زَادَ الزُّهْرِيُّ فِي رِوَايَةٍ: وَالْبِتْعُ نَبِيذُ الْعَسَلِ، كَانَ أَهْلُ الْيَمَنِ يَشْرَبُونَهُ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): തേൻ വീഞ്ഞിനെ സംബന്ധിച്ച് റസൂൽ(സ)യോട് ചോദിച്ചു. അവിടുന്ന് പറഞ്ഞു: "ലഹരിയുണ്ടാക്കുന്ന പാനീയമെല്ലാം നിഷിദ്ധംതന്നെ." മറ്റൊരു നിവേദനത്തിൽ സുഹ്‌രി കൂടുതലായി ഉദ്ധരിക്കുന്നു: ''ബിത്അ്'' എന്നാൽ തേൻ വീഞ്ഞാകുന്നു. യമൻകാർ ഈ മദ്യമാണ് കഴിക്കാറുണ്ടായിരുന്നത്. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 603, 603, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=45), 1, null, 'മറ്റൊരു നിവേദനത്തിൽ സുഹ്‌രി കൂടുതലായി ഉദ്ധരിക്കുന്നു: ''ബിത്അ്'' എന്നാൽ തേൻ വീഞ്ഞാകുന്നു. യമൻകാർ ഈ മദ്യമാണ് കഴിക്കാറുണ്ടായിരുന്നത്. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ دَيْلَمَ الْحِمْيَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّا بِأَرْضٍ بَارِدَةٍ نُعَالِجُ فِيهَا عَمَلًا شَدِيدًا، وَإِنَّا نَتَّخِذُ شَرَابًا مِنْ هَذَا الْقَمْحِ، نَتَقَوَّى بِهِ عَلَى أَعْمَالِنَا وَعَلَى بَرْدِ بِلَادِنَا؟ قَالَ: "هَلْ يُسْكِرُ؟". قُلْتُ: نَعَمْ، قَالَ: "فَاجْتَنِبُوهُ". قَالَ: قُلْتُ: فَإِنَّ النَّاسَ غَيْرُ تَارِكِيهِ؟ قَالَ: "فَإِنْ لَمْ يَتْرُكُوهُ فَقَاتِلُوهُمْ". (د)', 'ദയ്‌ലമുൽ ഹിംയരി(റ): ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചു; പ്രവാചകരേ, പ്രയാസകരമായ ജോലി കൈകാര്യം ചെയ്യുന്ന ശൈത്യപ്രദേശത്തുള്ളവരാണു ഞങ്ങൾ. ഈ ഗോതമ്പിൽ നിന്നു ഞങ്ങളൊരു പാനീയം ഉണ്ടാക്കുകയും അതു മുഖേന ഞങ്ങളുടെ ജോലികൾക്കും നാട്ടിലുള്ള ശൈത്യത്തെ നേരിടുന്നതിന്നും ശക്തിയാർജ്ജിക്കുകയും ചെയ്യുന്നു. റസൂൽ(സ) ചോദിച്ചു: "അത് മത്തുണ്ടാക്കുമോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "എങ്കിൽ നിങ്ങളത് വെടിയുക." നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: ജനം അതിനെ ഉപേക്ഷിക്കാത്തവരാണെങ്കിലോ? റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾ അതിനെ ഉപേക്ഷിച്ചില്ലെങ്കിൽ നിങ്ങൾ അവരോട് യുദ്ധം ചെയ്യുക." (ദ)', 'دَيْلَمَ الْحِمْيَرِيِّ', 'ദയ്‌ലമുൽ ഹിംയരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 603, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَرَابٍ مِنَ الْعَسَلِ، فَقَالَ: "ذَاكَ الْبِتْعُ". قُلْتُ: وَيُنْتَبَذُ مِنَ الشَّعِيرِ وَالذُّرَّةِ؟ فَقَالَ: "ذَلِكَ الْمِزْرُ". ثُمَّ قَالَ: "أَخْبِرْ قَوْمَكَ أَنَّ كُلَّ مُسْكِرٍ حَرَامٌ". (ق،د،ن)', 'അബൂമൂസ(റ): തേനിനാലുള്ള മദ്യത്തെസംബന്ധിച്ചു ഞാൻ നബി(സ)യോട് ചോദിച്ചു. അവിടുന്ന് പറഞ്ഞു: "അത് ''ബിത്അ്'' ആണ്." ഞാൻ ചോദിച്ചു. ഗോതമ്പിൽനിന്നും ചോളത്തിൽ നിന്നും ലഹരി പാനീയം ഉണ്ടാക്കപ്പെടുമോ? റസൂൽ(സ) പറഞ്ഞു: "അത് ''മിസ്ർ'' ആണ്." ശേഷം റസൂൽ(സ) അരുളി: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധമാണെന്നു നീ നിന്റെ സമൂഹത്തെ അറിയിക്കുക." (ബു,മു,ദ,ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْخَمْرِ وَالْمَيْسِرِ وَالْكُوبَةِ وَالْغُبَيْرَاءِ، وَقَالَ: "كُلُّ مُسْكِرٍ حَرَامٌ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): മദ്യം, ചൂതാട്ടം, ചതുരംഗക്കളി, ചോളത്തിൽനിന്നുണ്ടാക്കുന്ന ലഹരിപാനീയം എന്നിവ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. റസൂൽ(സ) തുടർന്നു പറഞ്ഞു: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധമാകുന്നു." (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كُلِّ مُسْكِرٍ وَمُفَتِّرٍ. (د)', 'ഉമ്മുസലമ(റ): ലഹരി പിടിപ്പിക്കുകയും ശരീരത്തെ തളർത്തുകയും ചെയ്യുന്ന എല്ലാറ്റിനെയും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلُّ مُسْكِرٍ حَرَامٌ، وَمَا أَسْكَرَ مِنْهُ الْفَرَقُ فَمِلْءُ الْكَفِّ مِنْهُ حَرَامٌ". (د،ت)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധമാകുന്നു. ഒരു ഫറഖ് (ഏകദേശം പതിനാറ് റാത്തൽ) ലഹരിയുണ്ടാക്കുന്നതാണെങ്കിൽ അതിൽനിന്ന് കൈ നിറച്ച് കോരിയാൽ കിട്ടുന്നതുപയോഗിക്കുന്നതും നിഷിദ്ധമാണ." (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ". حَسَنٌ. (د،ت،ن،جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "ഏതൊന്നു കൂടുതലായാൽ ലഹരിയുണ്ടാക്കുന്നവോ അതിന്റെ അൽപവും നിഷിദ്ധമാണ്." (ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 604, 604, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَنْهَاكُمْ عَنْ قَلِيلِ مَا أَسْكَرَ كَثِيرُهُ". وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ قَلِيلِ مَا أَسْكَرَ كَثِيرُهُ. (ن)', 'സഅ്ദുബ്‌നു അബീവഖാസ്(റ): നബി(സ) പറഞ്ഞു: "ഏതൊന്നിന്റെ കൂടുതൽ ലഹരിയുണ്ടാക്കുന്നുവോ അതിന്റെ അല്പത്തേയും ഞാൻ നിങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നു." മറ്റൊരു നിവേദനം: ഏതൊന്നിന്റെ കൂടുതൽ ലഹരിയുണ്ടാക്കുന്നുവോ അതിന്റെ കുറഞ്ഞതിനെയും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ന)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്‌നു അബീവഖാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 604, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=52), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ قَلِيلِ مَا أَسْكَرَ كَثِيرُهُ. (ن)', 'മറ്റൊരു നിവേദനം: ഏതൊന്നിന്റെ കൂടുതൽ ലഹരിയുണ്ടാക്കുന്നുവോ അതിന്റെ കുറഞ്ഞതിനെയും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ أَنْ نَجْمَعَ شَيْئَيْنِ نَبِيذًا، يَبْغِي أَحَدُهُمَا عَلَى صَاحِبِهِ. قَالَ: وَسَأَلْتُهُ عَنِ الْفَضِيخِ، فَنَهَانِي عَنْهُ. قَالَ: كَانَ يَكْرَهُ الْمُذَنَّبَ مِنَ الْبُسْرِ، مَخَافَةَ أَنْ يَكُونَا شَيْئَيْنِ، فَكُنَّا نَقْطَعُهُ. (ن)', 'അനസുബ്‌നു മാലിക്(റ): ഒന്ന് മറ്റൊന്നിന് വീര്യം നൽകുമെന്നതിനാൽ രണ്ട് വസ്തുക്കളെ ഒരുമിച്ച് ചേർത്തു വീഞ്ഞുണ്ടാക്കുന്നത് റസൂൽ(സ) വിലക്കിയിരുന്നു. അനസ്(റ) പറയുന്നു: പച്ച ഈത്തപ്പഴത്തിന്റെ വീഞ്ഞിനെക്കുറിച്ച് പ്രവാചകൻ(സ)യോട് ഞാൻ അന്വേഷിച്ചു. അപ്പോൾ റസൂൽ(സ) എനിക്കത് നിരോധിച്ചു. അനസ്(റ) പറയുന്നു: രണ്ടും രണ്ട് വസ്തുക്കളാകുമോയെന്ന ഭയം കാരണം പച്ച ഈത്തപ്പഴത്തിൽ നിന്നുള്ള പഴുത്ത ഭാഗം റസൂൽ(സ) വെറുത്തിരുന്നു. ആയതിനാൽ ഞങ്ങളത് മുറിച്ചെടുക്കുമായിരുന്നു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنِ ابْنِ عَبَّاسٍ رضي الله عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ، وَعَنِ الْبُسْرِ وَالتَّمْرِ أَنْ يُخْلَطَا، وَعَنِ الزَّبِيبِ وَالتَّمْرِ أَنْ يُخْلَطَا، وَكَتَبَ إِلَى أَهْلِ هَجَرَ: "أَنْ لَا تَخْلِطُوا الزَّبِيبَ وَالتَّمْرَ جَمِيعًا". (ن)', 'ഇബ്‌നുഅബ്ബാസ്(റ): ചുരങ്ങാപാത്രം, പച്ച ഭരണി, ടാർപൂശിയ പാത്രം, ഈത്തപ്പന തുരന്നുണ്ടാക്കിയ പാത്രം, കാരക്കയും പഴുക്കാത്ത ഈത്തപ്പഴവും കൂട്ടിക്കലർത്തി മദ്യമുണ്ടാക്കൽ, ഉണക്കമുന്തിരിയും കാരക്കയും കൂട്ടിക്കലർത്തി മദ്യമുണ്ടാക്കൽ എന്നിവ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. ഹജറുകാരിലേക്ക് റസൂൽ(സ) എഴുതുകയും ചെയ്തു: "നിങ്ങൾ ഉണക്കമുന്തിരിയും കാരക്കയും (മദ്യമുണ്ടാക്കാൻ) ഒന്നായി കൂട്ടിക്കലർത്തരുത്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: الْبُسْرُ وَحْدَهُ حَرَامٌ، وَمَعَ التَّمْرِ حَرَامٌ. (ن)', 'ഇബ്‌നുഅബ്ബാസ്(റ): പഴുക്കാത്ത ഈത്തപ്പഴം തനിയെ നിഷിദ്ധമാണ്. അത് കാരക്കയോട് കൂടിയും നിഷിദ്ധം തന്നെ. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُنْبَذَ الْبُسْرُ وَالرُّطَبُ جَمِيعًا. حسن صحيح. (ق,د,ت,ن,جه)', 'ജാബിറുബ്‌നു അബ്ദില്ല(റ): പഴുക്കാത്ത ഈത്തപ്പഴത്തിൽ നിന്നും പഴുത്ത് പാകമായ ഈത്തപ്പഴത്തിൽ നിന്നും ഒരുമിച്ച് ലഹരിപാനീയമുണ്ടാക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്‌നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 605, 605, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْبُسْرِ وَالتَّمْرِ أَنْ يُخْلَطَ بَيْنَهُمَا، وَنَهَى عَنِ الزَّبِيبِ وَالتَّمْرِ أَنْ يُخْلَطَ بَيْنَهُمَا، وَنَهَى عَنِ الْجِرَارِ أَنْ يُنْبَذَ فِيهَا. حَسَنٌ صَحِيحٌ. (م,ت)', 'അബൂസഈദ്(റ): പഴുക്കാത്ത ഈത്തപ്പഴവും കാരക്കയും (മദ്യമുണ്ടാക്കാൻ) കൂട്ടിക്കലർത്തൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. ഉണക്കമുന്തിരിയും കാരക്കയും കൂട്ടിക്കലർത്തലും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. മൺഭരണികളിൽ ലഹരി പാനീയം നിർമ്മിക്കലും അവിടുന്ന് വിലക്കി. (മു,തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 605, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَرِبَ النَّبِيذَ مِنْكُمْ فَلْيَشْرَبْهُ زَبِيبًا فَرْدًا، أَوْ تَمْرًا فَرْدًا، أَوْ بُسْرًا فَرْدًا". (م)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) അരുളി: "നിങ്ങളിൽ നിന്നാരെങ്കിലും നീര് പാനം ചെയ്യുന്നുവെങ്കിൽ ഉണക്കമുന്തിരി മാത്രമായിട്ടോ, കാരക്ക മാത്രമായിട്ടോ, പഴുക്കാത്ത ഈത്തപ്പഴം മാത്രമായിട്ടോ പാനം ചെയ്തുകൊള്ളട്ടെ." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ كَبْشَةَ بِنْتِ أَبِي مَرْيَمَ قَالَتْ: سَأَلْتُ أُمَّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: مَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْهُ؟ قَالَتْ: كَانَ يَنْهَانَا أَنْ نَعْجَمَ النَّوَى طَبْخًا، أَوْ نَخْلِطَ الزَّبِيبَ وَالتَّمْرَ. (د)', 'കബ്ശ ബിൻത് അബീമർയം(റ): ഉമ്മുസലമ(റ)യോടു ഞാൻ ചോദിച്ചു: റസൂൽ(സ) നിരോധമേർപ്പെടുത്തിയിരുന്നത് എന്തിനെ കുറിച്ചായിരുന്നു? അവർ പ്രതിവചിച്ചു: ഈത്തപ്പനക്കുരു പാകംചെയ്ത് നല്ലപോലെ വേവിക്കുന്നതിനെയും ഉണക്കമുന്തിരിയും കാരക്കയും കൂട്ടിക്കലർത്തലിനെയും റസൂൽ(സ) ഞങ്ങളോട് വിലക്കിയിരുന്നു. (ദ)', 'كَبْشَةَ بِنْتِ أَبِي مَرْيَمَ قَالَتْ', 'കബ്ശ ബിൻത് അബീമർയം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُنْبَذُ لَهُ زَبِيبٌ فَيُلْقِي فِيهِ تَمْرًا، وَتَمْرٌ فَيُلْقِي فِيهِ الزَّبِيبَ. (د)', 'ആയിശ(റ): നിശ്ചയം റസൂൽ(സ)ക്ക് വേണ്ടി ഉണക്ക മുന്തിരിയുടെ പാനീയമുണ്ടാക്കിയിട്ട് അതിൽ കാരക്ക ഇട്ടുവെക്കുകയോ, കാരക്കയുടെ പാനീയമുണ്ടാക്കിയിട്ട് അതിൽ ഉണക്ക മുന്തിരി ഇട്ടു വെക്കുകയോ ചെയ്തിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ صَفِيَّةَ بِنْتِ عَطِيَّةَ قَالَتْ: دَخَلْتُ مَعَ نِسْوَةٍ مِنْ عَبْدِ الْقَيْسِ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، فَسَأَلْنَاهَا عَنِ التَّمْرِ وَالزَّبِيبِ، فَقَالَتْ: كُنْتُ آخُذُ قَبْضَةً مِنْ تَمْرٍ وَقَبْضَةً مِنْ زَبِيبٍ، فَأُلْقِيهِ فِي إِنَاءٍ فَأَمْرُسُهُ، ثُمَّ أَسْقِيهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د)', 'സ്വഫിയ്യ ബിൻതു അതിയ്യ(റ): അബ്ദുൽഖൈസിൽപെട്ട ചില സ്ത്രീകളോടു കൂടെ ഞാൻ ആയിശ(റ)യുടെ അടുക്കൽ ചെന്നിട്ട് കാരക്കയെയും ഉണക്കമുന്തിരിയെയും സംബന്ധിച്ച് അവരോടു ചോദിച്ചു. അപ്പോഴവർ പറഞ്ഞു: ഞാൻ കാരക്കയിൽ നിന്നും ഉണക്ക മുന്തിരിയിൽനിന്നും ഓരോപിടി എടുത്ത് അതൊരു പാത്രത്തിൽ ഇടുകയും അനന്തരം വിരലുകൾ കൊണ്ട് വെള്ളത്തിലിട്ട് ഞെക്കിപ്പിഴിയുകയും ചെയ്തിരുന്നു. ശേഷം നബി(സ)യെ ഞാനത് കുടിപ്പിച്ചിരുന്നു. (ദ)', 'صَفِيَّةَ بِنْتِ عَطِيَّةَ قَالَتْ', 'സ്വഫിയ്യ ബിൻതു അതിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَنْبِذُوا الزَّهْوَ وَالرُّطَبَ، وَلَا تَنْبِذُوا الرُّطَبَ وَالزَّبِيبَ، جَمِيعًا". (ن)', 'അബൂഖതാദ(റ): റസൂൽ(സ) പറഞ്ഞു: "പഴുപ്പ്നിറം കയറിയ കാരക്കയും പഴുത്ത് പാകമായ ഈത്തപ്പഴവും വെള്ളത്തിലിട്ട് പാനീയമുണ്ടാക്കരുത്. പഴുത്ത് പാകമായ ഈത്തപ്പഴവും ഉണക്കമുന്തിരിയും ഒരുമിച്ച് വെള്ളത്തിലിട്ടും നീരെടുക്കരുത്." (ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 606, 606, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَجْمَعُوا بَيْنَ الرُّطَبِ وَالزَّهْوِ، وَلَا بَيْنَ الزَّبِيبِ وَالتَّمْرِ، وَانْبِذُوا كُلَّ وَاحِدٍ مِنْهُمَا عَلَى حِدَتِهِ". (ق,د,ن,جه)', 'അബൂഖതാദ(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "പഴുത്ത് പാകമായ ഈത്തപ്പഴവും പഴുപ്പ് നിറം കയറിയ കാരക്കയും തമ്മിലും, ഉണക്കമുന്തിരിയും കാരക്കയും തമ്മിലും ഒരുമിച്ചു ചേർക്കരുത് (നീരെടുക്കരുത്). അവകളോരോന്നും വെവ്വേറെ വെള്ളത്തിലിട്ട് നീരെടുക്കുക." (ബു,മു,ദ,ന,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 606, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ، وَأَنْ يُخْلَطَ الْبَلَحُ وَالزَّهْوُ. وفي رواية: وَأَنْ يُخْلَطَ التَّمْرُ بِالزَّبِيبِ وَالزَّهْوُ بِالتَّمْرِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ചുരക്കാപാത്രം, പച്ചഭരണി, ടാർപൂശിയ പാത്രം, ഈത്തപ്പനയുടെ മുരട് തുരന്നുണ്ടാക്കുന്ന പാത്രം, പച്ചക്കാരക്കയും പഴുപ്പ്നിറം കയറിയ ഈത്തപ്പഴവും കൂട്ടിക്കലർത്തി നീരെടുക്കൽ എന്നിവ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=64), 1, 'وَفِي رِوَايَةٍ: وَأَنْ يُخْلَطَ التَّمْرُ بِالزَّبِيبِ وَالزَّهْوُ بِالتَّمْرِ. (ن)', 'മറ്റൊരു നിവേദനം: കാരക്ക ഉണക്കമുന്തിരിയുമായും പഴുപ്പ് നിറം കയറിയ ഈത്തപ്പഴം കാരക്കയുമായും കൂട്ടിക്കലർത്തുന്നത് റസൂൽ(സ) നിരോധിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَنِ الزَّهْوِ وَالتَّمْرِ، وَالزَّبِيبِ وَالتَّمْرِ. (ن)', 'അബൂസഈദിൽഖുദ്‌രി(റ): പഴുപ്പ് നിറം കയറിയ ഈത്തപ്പഴവും കാരക്കയും തമ്മിലും ഉണക്ക മുന്തിരിയും കാരക്കയും തമ്മിലും കൂട്ടിക്കലർത്തൽ റസൂൽ(സ) നിരോധിച്ചു. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽഖുദ്‌രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ ابْنِ أَبِي لَيْلَى، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قالَ: نَهَى عَنِ الْبَلَحِ وَالتَّمْرِ، وَالزَّبِيبِ وَالتَّمْرِ. (د,ن)', 'ഇബ്നു അബീലൈല: പ്രവാചകൻ(സ)യുടെ അനുചരന്മാരിൽ ഒരാൾ ഉദ്ധരിക്കുന്നു: പച്ചക്കാരക്ക കാരക്കയുമായും, ഉണക്കമുന്തിരി കാരക്കയുമായും കൂട്ടിക്കലർത്തി നീരെടുക്കൽ റസൂൽ(സ) വിലക്കി. (ദ,ന)', 'ابْنِ أَبِي لَيْلَى، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قالَ', 'ഇബ്നു അബീലൈല', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ، عن النبي صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَجْمَعُوا بَيْنَ التَّمْرِ وَالزَّبِيبِ، وَلَا بَيْنَ الزَّهْوِ وَالرُّطَبِ". وفي رواية قال: "لَا تَنْبُذُوا الزَّهْوَ وَالرُّطَبَ جَمِيعًا، وَلَا تَنْبُذُوا الزَّبِيبَ وَالرُّطَبَ جَمِيعًا." (ن)', 'അബൂഖതാദ(റ): റസൂൽ(സ) പറഞ്ഞു: "കാരക്കയും ഉണക്കമുന്തിരിയും നിങ്ങൾ ഒരുമിച്ചു ചേർക്കരുത്. പഴുപ്പ്നിറം കയറിയ ഈത്തപ്പഴവും പഴുത്തു പാകമായ ഈത്തപ്പഴവും നിങ്ങൾ ഒരുമിച്ചു ചേർക്കരുത്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=67), 1, 'وَفِي رِوَايَةٍ قال: "لَا تَنْبُذُوا الزَّهْوَ وَالرُّطَبَ جَمِيعًا، وَلَا تَنْبُذُوا الزَّبِيبَ وَالرُّطَبَ جَمِيعًا." (ن)', 'മറ്റൊരു നിവേദനം: "പഴുപ്പ്നിറം കയറിയ കാരക്കയും പഴുത്ത് പാകമായ ഈത്തപ്പഴവും ഒരുമിച്ച് ചേർത്തു വെള്ളത്തിലിട്ട് നീരെടുക്കരുത്. ഉണക്കമുന്തിരിയും പഴുത്തുപാകമായ ഈത്തപ്പഴവും ഒരുമിച്ചുചേർത്തു വെള്ളത്തിലിട്ടും നീരെടുക്കരുത്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ أَنْ يُخْلَطَ التَّمْرُ وَالزَّبِيبُ، وَأَنْ يُخْلَطَ الزَّهْوُ وَالتَّمْرُ، وَالزَّهْوُ وَالْبُسْرُ. (ن)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): കാരക്കയും ഉണക്കമുന്തിരിയും കൂട്ടിക്കലർത്തുന്നതും, പഴുപ്പ്നിറം കയറിയ ഈത്തപ്പഴവും കാരക്കയും കൂട്ടിക്കലർത്തുന്നതും, പഴുപ്പ്നിറം കയറിയ ഈത്തപ്പഴവും പഴുക്കാത്ത ഈത്തപ്പഴവും കൂട്ടിക്കലർത്തുന്നതും റസൂൽ(സ) നിരോധിച്ചു. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 607, 607, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ جَابِرِ بْنِ زَيْدٍ وَعِكْرِمَةَ: أَنَّهُمَا كَانَا يَكْرَهَانِ الْبُسْرَ وَحْدَهُ، وَيَأْخُذَانِ ذَلِكَ عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا. وَقَالَ ابْنُ عَبَّاسٍ: أَخْشَى أَنْ يَكُونَ الْمُزَّاءُ الَّذِي نُهِيتُ عَنْهُ عَبْدُ الْقَيْسِ. فقِيلَ لِقَتَادَةَ: مَا الْمُزَّاءُ؟ قَالَ: النَّبِيذُ فِي الْحَنْتَمِ وَالْمُزَفَّتِ. (د)', 'ജാബിറിബ്നു സൈദ്(റ), ഇക്രിമ(റ): പഴുക്കാത്ത ഈത്തപ്പഴത്തിൽ നിന്നുമാത്രം ഉണ്ടാക്കുന്ന പാനീയം അവരിരുവരും വെറുത്തിരുന്നു. ഇബ്നുഅബ്വാസ്(റ)വിൽ നിന്നാണവർ അത് പഠിച്ചത്. ഇബ്നുഅബ്വാസ്(റ) പറഞ്ഞു: അബ്ദുൽ ഖൈസിന് നിരോധിക്കപ്പെട്ട ''മുസ്സാഅ്'' ആകുമോ അതെന്ന് ഞാൻ ഭയപ്പെടുന്നു. അപ്പോൾ ഖതാദ ചോദിക്കപ്പെട്ടു, മുസ്സാഅ് എന്താണ്? അദ്ദേഹം പറഞ്ഞു: പച്ച ഭരണിയിലും ടാറിട്ട പാത്രത്തുലുമുള്ള ലഹരി പദാർത്ഥം. (ദ)', 'جَابِرِ بْنِ زَيْدٍ وَعِكْرِمَةَ', 'ജാബിറിബ്നു സൈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 607, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: كَانَ أَنَسٌ يَأْمُرُ بِالتَّذْنُوبِ فَيُقْرَضُ. (ن)', 'അനസ്(റ): ഒരു ഭാഗം പഴുത്ത ഈത്തപ്പഴം മുറിച്ചെടുക്കാൻ അനസ്(റ) കൽപിക്കുമായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ لَا يَدَعُ شَيْئًا قَدْ أَرْطَبَ إِلَّا عَزَلَهُ عَنْ فَضِيخِهِ. (ن)', 'അനിസ്(റ): പച്ച ഈത്തപ്പഴത്തിന്റെ പഴുത്തഭാഗം നീക്കിയിട്ട് മാത്രമാണ് റസൂൽ(സ) ഉപയോഗിച്ചിരുന്നത്. (ന)', 'أَنَسٍ', 'അനിസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُخْلَطَ بُسْرٌ بِتَمْرٍ، أَوْ زَبِيبٌ بِتَمْرٍ، أَوْ زَبِيبٌ بِبُسْرٍ، وَقَالَ: "مَنْ شَرِبَهُ مِنْكُمْ فَلْيَشْرَبْ كُلَّ وَاحِدٍ مِنْهُ فَرْدًا: تَمْرًا فَرْدًا، أَوْ بُسْرًا فَرْدًا، أَوْ زَبِيبًا فَرْدًا". (ن)', 'അബൂസഇൗദിൽ ഖുദ്രിയ്യി(റ): പഴുക്കാത്ത ഈത്തപ്പഴം, ഉണങ്ങിയ ഈത്തപ്പഴവുമായിട്ടോ ഉണങ്ങിയ മുന്തിരി ഉണങ്ങിയ ഈത്തപ്പഴവുമായിട്ടോ, ഉണങ്ങിയ മുന്തിരി പഴുക്കാത്ത ഈത്തപ്പഴുമായിട്ടോ (നീരെടുക്കാൻ വേണ്ടി) കൂട്ടിക്കലർത്തുന്നത് നിരോധിച്ചിട്ട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും അത് പാനം ചെയ്യുന്നുവെങ്കിൽ അവകളോരോന്നും തനിയെ പാനം ചെയ്യുക. കാരക്ക മാത്രമായിട്ടോ, പഴുക്കാത്ത ഈത്തപ്പഴം മാത്രമായിട്ടോ ഉണങ്ങിയമുന്തിരിമാത്രമായിട്ടോ പാനം ചെയ്യുക." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രിയ്യി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَجْمَعُوا بَيْنَ الرُّطَبِ وَالزَّهْوِ، وَلَا بَيْنَ الزَّبِيبِ وَالتَّمْرِ، وَانْبِذُوا كُلَّ وَاحِدٍ مِنْهُمَا عَلَى حِدَتِهِ". (ق,د,ن,جه)', 'അബൂഖതാദ(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "പഴുത്ത് പാകമായ ഈത്തപ്പഴം പഴുപ്പ്നിറം കയറിയ ഈത്തപ്പഴവുമായും, ഉണക്കമുന്തിരി കാരക്കയുമായും ഒരുമിച്ചു ചേർക്കരുത് (നീരെടുക്കരുത്). അവകളോരോന്നും വെവ്വേറെ വെള്ളത്തിലിട്ട് നീരെടുക്കുക." (ബു,മു,ദ,ന,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 608, 608, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى أَبُو أُسَيْدٍ السَّاعِدِيُّ فَدَعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عُرْسِهِ، فَكَانَتِ امْرَأَتُهُ خَادِمَهُمْ، وَهِيَ الْعَرُوسُ، قَالَ: أَتَدْرُونَ مَا سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ أَنْقَعْتُ لَهُ تَمَرَاتٍ مِنَ اللَّيْلِ فِي تَوْرٍ. (خ)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): അബൂ ഉസൈദുസ്സാഇദിയ്യ്(റ) നബി(സ)യെ തന്റെ വിവാഹസദ്യക്ക് ക്ഷണിച്ചു. അദ്ദേഹത്തിന്റെ ഭാര്യയായ വധു തന്നെയാണ് അവരെ സ്വീകരിച്ചത്. അബൂഉസൈദ്(റ) പറയുന്നു: അവർ നബിയെ കുടിപ്പിച്ചത് എന്താണെന്ന് നിങ്ങൾക്കറിയുമോ? രാത്രി ചെറിയ പാത്രത്തിൽ കാരക്ക വെള്ളത്തിലിട്ട് കുതിർത്തതാണ് റസൂൽ(സ)യെ കുടിപ്പിച്ചത്. (ബു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 608, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عُمَرَ وَابْنِ عَبَّاسٍ، رَضِيَ اللَّهُ عَنْهُمْ: أَنَّهُمَا شَهِدَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ، ثُمَّ تَلَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ الْآيَةَ: {وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا}[الحشر:٧] (ن)', 'ഇബ്നുഉമർ(റ), ഇബ്നുഅബ്വാസ്(റ): ചുരയ്ക്കാ പാത്രം, പച്ചഭരണി, ടാറിട്ടപാത്രം, ഈത്തപ്പന കൊത്തിയുണ്ടാക്കിയ പാത്രം എന്നിവ റസൂൽ(സ) നിരോധിച്ചതിന് അവരിരുവരും സാക്ഷ്യം വഹിച്ചിട്ടുണ്ട്. പിന്നീട് റസൂൽ(സ) ഈ സൂക്തം പാരായണം ചെയ്തു: ''റസൂൽ നിങ്ങൾക്ക് നൽകിയതെന്തോ അത് സ്വീകരിക്കുക, അവിടന്ന് നിങ്ങളോടു വിലക്കിയതെന്തോ അതിൽ നിന്നും വിട്ടുനിൽക്കുക.'' (അൽഹശ്ർ:7) (ന)', 'ابْنِ عُمَرَ وَابْنِ عَبَّاسٍ،', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الحشر:٧', null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَلَمْ يَقُلِ اللَّهُ عَزَّ وَجَلَّ: {وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا}؟ قِيلَ: بَلَى. قَالَ: أَلَمْ يَقُلِ اللَّهُ: {وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ} [الأحزاب:٣٦]؟ قِيلَ: بَلَى. قَالَ: فَإِنِّي أَشْهَدُ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ النَّقِيرِ وَالْمُقَيَّرِ وَالدُّبَّاءِ وَالْحَنْتَمِ. (ن)', 'ഇബ്നുഅബ്വാസ്(റ): അദ്ദേഹം ചോദിച്ചു: പ്രതാപശാലിയും ഉന്നതനുമായ അല്ലാഹു പറഞ്ഞിട്ടില്ലേ: ''റസൂൽ നിങ്ങൾക്ക് നൽകിയതെന്തോ അത് സ്വീകരിക്കുക, അവിടന്ന് നിങ്ങളോടു വിലക്കിയതെന്തോ അതിൽ നിന്നും വിട്ടുനിൽക്കുക.'' മറുപടി പറയപ്പെട്ടു: അതെ (പറഞ്ഞിട്ടുണ്ട്). ഇബ്നുഅബ്വാസ്(റ) ചോദിച്ചു: അല്ലാഹു പറഞ്ഞിട്ടില്ലേ: ''അല്ലാഹുവും റസൂലും ഒരുകാര്യം തീരുമാനിച്ചാൽ സ്വന്തം കാര്യങ്ങളിൽ മറ്റൊരു വഴി തെരഞ്ഞെടുക്കാൻ വിശ്വാസിക്കോ വിശ്വാസിനിക്കോ പാടില്ല.'' (അൽ അഹ്സാബ്: 36) മറുപടി പറയപ്പെട്ടു: അതെ. ഇബ്നുഅബ്വാസ്(റ) പറഞ്ഞു: ഈത്തപ്പന കൊത്തിയുണ്ടായ പാത്രം, ടാറിട്ടപാത്രം, ചുരയ്ക്കാപാത്രം, പച്ച ഭരണി എന്നിവ നബി(സ) നിരോധിച്ചതിന് നിശ്ചയമായും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്വാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأحزاب:٣٦', null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفْدَ عَبْدِ الْقَيْسِ حِينَ قَدِمُوا عَلَيْهِ عَنِ الدُّبَّاءِ وَعَنِ النَّقِيرِ وَعَنِ الْمُزَفَّتِ وَعَنِ الْمَزَادَةِ الْمَجْبُوبَةِ. وَقَالَ: "انْتَبِذْ فِي سِقَائِكَ. أَوْكِهِ وَاشْرَبْهُ حُلْوًا". قَالَ بَعْضُهُمْ: ائْذَنْ لِي يَا رَسُولَ اللَّهِ فِي مِثْلِ هَذَا. قَالَ: "إِذًا تَجْعَلَهَا مِثْلَ هَذِهِ" وَأَشَارَ بِيَدِهِ يَصِفُ ذَلِكَ. (ن)', 'അബൂഹുറൈറ(റ): അബ്ദുൽഖൈസ് നിവേദകസംഘം റസൂൽ(സ)യുടെയടുക്കൽ ആഗതരായ സന്ദർഭത്തിൽ ചുരങ്ങാപ്പാത്രം, ഈത്തപ്പനമുരട് തുരന്നുണ്ടാക്കിയ പാത്രം, ടാർ പൂശിയ പാത്രം, മുറിക്കപ്പെട്ട തോൽപ്പാത്രം എന്നിവ നിരോധിച്ചുകൊണ്ട് റസൂൽ(സ) അരുളി: "നീ നിന്റെ തോൽപ്പാത്രത്തിൽ ജ്യൂസുണ്ടാക്കുകയും അതിന്റെ വായ (ഉപരിഭാഗം) കെട്ടുകയും സ്വാദോടെ കുടിക്കുകയും ചെയ്യുക." അപ്പോൾ അവരിൽ ചിലർ ചോദിച്ചു: ദൈവദൂതരേ, ഇതുപോലുള്ളതിൽ ഞങ്ങൾക്ക് അനുമതി നൽകിയാലും. റസൂൽ(സ) തന്റെ കരം കൊണ്ട് ആംഗ്യരൂപേണ വിശദീകരിച്ചുകൊണ്ട് പറഞ്ഞു: "അപ്പോൾ നീയത് ഇതുപോലെ ആക്കുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 609, 609, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَرِّ وَالْمُزَفَّتِ وَالدُّبَّاءِ وَالنَّقِيرِ، وكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا لَمْ يَجِدْ سِقَاءً يُنْبَذُ لَهُ فِيهِ نُبِذَ لَهُ فِي تَوْرٍ مِنْ حِجَارَةٍ. وفي رواية قال: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْبَذُ لَهُ فِي سقاء، فَإِذَا لَمْ يَكُنْ لَهُ سِقَاءٌ نَنْبِذُ لَهُ فِي تَوْرٍ برام. قَالَ: وَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالنَّقِيرِ وَالْمُزَفَّتِ. (ن)', 'ജാബിർ(റ): ടാർപൂശിയ പാത്രം, മൺഭരണികൾ, ചുരങ്ങാപ്പാത്രം, ഈത്തപ്പനമുരട് തുരന്നുണ്ടാക്കിയ പാത്രം എന്നിവ റസൂൽ(സ) നിരോധിച്ചു. പ്രവാചകർ(സ)ക്ക് ജ്യൂസുണ്ടാക്കാറുള്ള തോൽപ്പാത്രം ലഭിച്ചില്ലങ്കിൽ കൽപ്പാത്രത്തിൽ പ്രവാചകൻ(സ)ക്ക് വേണ്ടി ജ്യൂസുണ്ടാക്കാറുണ്ടായിരുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=78), 1, 'وَفِي رِوَايَةٍ قال: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْبَذُ لَهُ فِي سقاء، فَإِذَا لَمْ يَكُنْ لَهُ سِقَاءٌ نَنْبِذُ لَهُ فِي تَوْرٍ برام. قَالَ: وَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالنَّقِيرِ وَالْمُزَفَّتِ. (ن)', 'മറ്റൊരു നിവേദനം: പ്രവാചകൻ(സ)ക്ക് വേണ്ടി തോൽപ്പാത്രത്തിൽ ജ്യൂസുണ്ടാക്കാറുണ്ടായിരുന്നു. തോൽപ്പാത്രം ലഭിച്ചില്ലായെങ്കിൽ കൽച്ചട്ടിയിലായിരുന്നു ഞങ്ങൾ അവിടത്തേക്ക് ജ്യൂസുണ്ടാക്കിയിരുന്നത്. അദ്ദേഹം പറയുന്നു: ചുരങ്ങാപ്പാത്രം, ഈത്തപ്പനമുരട് തുരന്നുണ്ടാക്കിയ പാത്രം, ടാർപൂശിയ പാത്രം എന്നിവ റസൂൽ(സ) നിരോധിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ زَاذَانَ قَالَ: قُلْتُ لِابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: حَدِّثْنِي بِمَا نَهَى عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَشْرِبَةِ بِلُغَتِكَ، وَفَسِّرْهُ لِي بِلُغَتِنَا، فَإِنَّ لَكُمْ لُغَةً سِوَى لُغَتِنَا. فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَنْتَمِ وَهِيَ الْجَرَّةُ، وَعَنِ الدُّبَّاءِ وَهِيَ الْقَرْعَةُ، وَعَنِ الْمُزَفَّتِ وَهُوَ الْمُقَيَّرُ، وَعَنِ النَّقِيرِ وَهِيَ النَّخْلَةُ تُنْسَحُ نَسْحًا وَتُنْقَرُ نَقْرًا، وَأَمَرَ أَنْ يُنْتَبَذَ فِي الْأَسْقِيَةِ. (م)', 'സാദാൻ(റ): ഞാൻ ഇബ്നുഉമർ(റ)വിനോടു പറഞ്ഞു: റസൂൽ(സ) നിരോധിച്ച പാനീയങ്ങളെക്കുറിച്ച് താങ്കളുടെ ഭാഷയിൽ എനിക്ക് പറഞ്ഞു തരിക. ഞങ്ങളുടെ ഭാഷയിൽ അതെനിക്ക് വിശദീകരിച്ചു തരികയും ചെയ്യുക. ഞങ്ങളുടെ ഭാഷയല്ല നിങ്ങളുടേത്. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഹൻതം നിരോധിച്ചു. അത് മൺഭരണിയാണ്. ദുബ്വാഅ് നിരോധിച്ചു. അത് ചുരയ്ക്കാപാത്രമാണ്. മുസഫ്ഫത്ത് നിരോധിച്ചു. അത് ടാർപൂശിയ പാത്രമാണ്. നഖീർ നിരോധിച്ചു. അത് തൊലി നീക്കപ്പെടുകയും ശേഷം കൊത്തുവേല ചെയ്യപ്പെടുകയും ചെയ്യുന്ന ഈത്തപ്പനയാകുന്നു. തോൽപ്പാത്രങ്ങളിൽ ജ്യൂസുണ്ടാക്കാൻ റസൂൽ(സ) കൽപിച്ചു. (മു)', 'زَاذَانَ قَالَ', 'സാദാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 610, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّا هَذَا الْحَيَّ مِنْ رَبِيعَةَ، قَدْ حَالَ بَيْنَنَا وَبَيْنَكَ كُفَّارُ مُضَرَ، وَلَيْسَ نَخْلُصُ إِلَيْكَ إِلَّا فِي شَهْرٍ حَرَامٍ، فَمُرْنَا بِشَيْءٍ، نَأْخُذُ بِهِ وَنَدْعُو إِلَيْهِ مَنْ وَرَاءَنَا. قَالَ: "آمُرُكُمْ بِأَرْبَعٍ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: الْإِيمَانُ بِاللَّهِ، وَشَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ. وَعَقَدَ بِيَدِهِ وَاحِدَةً وَقَالَ: مُسَدَّدٌ الْإِيمَانُ بِاللَّهِ. ثُمَّ فَسَّرَهَا لَهُمْ: شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامُ الصَّلَاةِ، وَإِيتَاءُ الزَّكَاةِ، وَأَنْ تُؤَدُّوا الْخُمُسَ مِمَّا غَنِمْتُمْ وَأَنْهَاكُمْ عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالْمُزَفَّتِ، وَالْمُقَيَّرِ". (ق,د,ت,ن)', 'ഇബ്നുഅബ്വാസ്(റ): അബ്ദുൽഖൈസ് നിവേദകസംഘം നബിയുടെ അടുക്കൽ വന്നിട്ട് പറഞ്ഞു: ദൈവദൂതരേ, താങ്കളുടെയും റബീഅ ഗോത്രക്കാരായ ഞങ്ങളുടെയും ഇടയിൽ മുളർ ഗോത്രക്കാരായ സത്യനിഷേധികൾ തടസ്സമായതിനാൽ യുദ്ധം നിഷിദ്ധമായ മാസത്തിലല്ലാതെ താങ്കളുടെയടുക്കൽ വരാൻ ഞങ്ങൾക്ക് സാധിക്കുകയില്ല. അതുകൊണ്ട് ഞങ്ങൾക്ക് മുറുകെപ്പിടിക്കാനും ഞങ്ങൾക്ക് പിന്നിലുള്ളവരെ അതിലേക്ക് ക്ഷണിക്കാനുമുതകുന്ന ചിലകാര്യങ്ങൾ ഞങ്ങളോടു കൽപിച്ചാലും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളോടു നാലു കാര്യങ്ങൾ നിർദ്ദേശിക്കുകയും നാലു കാര്യങ്ങൾ നിരോധിക്കുകയും ചെയ്യുന്നു. അല്ലാഹുവിൽ വിശ്വസിക്കുകയും അവനല്ലാതെ ആരാധ്യനില്ലായെന്നു സാക്ഷ്യം വഹിക്കുകയും ചെയ്യുക." റസൂൽ(സ) തന്റെ കൈകൊണ്ട് ഒന്ന് എന്ന് എണ്ണി. ശേഷം പറഞ്ഞു: "അല്ലാഹുവിലുള്ള വിശ്വാസം ശക്തമാക്കപ്പെടണം." പിന്നീട് അല്ലാഹുവിൽ വിശ്വസിക്കുന്നതിനെക്കുറിച്ച് നബി അവരോടു വിശദീകരിച്ചു: "അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ലയെന്നും മുഹമ്മദ്(സ) ദൈവദൂതരാണെന്നും സാക്ഷ്യം വഹിക്കുക. നമസ്കാരം നിലനിർത്തുക, സക്കാത്തു നൽകുക, യുദ്ധാർജ്ജിത സമ്പത്തിന്റെ അഞ്ചിലൊരുവിഹിതം (പൊതുഖജനാവിലേക്ക്) നൽകുക. ചുരങ്ങാപാത്രം, പച്ചഭരണി, ടാർപൂശിയ പാത്രം, കീൽഒഴിച്ച പാത്രം എന്നിവ ഞാൻ നിങ്ങൾക്ക് നിരോധിക്കുകയും ചെയ്യുന്നു." (ബു,മു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്വാസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 610, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِوَفْدِ عَبْدِ الْقَيْسِ: "أَنْهَاكُمْ عَنِ النَّقِيرِ، وَالْمُقَيَّرِ، وَالْحَنْتَمِ، وَالدُّبَّاءِ، وَالْمَزَادَةِ الْمَجْبُوبَةِ، وَلَكِنِ اشْرَبْ فِي سِقَائِكَ وَأَوْكِهِ". (م,د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) അബ്ദുൽഖൈസ് നിവേദകസംഘത്തോടു പറഞ്ഞു: "ഈത്തപ്പനക്കുറ്റി തുരന്നുണ്ടാക്കിയ പാത്രം, ടാർപൂശിയ പാത്രം, പച്ചഭരണി, ചുരങ്ങാപ്പാത്രം, മുറിക്കപ്പെട്ട വലിയ തോൽപ്പാത്രം എന്നിവയുടെ ഉപയോഗം ഞാൻ നിങ്ങൾക്ക് നിരോധിക്കുന്നു. എങ്കിലും തോൽ പാത്രത്തിൽ നീ കുടിച്ചുകൊള്ളുക. അതിന്റെ ഉപരിഭാഗം (വായ) കെട്ടുകയും ചെയ്യുക." (മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ: فِي قِصَّةِ وَفْدِ عَبْدِ الْقَيْسِ، قَالُوا: فِيمَ نَشْرَبُ يَا نَبِيَّ اللَّهِ؟ فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِأَسْقِيَةِ الْأَدَمِ الَّتِي يُلَاثُ عَلَى أَفْوَاهِهَا". (د,ن)', 'ഇബ്നുഅബ്വാസ്(റ): അബ്ദുൽഖൈസ് നിവേദകസംഘത്തിന്റെ സംഭവം ഉദ്ധരിച്ചു കൊണ്ട് അദ്ദേഹം പറയുന്നു. അവർ ചോദിച്ചു: പ്രവാചകരേ ഏത് പാത്രത്തിലാണ് ഞങ്ങൾ പാനം ചെയ്യേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "വായ മുടികെട്ടിയ തോൽപാത്രം നിങ്ങൾ ഉപയോഗിക്കുക." (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്വാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي الْقَمُوصِ زَيْدِ بْنِ عَلِيٍّ: حَدَّثَنِي رَجُلٌ كَانَ مِنَ الْوَفْدِ الَّذِينَ وَفَدُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ عَبْدِ الْقَيْسِ - يَحْسَبُ أَنَّ اسْمَهُ قَيْسُ بْنُ النُّعْمَانِ - فَقَالَ: "لَا تَشْرَبُوا فِي نَقِيرٍ، وَلَا مُزَفَّتٍ، وَلَا دُبَّاءٍ، وَلَا حَنْتَمٍ، وَاشْرَبُوا فِي الْجِلْدِ الْمُوكَى عَلَيْهِ، فَإِنِ اشْتَدَّ فَاكْسِرُوهُ بِالْمَاءِ، فَإِنْ أَعْيَاكُمْ فَأَهْرِيقُوهُ". (د)', 'അബുൽഖമൂസ് സൈദുബ്നു അലിയ്യ്(റ): നബി(സ)യുടെ അടുക്കൽ വന്ന അബ്ദുൽഖൈസ് നിവേദകസംഘത്തിൽപ്പെട്ട ഒരാൾ - അദ്ദേഹത്തിന്റെ പേർ ഖൈസ്ബ്നു നുഅ്മാൻ എന്നാണെന്നു തോന്നുന്നു - എന്നോടു ഒരു ഹദീസ് പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "ഈത്തപ്പനക്കുറ്റി തുരന്നുണ്ടാക്കുന്ന പാത്രത്തിലും, ടാർപൂശിയപാത്രത്തിലും, ചുരങ്ങാപാത്രത്തിലും, പച്ചഭരണിയിലും നിങ്ങൾ പാനം ചെയ്യരുത്. വായമുടികെട്ടിയ തോൽപാത്രത്തിൽ നിങ്ങൾ കുടിക്കുക. പാനീയം കട്ടികൂടിയാൽ അതിൽ വെള്ളം ചേർത്ത് കട്ടിക്കുറക്കുക, അത് നിങ്ങൾക്ക് വിഷമകരമായാൽ നിങ്ങളത് ഒഴിച്ചുകളയുക." (ദ)', 'أَبِي الْقَمُوصِ زَيْدِ بْنِ عَلِيٍّ', 'അബുൽഖമൂസ് സൈദുബ്നു അലിയ്യ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 611, 611, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ وَفْدَ عَبْدِ الْقَيْسِ قَالُوا: يَا رَسُولَ اللَّهِ، فِيمَ نَشْرَبُ؟ قَالَ: "لَا تَشْرَبُوا فِي الدُّبَّاءِ، وَلَا فِي الْمُزَفَّتِ، وَلَا فِي النَّقِيرِ، وَانْتَبِذُوا فِي الْأَسْقِيَةِ". قَالُوا: يَا رَسُولَ اللَّهِ، فَإِنِ اشْتَدَّ فِي الْأَسْقِيَةِ؟ قَالَ: "فَصُبُّوا عَلَيْهِ الْمَاءَ" قَالُوا: يَا رَسُولَ اللَّهِ، فَقَالَ لَهُمْ فِي الثَّالِثَةِ أَوِ الرَّابِعَةِ: "أَهْرِيقُوهُ" ثُمَّ قَالَ: "إِنَّ اللَّهَ حَرَّمَ عَلَيَّ - أَوْ: حُرِّمَ - الْخَمْرُ وَالْمَيْسِرُ وَالْكُوبَةُ" قَالَ: "وَكُلُّ مُسْكِرٍ حَرَامٌ". (د,ن)', 'ഇബ്നുഅബ്വാസ്(റ): അബ്ദുൽഖൈസ് നിവേദകസംഘം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളെന്തിലാണ് പാനം ചെയ്യേണ്ടത്? അവിടന്ന് പറഞ്ഞു: "ചുരങ്ങാപ്പാത്രത്തിലും, ടാർപൂശിയ പാത്രത്തിലും, ഈത്തപ്പനക്കുറ്റി തുരന്നുണ്ടാക്കിയ പാത്രത്തിലും നിങ്ങൾ പാനം ചെയ്യരുത്. നിങ്ങൾ തോൽപ്പാത്രങ്ങളിൽ ജ്യൂസുണ്ടാക്കുക." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, തോൽ പാത്രങ്ങളിൽ അത് കട്ടിയായാലോ?. റസൂൽ(സ) പ്രതിവചിച്ചു: "അപ്പോൾ നിങ്ങളതിൽ വെള്ളമൊഴിക്കുക." അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ. മൂന്നാമത്തേയോ നാലാമത്തേയോ തവണ തിരുമേനി(സ) അവരോട് പറഞ്ഞു: "നിങ്ങളത് ഒഴിച്ചുകളയുക." പിന്നീട് അവിടന്ന് പറഞ്ഞു: "മദ്യവും ചൂതുകളിയും ചതുരംഗവും എനിക്ക് അല്ലാഹു നിഷിദ്ധമാക്കിയിരിക്കുന്നു - അല്ലെങ്കിൽ നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കുന്നു." തുടർന്ന് അവിടന്ന് അരുളി: "ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധമാകുന്നു." (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്വാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 611, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالنَّقِيرِ، وَالْجِعَةِ. (د,ن)', 'അലി(റ): ചുരങ്ങാപ്പാത്രം, പച്ചഭരണി, ഈത്തപ്പനക്കുറ്റി തുരന്നുണ്ടാക്കുന്ന പാത്രം, മദ്യം എന്നിവ റസൂൽ(സ) ഞങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നു. (ദ,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: ذَكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْأَوْعِيَةِ: الدُّبَّاءِ، وَالْحَنْتَمِ، وَالْمُزَفَّتِ، وَالنَّقِيرِ، فَقَالَ أَعْرَابِيٌّ: إِنَّهُ لَا ظُرُوفَ لَنَا، فَقَالَ: "اشْرَبُوا مَا حَلَّ". وفي رواية: قَالَ: "اجْتَنِبُوا مَا أَسْكَرَ". (ق,د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ചുരങ്ങാപ്പാത്രം, പച്ചഭരണി, ടാർപൂശിയ പാത്രം, ഈത്തപ്പനക്കുറ്റി തുരന്നുണ്ടാക്കിയ പാത്രം എന്നിവയെ ക്കുറിച്ച് റസൂൽ(സ) പരാമർശിച്ചപ്പോൾ ഒരുഗ്രാമീണ അറബി പറഞ്ഞു: ഞങ്ങൾക്ക് മറ്റ് പാത്രങ്ങളൊന്നുമില്ലല്ലോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അനുവദനീയമായത് നിങ്ങൾ കുടിക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=86), 1, 'وَفِي رِوَايَةٍ: قَالَ: "اجْتَنِبُوا مَا أَسْكَرَ". (ق,د)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അരുളി: "ലഹരിയുണ്ടാക്കുന്നത് നിങ്ങൾ വർജ്ജിക്കുക." (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ مَالِكِ بْنِ عُمَيْرٍ قَالَ: قَالَ صَعْصَعَةُ لِعَلِيِّ بْنِ أَبِي طَالِبٍ كَرَّمَ اللَّهُ وَجْهَهُ: انْهَنَا يَا أَمِيرَ الْمُؤْمِنِينَ عَمَّا نَهَاكَ عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ. (ن)', 'മാലികുബ്നു ഉമൈർ(റ): അലി(റ)നോട് സ്വഅ്സ്വഅത്ത് പറഞ്ഞു: സത്യവിശ്വാസികളുടെ നേതാവേ, റസൂൽ(സ) നിരോധിച്ചതിനെ താങ്കൾ ഞങ്ങൾക്കും നിരോധിച്ചാലും. അലി(റ) പറഞ്ഞു: റസൂൽ(സ) എനിക്ക് ചുരങ്ങാപ്പാത്രവും പച്ചഭരണിയും നിരോധിച്ചു. (ന)', 'مَالِكِ بْنِ عُمَيْرٍ قَالَ', 'മാലികുബ്നു ഉമൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَتَعْجِزُ إِحْدَاكُنَّ أَنْ تَتَّخِذَ كُلَّ عَامٍ مِنْ جِلْدِ أُضْحِيَّتِهَا سِقَاءً؟ ثُمَّ قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنْبَذَ فِي الْجَرِّ، وَفِي كَذَا، وَفِي كَذَا، إِلَّا الْخَلَّ. (جه)', 'ആഇശ(റ): എല്ലാ വർഷവും തന്റെ ബലി മൃഗത്തിന്റെ തോലിൽനിന്നും തോൽപ്പാത്രം ഉണ്ടാക്കാൻ നിങ്ങളിൽ നിന്ന് ആരെങ്കിലും അശക്തരാണോ? പിന്നീട് ആഇശ(റ) പറഞ്ഞു: മൺഭരണികളിലും ഇന്നപാത്രത്തിലും ഇന്നപാത്രത്തിലും ജ്യൂസുണ്ടാക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. സുർക്ക ഒഴികെ. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِنَبِيذِ جَرٍّ يَنِشُّ، فَقَالَ: "اضْرِبْ بِهَذَا الْحَائِطِ، فَإِنَّ هَذَا شَرَابُ مَنْ لَا يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): മൺഭരണികളിലുള്ള നുരഞ്ഞുപൊന്തുന്ന ജ്യൂസ് പ്രവാചകൻ(സ)ക്ക് കൊണ്ടുവരപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "നീ ഇത് മതിലിൽ എറിയുക. നിശ്ചയം ഇത് അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കാത്തവന്റെ പാനീയമാണ്." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 612, 612, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: سَأَلْنَا ابْنَ عُمَر - رَضِيَ اللَّهُ عَنْهُمَا - عَنْ نَبِيذِ الْجَرِّ؟ فَقَالَ: حَرَّمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَتَيْتُ ابْنَ عَبَّاسٍ - رَضِيَ اللَّهُ عَنْهُمَا - فَقُلْتُ: سَمِعْتُ الْيَوْمَ شَيْئًا عَجِبْتُ مِنْهُ. قَالَ: مَا هُوَ؟ قُلْتُ: سَأَلْتُ ابْنَ عُمَر عَنْ نَبِيذِ الْجَرِّ فَقَالَ: حَرَّمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: صَدَقَ ابْنُ عُمَر. قُلْتُ: مَا الْجَرُّ؟ قَالَ: كُلُّ شَيْءٍ مِنْ مَدَرٍ. وفي رواية قال: كُنْتُ عِنْدَ ابْنِ عُمَرَ، فَسُئِلَ عَنْ نَبِيذِ الْجَرِّ، فَقَالَ: حَرَّمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَشَقَّ عَلَيَّ لَمَّا سَمِعْتُهُ، فَأَتَيْتُ ابْنَ عَبَّاسٍ فَقُلْتُ: إِنَّ ابْنَ عُمَرَ سُئِلَ عَنْ شَيْءٍ، فَجَعَلْتُ أُعَظِّمُهُ. قَالَ: مَا هُوَ؟ قُلْتُ سُئِلَ عَنْ نَبِيذِ الْجَرِّ. فَقَالَ: صَدَقَ، حَرَّمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: وَمَا الْجَرُّ؟ قَالَ: كُلُّ شَيْءٍ صُنِعَ مِنْ مَدَرٍ. (ن)', 'സഈദുബ്നു ജുബൈർ(റ): മൺഭരണിയിലെ ജ്യൂസിനെ സംബന്ധിച്ച് ഞങ്ങൾ ഇബ്നുഉമർ(റ)വിനോടു ചോദിച്ചു. അപ്പോളദ്ദേഹം പറഞ്ഞു: പ്രവാചകനത് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. അനന്തരം ഞാൻ ഇബ്നുഅബ്വാസ്(റ)വിന്റെ അരികെ ചെന്നിട്ട് പറഞ്ഞു: എന്നെ അൽഭുതപ്പെടുത്തിയ ഒരു കാര്യം ഇന്ന് ഞാൻ കേട്ടു. അദ്ദേഹം ചോദിച്ചു: അതെന്താണ്? ഞാൻ പറഞ്ഞു: മൺഭരണിയിലെ ജ്യൂസിനെ സംബന്ധിച്ച് ഞാൻ ഇബ്നുഉമർ(റ)വിനോടു ചോദിച്ചു. അപ്പോളദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) അത് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. അപ്പോൾ ഇബ്നുഅബ്വാസ്(റ) പറഞ്ഞു: ഇബ്നുഉമർ(റ) സത്യം പറഞ്ഞിരിക്കുന്നു. ഞാൻ ചോദിച്ചു. എന്താണ് ജർറ്? അദ്ദേഹം പറഞ്ഞു: കളി മണ്ണിൽനിന്നുള്ള എല്ലാവസ്തുക്കളും.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=90), 1, 'وَفِي رِوَايَةٍ قال: كُنْتُ عِنْدَ ابْنِ عُمَرَ، فَسُئِلَ عَنْ نَبِيذِ الْجَرِّ، فَقَالَ: حَرَّمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَشَقَّ عَلَيَّ لَمَّا سَمِعْتُهُ، فَأَتَيْتُ ابْنَ عَبَّاسٍ فَقُلْتُ: إِنَّ ابْنَ عُمَرَ سُئِلَ عَنْ شَيْءٍ، فَجَعَلْتُ أُعَظِّمُهُ. قَالَ: مَا هُوَ؟ قُلْتُ سُئِلَ عَنْ نَبِيذِ الْجَرِّ. فَقَالَ: صَدَقَ، حَرَّمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: وَمَا الْجَرُّ؟ قَالَ: كُلُّ شَيْءٍ صُنِعَ مِنْ مَدَرٍ. (ن)', 'മറ്റൊരു നിവേദനം: ഞാൻ ഇബ്നുഉമർ(റ)വിന്റെ അടുക്കലായിരുന്നു. മൺഭരണികളിലെ ജ്യൂസിനെക്കുറിച്ച് അദ്ദേഹം ചോദിക്കപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) അത് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. അതു കേട്ടപ്പോൾ എനിക്ക് വിഷമമായി. ഞാനങ്ങനെ ഇബ്നുഅബ്വാസ്(റ)വിന്റെ സമീപം ചെന്നിട്ട് പറഞ്ഞു: ഒരു കാര്യത്തെക്കുറിച്ച് ഇബ്നുഉമർ(റ)വിനോടു ചോദിക്കപ്പെട്ടു. എനിക്കത് ഗൗരവമുള്ളതായി അനുഭവപ്പെടാൻ തുടങ്ങി. അദ്ദേഹം ചോദിച്ചു: അതെന്താണ്? ഞാൻ പറഞ്ഞു: മൺഭരണികളിലെ ജ്യൂസിനെക്കുറിച്ചു അദ്ദേഹം ചോദിക്കപ്പെട്ടു. അപ്പോൾ ഇബ്നുഅബ്വാസ്(റ) പറഞ്ഞു: ഇബ്നുഉമർ(റ) സത്യം പറഞ്ഞിരിക്കുന്നു. റസൂൽ(സ) അത് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. ഞാൻ ചോദിച്ചു: എന്താണ് ജർറ്? അദ്ദേഹം പറഞ്ഞു: കളിമണ്ണിനാൽ നിർമ്മിക്കപ്പെടുന്ന എല്ലാവസ്തുക്കളും. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ فِي الْجَرِّ غَيْرِ مُزَفَّتٍ. (ن)', 'അബ്ദുല്ല(റ): ടാർ പൂശാത്ത മൺഭരണികളിൽ റസൂൽ(സ) ഇളവുനൽകി. (ന)', 'عَبْدِ اللَّهِ', 'അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الشُّرْبِ مِنْ فَمِ الْقِرْبَةِ أَوِ السِّقَاءِ، وَأَنْ يَمْنَعَ جَارَهُ أَنْ يَغْرِزَ خَشَبَهُ فِي دَارِهِ. (خ)', 'അബൂഹുറൈറ(റ): വെള്ളംനിറച്ച തോൽപാത്രത്തിന്റെ വായ തുറന്ന് അതിൽനിന്നു കുടിക്കുന്നതും തന്റെ അയൽവാസി തന്റെ വളപ്പിൽ ഒരുമരക്കഷ്ണം നടുന്നത് തടയലും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ شَرَابٍ صُنِعَ فِي دُبَّاءٍ أَوْ حَنْتَمٍ أَوْ مُزَفَّتٍ، لَا يَكُونُ زَيْتًا أَوْ خَلًّا. (ن)', 'ആഇശ(റ): ചുരയ്ക്കാപ്പാത്രം, പച്ചഭരണി, ടാർപൂശിയ പാത്രം എന്നിവയിൽ നിർമ്മിക്കപ്പെട്ട പാനീയം റസൂൽ(സ) നിരോധിക്കുന്നതായി ഞാൻ കേട്ടു; അത് ഒലീവെണ്ണയോ സുറുക്കയോ അല്ലാത്ത സമയത്ത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: نَهَى عَنِ الدُّبَّاءِ بِذَاتِهِ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) ചുരയ്ക്കാ പാത്രത്തെ തന്നെ നിരോധിച്ചു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 613, 613, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ هُنَيْدَةَ بِنْتِ شَرِيكِ بْنِ أَبَانَ قَالَتْ: لَقِيتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا بِالْخُرَيْبَةِ، فَسَأَلْتُهَا عَنِ الْعَكَرِ؟ فَنَهَتْنِي عَنْهُ وَقَالَتْ: انْبِذِي عَشِيَّةً وَاشْرَبِيهِ غُدْوَةً، وَأُوكِي عَلَيْهِ، وَنَهَتْنِي عَنِ الدُّبَّاءِ وَالنَّقِيرِ وَالْمُزَفَّتِ وَالْحَنْتَمِ. (ن)', 'ഹുനൈദത് ബിൻത് ശരീകുബ്നുൽ അബാൻ(റ): ഖുറയ്ബ എന്ന സ്ഥലത്തുവെച്ച് ആഇശ(റ)യെ ഞാൻ കണ്ടുമുട്ടി. അവരോടു ഊറലി (കലങ്ങിയത്, മട്ട്) നെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ എനിക്ക് അത് നിരോധിച്ചിട്ട് അവർ പറഞ്ഞു: പ്രദോഷത്തിൽ വെള്ളത്തിലിട്ടിട്ട് പ്രഭാതത്തിലത് നിങ്ങൾ പാനം ചെയ്യുക. അതിന്റെ വായ് കെട്ടിബന്ധിക്കുകയും ചെയ്യുക. ചുരയ്ക്കാപ്പാത്രവും ഈത്തപ്പന കൊത്തിയുണ്ടാക്കിയ പാത്രവും ടാർപൂശിയ പാത്രവും പച്ച ഭരണിയും അവർ എന്നോട് നിരോധിച്ചു. (ന)', 'هُنَيْدَةَ بِنْتِ شَرِيكِ بْنِ أَبَانَ قَالَتْ', 'ഹുനൈദത് ബിൻത് ശരീകുബ്നുൽ അബാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 613, 614, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنِ ابْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قال: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَبِيذِ الْجَرِّ الْأَخْضَرِ. قُلْتُ: فَالْأَبْيَضُ؟ قَالَ: لَا أَدْرِي. وفي رواية: عن نبيذ الجر الأخضر والأبيض. (ن)', 'ഇബ്നു അബീഔഫാ(റ): റസൂൽ(സ) പച്ചഭരണിയിലെ ജ്യൂസ് നിരോധിച്ചു. ഞാൻ (നിവേദകൻ) ചോദിച്ചു: വെളുത്ത ഭരണിയിലെ ജ്യൂസോ? അദ്ദേഹം പറഞ്ഞു: എനിക്കറിയില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=96), 1, 'وَفِي رِوَايَةٍ: عن نبيذ الجر الأخضر والأبيض. (ن)', 'മറ്റൊരു നിവേദനം: പച്ചഭരണികളിലും വെളുത്തഭരണികളിലുമുള്ള വീഞ്ഞ് റസൂൽ(സ) നിരോധിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ فَتَزَوَّدُوا وَادَّخِرُوا، وَمَنْ أَرَادَ زِيَارَةَ الْقُبُورِ فَإِنَّهَا تُذَكِّرُ الْآخِرَةَ، وَاشْرَبُوا وَاتَّقُوا كُلَّ مُسْكِرٍ". وفي رواية قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا. وَنَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثَةِ أَيَّامٍ، فَأَمْسِكُوا مَا بَدَا لَكُمْ وَنَهَيْتُكُمْ عَنِ النَّبِيذِ إِلَّا فِي سِقَاءٍ، فَاشْرَبُوا فِي الْأَسْقِيَةِ كُلِّهَا وَلَا تَشْرَبُوا مُسْكِرًا". وفي رواية قال: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ ثَلَاثٍ: زِيَارَةِ الْقُبُورِ فَزُورُوهَا، وَلْتَزِدْكُمْ زِيَارَتُهَا خَيْرًا. وَنَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ، فَكُلُوا مِنْهَا مَا شِئْتُمْ. وَنَهَيْتُكُمْ عَنِ الْأَشْرِبَةِ فِي الْأَوْعِيَةِ، فَاشْرَبُوا فِي أَيِّ وِعَاءٍ شِئْتُمْ، وَلَا تَشْرَبُوا مُسْكِرًا". وفي رواية قال: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "كُنْتُ نَهَيْتُكُمْ عَنِ الْأَوْعِيَةِ، فَانْتَبِذُوا فِيمَا بَدَا لَكُمْ، وَإِيَّاكُمْ وَكُلَّ مُسْكِرٍ". و في رواية: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَا هُوَ يَسِيرُ إِذْ حَلَّ بِقَوْمٍ، فَسَمِعَ لَهُمْ لَغَطًا، فَقَالَ: "مَا هَذَا الصَّوْتُ". قَالُوا: يَا نَبِيَّ اللَّهِ، لَهُمْ شَرَابٌ يَشْرَبُونَهُ. فَبَعَثَ إِلَى الْقَوْمِ فَدَعَاهُمْ فَقَالَ: "فِي أَيِّ شَيْءٍ تَنْتَبِذُونَ". قَالُوا: نَنْتَبِذُ فِي النَّقِيرِ وَالدُّبَّاءِ، وَلَيْسَ لَنَا ظُرُوفٌ. فَقَالَ: "لَا تَشْرَبُوا إِلَّا فِيمَا أَوْكَيْتُمْ عَلَيْهِ". قَالَ: فَلَبِثَ بِذَلِكَ مَا شَاءَ اللَّهُ أَنْ يَلْبَثَ، ثُمَّ رَجَعَ عَلَيْهِمْ، فَإِذَا هُمْ قَدْ أَصَابَهُمْ وَبَاءٌ وَاصْفَرُّوا. قَالَ: "مَا لِي أَرَاكُمْ قَدْ هَلَكْتُمْ". قَالُوا: يَا نَبِيَّ اللَّهِ، أَرْضُنَا وَبِيئَةٌ، وَحُرِّمَتْ عَلَيْنَا إِلَّا مَا أَوْكَيْنَا عَلَيْهِ. قَالَ: اشْرَبُوا، وَكُلُّ مُسْكِرٍ حَرَامٌ" (ن)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ഞാൻ ബലിമാംസം നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങളതു കൊണ്ട് പാഥേയം ഒരുക്കുകയും സൂക്ഷിച്ചുവെക്കുകയും ചെയ്തുകൊള്ളുക. ആരെങ്കിലും ഖബർ സന്ദർശനം ഉദ്ദേശിക്കുന്നുവെങ്കിൽ തീർച്ചയായുമത് പരലോകസ്മരണയുണ്ടാക്കുന്നതാണ്. നിങ്ങൾ പാനം ചെയ്യുക, ലഹരിയുണ്ടാക്കുന്നതിനെയെല്ലാം സൂക്ഷിക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=97), 1, 'وَفِي رِوَايَةٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا. وَنَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثَةِ أَيَّامٍ، فَأَمْسِكُوا مَا بَدَا لَكُمْ وَنَهَيْتُكُمْ عَنِ النَّبِيذِ إِلَّا فِي سِقَاءٍ، فَاشْرَبُوا فِي الْأَسْقِيَةِ كُلِّهَا وَلَا تَشْرَبُوا مُسْكِرًا".', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ)അരുളി: "തീർച്ചയായും ഞാൻ ഖബർ സന്ദർശനം നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങൾ ഖബർ സന്ദർശിക്കുക. മൂന്നു ദിവസത്തിനു മീതെ ബലിമാംസം ഉപയോഗിക്കൽ ഞാൻ നിങ്ങളോടു വിലക്കിയിരുന്നു. ഇനി നിങ്ങൾക്ക് തോന്നുന്നിടത്തോളം സൂക്ഷിച്ചു വെച്ചുകൊള്ളുക. തോൽപ്പാത്രത്തിലല്ലാത്ത പാനീയം ഞാൻ നിങ്ങൾക്ക് വിലക്കിയിരുന്നു. ഇനി നിങ്ങൾ എല്ലാതോൽപ്പാത്രങ്ങളിലും കുടിച്ചുകൊള്ളുക. (പക്ഷേ) ലഹരിയുണ്ടാക്കുന്നത് കുടിക്കരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=97), 2, 'وَفِي رِوَايَةٍ قال: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ ثَلَاثٍ: زِيَارَةِ الْقُبُورِ فَزُورُوهَا، وَلْتَزِدْكُمْ زِيَارَتُهَا خَيْرًا. وَنَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ، فَكُلُوا مِنْهَا مَا شِئْتُمْ. وَنَهَيْتُكُمْ عَنِ الْأَشْرِبَةِ فِي الْأَوْعِيَةِ، فَاشْرَبُوا فِي أَيِّ وِعَاءٍ شِئْتُمْ، وَلَا تَشْرَبُوا مُسْكِرًا".', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അരുളി: "മൂന്ന് കാര്യങ്ങൾ ഞാൻ നിരോധിച്ചിരുന്നു. അതിലൊന്നു ഖബർ സന്ദർശനമായിരുന്നു. ഇനിമുതൽ നിങ്ങൾ ഖബർ സന്ദർശിക്കുക. കാരണമത് നിങ്ങൾക്ക് നന്മ വർദ്ധിപ്പിക്കുന്നതാണ്. അപ്രകാരം നിങ്ങൾ മൂന്നു ദിവസത്തിനു ശേഷം ബലിമാംസം ഉപയോഗിക്കുന്നത് നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങൾ ഉദ്ദേശിക്കുന്നിടത്തോളം അതിൽനിന്നും ഭക്ഷിച്ചുകൊള്ളുക. ചിലപാത്രങ്ങളിലുള്ള പാനീയവും ഞാൻ നിങ്ങൾക്ക് വിലക്കിയിരുന്നു. ഇനി നിങ്ങൾ ഉദ്ദേശിക്കുന്ന പാത്രത്തിലെല്ലാം പാനം ചെയ്തുകൊള്ളുക. (പക്ഷേ) ലഹരിയുണ്ടാക്കുന്നത് കുടിക്കരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=97), 3, 'وَفِي رِوَايَةٍ قال: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "كُنْتُ نَهَيْتُكُمْ عَنِ الْأَوْعِيَةِ، فَانْتَبِذُوا فِيمَا بَدَا لَكُمْ، وَإِيَّاكُمْ وَكُلَّ مُسْكِرٍ". و في رواية: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَا هُوَ يَسِيرُ إِذْ حَلَّ بِقَوْمٍ، فَسَمِعَ لَهُمْ لَغَطًا، فَقَالَ: "مَا هَذَا الصَّوْتُ". قَالُوا: يَا نَبِيَّ اللَّهِ، لَهُمْ شَرَابٌ يَشْرَبُونَهُ. فَبَعَثَ إِلَى الْقَوْمِ فَدَعَاهُمْ فَقَالَ: "فِي أَيِّ شَيْءٍ تَنْتَبِذُونَ". قَالُوا: نَنْتَبِذُ فِي النَّقِيرِ وَالدُّبَّاءِ، وَلَيْسَ لَنَا ظُرُوفٌ. فَقَالَ: "لَا تَشْرَبُوا إِلَّا فِيمَا أَوْكَيْتُمْ عَلَيْهِ". قَالَ: فَلَبِثَ بِذَلِكَ مَا شَاءَ اللَّهُ أَنْ يَلْبَثَ، ثُمَّ رَجَعَ عَلَيْهِمْ، فَإِذَا هُمْ قَدْ أَصَابَهُمْ وَبَاءٌ وَاصْفَرُّوا. قَالَ: "مَا لِي أَرَاكُمْ قَدْ هَلَكْتُمْ". قَالُوا: يَا نَبِيَّ اللَّهِ، أَرْضُنَا وَبِيئَةٌ، وَحُرِّمَتْ عَلَيْنَا إِلَّا مَا أَوْكَيْنَا عَلَيْهِ. قَالَ: اشْرَبُوا، وَكُلُّ مُسْكِرٍ حَرَامٌ" (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അരുളി: "ചില പാത്രങ്ങൾ ഞാൻ നിങ്ങൾക്ക് നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങൾക്ക് തോന്നുന്നതിൽ ജ്യൂസുണ്ടാക്കുക. ലഹരിയുണ്ടാക്കുന്ന എല്ലാത്തിനെയും നിങ്ങൾ സൂക്ഷിക്കുകയും ചെയ്യുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=97), 4, null, 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) സവാരി ചെയ്യുന്നതിനിടയിൽ ഒരു സമൂഹത്തിന്റെ അടുക്കൽ എത്തിയപ്പോൾ അവരിൽ നിന്ന് ബഹളം കേൾക്കാനിടയായി. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഇതെന്ത് ശബ്ദമാണ്?" അവർ പറഞ്ഞു: നബിയെ, അവർ ഒരു പാനീയം കുടിച്ചു കൊണ്ടിരിക്കുകയാണ്. പ്രവാചകൻ(സ) ഒരാളെ അയച്ച് അവരെ വിളിപ്പിച്ചിട്ട് ചോദിച്ചു: "ഏത് പാത്രത്തിലാണ് നിങ്ങൾ പാനീയമുണ്ടാക്കുന്നത്?" അവർ പറഞ്ഞു: ഈത്തപ്പനക്കുറ്റി തുരന്നുണ്ടാക്കിയ പാത്രത്തിലും ചുരങ്ങാപ്പാത്രത്തിലും ഞങ്ങൾ പാനീയമുണ്ടാക്കാറുണ്ട്. (ഇതല്ലാതെ) ഞങ്ങൾക്ക് പാത്രങ്ങളില്ല. തദവസരത്തിൽ റസൂൽ(സ) പറഞ്ഞു: "വായ്ഭാഗം കെട്ടപ്പെട്ട പാത്രങ്ങളിൽ മാത്രം നിങ്ങൾ പാനം ചെയ്യുക." അദ്ദേഹം പറയുന്നു: കുറച്ചു കാലത്തിന് ശേഷം തിരുമേനി(സ) അവരിലേക്ക് മടങ്ങിച്ചെന്നു. തദവസരത്തിൽ അവർ പകർച്ചവ്യാധിയും മഞ്ഞപ്പിത്തവും ബാധിച്ചവരായി മാറിയിരുന്നു. റസൂൽ(സ) ചോദിച്ചു: "ഞാൻ നിങ്ങളെ ആപത്ത് ബാധിച്ചവരായി കാണുന്നുവല്ലോ?" അവർ പറഞ്ഞു: പ്രവാചകരേ, ഞങ്ങളുടെ നാട് പകർച്ചവ്യാധി ബാധിച്ച സ്ഥലമാണ്. വായ (ഉപരിതലം) ബന്ധിക്കപ്പെടാത്ത പാത്രങ്ങൾ താങ്കൾ ഞങ്ങൾക്ക് നിഷിദ്ധമാക്കിയിരുന്നു. പ്രവാചകൻ(സ) അരുളി: "നിങ്ങൾ പാനം ചെയ്തുകൊള്ളുക. ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധവുമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُنْتُ نَهَيْتُكُمْ عَنِ الْأَوْعِيَةِ، فَانْتَبِذُوا فِيهِ، وَاجْتَنِبُوا كُلَّ مُسْكِرٍ". (م,ت,ن,جه)', 'ഇബ്നു ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ചില പാത്രങ്ങൾ ഞാൻ നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങളതിൽ പാനീയമുണ്ടാക്കുക. ലഹരിയുണ്ടാക്കുന്നതെല്ലാം വർജ്ജിക്കുകയും ചെയ്യുക." (മു,തു,ന,ജ)', 'بُرَيْدَةَ', 'ഇബ്നു ബുറൈദ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 615, 615, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنِ الظُّرُوفِ، وَإِنَّ ظَرْفًا لَا يُحِلُّ شَيْئًا وَلَا يُحَرِّمُهُ، وَكُلُّ مُسْكِرٍ حَرَامٌ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ചില പാത്രങ്ങൾ ഞാൻ നിങ്ങൾക്ക് വിലക്കിയിരുന്നു. തീർച്ചയായും പാത്രം ഒന്നിനെയും അനുവദനീയമോ, നിഷിദ്ധമോ ആക്കുകയില്ല. ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിഷിദ്ധമാകുന്നു." (മു,ദ,തു,ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 615, 615, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّبِيذِ فِي الْأَوْعِيَةِ، قَالُوا: لَيْسَ كُلُّ النَّاسِ يَجِدُ، فَأَرْخَصَ لَهُمْ فِي الْجَرِّ غَيْرِ الْمُزَفَّتِ. (ق)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ചില പാത്രങ്ങളിൽ പാനീയമുണ്ടാക്കുന്നതിന് റസൂൽ(സ) നിരോധനം ഏർപ്പെടുത്തിയപ്പോൾ ഞങ്ങളുടെ അടുത്ത് തോൽ പാത്രങ്ങൾ ഉണ്ടായിരിക്കുകയില്ലെന്ന് അവർ പറഞ്ഞു. അപ്പോൾ ടാറിടാത്ത തൊട്ടി ഉപയോഗിക്കുവാൻ റസൂൽ(സ) അനുവാദം നൽകി. (ബു,മു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 615, 615, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ جابر بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قال: لَمَّا نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْأَوْعِيَةِ قَالَتِ الْأَنْصَارُ: إِنَّهُ لَا بُدَّ لَنَا، قَالَ: "فَلَا إِذَنْ" (خ,د,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ചില പാത്രങ്ങൾ നിരോധിച്ചപ്പോൾ അൻസാരികൾ പറഞ്ഞു: ഞങ്ങൾക്കതു അനിവാര്യമാണല്ലോ. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എങ്കിൽ വിരോധമില്ല." (ബു,ദ,തു,ജ)', 'جابر بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ جابر بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قال: كَانَ يُنْتَبَذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سِقَاءٍ، فَإِذَا لَمْ يَجِدُوا سِقَاءً نُبِذَ لَهُ فِي تَوْرٍ مِنْ حِجَارَةٍ، فَقَالَ بَعْضُ الْقَوْمِ – وَأَنَا أَسْمَعُ – لِأَبِي الزُّبَيْرِ: مِنْ بِرَامٍ؟ قَالَ: مِنْ بِرَامٍ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): തോൽപ്പാത്രങ്ങളിൽ റസൂൽ(സ)ക്ക് വേണ്ടി ജ്യൂസുണ്ടാക്കുമായിരുന്നു. തോൽപാത്രം ലഭിച്ചില്ലെങ്കിൽ കൽപ്പാത്രങ്ങളിൽ ജ്യൂസുണ്ടാക്കുമായിരുന്നു. അപ്പോൾ ചിലർ ഞാൻ കേൾക്കേ അബൂസുബൈറി(റ)നോടു ചോദിച്ചു: കൽച്ചട്ടിയിലോ? അദ്ദേഹം പറഞ്ഞു: അതെ, കൽച്ചട്ടിയിൽ. (മു)', 'جابر بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنَّا نَنْبِذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سِقَاءٍ تُوكَأُ فِي أَعْلَاهُ، لَهُ عَزْلَاءُ، نَنْبِذُهُ غُدْوَةً وَيَشْرَبُهُ عِشَاءً، وَنَنْبِذُهُ عِشَاءً وَيَشْرَبُهُ غُدْوَةً. حسن. (م,ت)', 'ആഇശ(റ): അടിഭാഗത്ത് ദ്വാരമുള്ള ഉപരിഭാഗം കെട്ടപ്പെട്ട തോൽപ്പാത്രത്തിൽ റസൂൽ(സ)ക്ക് വേണ്ടി ഞങ്ങൾ ജ്യൂസുണ്ടാക്കാറുണ്ടായിരുന്നു. പ്രഭാതത്തിൽ ഞങ്ങൾ ജ്യൂസുണ്ടാക്കുകയും രാത്രിയിൽ അവിടന്ന് കുടിക്കുകയും രാത്രിയിൽ ഞങ്ങൾ ജ്യൂസുണ്ടാക്കുകയും പ്രഭാതത്തിൽ അവിടന്ന് കുടിക്കുകയും ചെയ്യുമായിരുന്നു. (മു,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ خَلِيطِ الزَّهْوِ وَالتَّمْرِ، وَخَلِيطِ الْبُسْرِ وَالتَّمْرِ، وَقَالَ: "لِتَنْبِذُوا كُلَّ وَاحِدٍ مِنْهُمَا عَلَى حِدَةٍ فِي الْأَسْقِيَةِ الَّتِي يُلَاثُ عَلَى أَفْوَاهِهَا". (ن)', 'അബൂഖതാദ(റ): പഴുപ്പ്നിറം കയറിയ ഈത്തപ്പഴത്തിന്റെയും കാരക്കയുടെയും മിശ്രിതവും പഴുക്കാത്ത ഈത്തപ്പഴത്തിന്റെയും കാരക്കയുടെയും മിശ്രിതവും നിരോധിച്ചുകൊണ്ടു റസൂൽ(സ) അരുളി: "വായകൾ ബന്ധിക്കപ്പെട്ട തോൽപ്പാത്രങ്ങളിൽ രണ്ടിൽ നിന്നും വെവ്വേറെ നിങ്ങൾ ജ്യൂസുണ്ടാക്കുക." (ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 616, 616, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قال: عَلِمْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَصُومُ فِي بَعْضِ الْأَيَّامِ الَّتِي كَانَ يَصُومُهَا، فَتَحَيَّنْتُ فِطْرَهُ بِنَبِيذٍ صَنَعْتُهُ فِي دُبَّاءٍ، فَلَمَّا كَانَ الْمَسَاءُ جِئْتُهُ أَحْمِلُهَا إِلَيْهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي قَدْ عَلِمْتُ أَنَّكَ تَصُومُ فِي هَذَا الْيَوْمِ، فَتَحَيَّنْتُ فِطْرَكَ بِهَذَا النَّبِيذِ. فَقَالَ: "أَدْنِهِ مِنِّي يَا أَبَا هُرَيْرَةَ". فَرَفَعْتُهُ إِلَيْهِ فَإِذَا هُوَ يَنِشُّ، فَقَالَ: "خُذْ هَذِهِ فَاضْرِبْ بِهَا الْحَائِطَ، فَإِنَّ هَذَا شَرَابُ مَنْ لَا يُؤْمِنُ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ചില ദിവസങ്ങളിൽ നോമ്പ് അനുഷ്ഠിക്കാറുണ്ടെന്നു ഞാൻ മനസ്സിലാക്കി. അങ്ങനെ ചുരങ്ങാപ്പാത്രത്തിലുണ്ടായിക്കിയ ജ്യൂസുകൊണ്ട് പ്രവാചകനെ നോമ്പുതുറപ്പിക്കാൻ ഞാൻ ഉദ്ദേശിച്ചു. സായാഹ്നമായപ്പോൾ അതുമായി പ്രവാചകൻ(സ)യുടെ അടുക്കൽ ചെന്നിട്ട് ഞാൻ പറഞ്ഞു: ദൈവദൂതരേ, ഈ ദിവസം താങ്കൾ വ്രതമനുഷ്ഠിച്ചിരിക്കുകയാണെന്നു ഞാൻ മനസ്സിലാക്കി. ആയതിനാൽ ഈ ജ്യൂസുകൊണ്ട് താങ്കളെ നോമ്പുതുറപ്പിക്കാൻ ഞാൻ ഉദ്ദേശിക്കുന്നു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അബൂഹുറൈറാ, താങ്കളത് എന്റെ സമീപത്ത് വെക്കൂ." ഞാനതിനെ തിരുദൂതർ(സ)ക്ക് നൽകി. അത് പതഞ്ഞു പൊന്തുന്നുണ്ടായിരുന്നു. തത്സമയം അവിടന്നരുളി: "നീ ഇത് മതിലിൽ എറിയുക. കാരണം, ഇത് അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കാത്തവരുടെ പാനീയമാണ്." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 616, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قال: كَانَ يُنْبَذُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الزَّبِيبُ، فَيَشْرَبُهُ الْيَوْمَ وَالْغَدَ، وَبَعْدَ الْغَدِ إِلَى مَسَاءِ الثَّالِثَةِ، ثُمَّ يَأْمُرُ بِهِ فَيُسْقَى الْخَدَمُ أَوْ يُهَرَاقُ. (م,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)ക്കു വേണ്ടി ഉണക്കമുന്തിരിയുടെ ജ്യൂസുണ്ടാക്കുമായിരുന്നു. പ്രവാചകനത് ആ ദിവസവും പിറ്റേന്നും മൂന്നാം ദിവസം സായാഹ്നം വരെയും കുടിക്കുമായിരുന്നു. പിന്നീട് സേവകന്മാരെ കുടിപ്പിക്കാനോ അല്ലെങ്കിൽ ഒഴിച്ചുകളയാനോ കൽപിക്കുമായിരുന്നു. (മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَبِي ثَابِتٍ الثَّعْلَبِيِّ قَالَ: كُنْتُ عِنْدَ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، فَجَاءَهُ رَجُلٌ فَسَأَلَهُ عَنِ الْعَصِيرِ؟ فَقَالَ: اشْرَبْهُ مَا كَانَ طَرِيًّا. قَالَ: إِنِّي طَبَخْتُ شَرَابًا وَفِي نَفْسِي مِنْهُ. قَالَ: أَكُنْتَ شَارِبَهُ قَبْلَ أَنْ تَطْبُخَهُ؟ قَالَ: لَا قَالَ: فَإِنَّ النَّارَ لَا تُحِلُّ شَيْئًا قَدْ حُرِّمَ. (ن)', 'അബൂസ്സാബിത്തു സ്സഅ്ലബി(റ): ഞാൻ ഇബ്നുഅബ്ബസി(റ)ന്റെയടുക്കൽ ആയിരുന്നപ്പോൾ ഒരാൾ വന്നിട്ട് പിഴിഞ്ഞ നീരിനെക്കുറിച്ച് അദ്ദേഹത്തോടു ചോദിച്ചു. അപ്പോളദ്ദേഹം പറഞ്ഞു: പുതിയതിനെ (ശുദ്ധമായത്) നീ പാനം ചെയ്യുക. അയാൾ പറഞ്ഞു: ഞാൻ പാനീയം പാചകം ചെയ്യാറുണ്ട്, എന്റെ മനസ്സിൽ ഈ വിഷയത്തിൽ ചെറിയ അസ്വസ്ഥതയുമുണ്ട്. ഇബ്നുഅബ്ബാസ്(റ) ചോദിച്ചു. പാചകം ചെയ്യുന്നതിനു മുമ്പ് നീയത് കടിക്കുമായിരുന്നോ? അദ്ദേഹം ഇല്ലായെന്നു മറുപടിപറഞ്ഞു. ഇബ്നുഅബ്ബാസ്(റ) പ്രസ്താവിച്ചു. തീർച്ചയായും നിഷിദ്ധമായ ഒരു വസ്തുവിനെയും തീ അനുവദനീയമാക്കുകയില്ല. (ന)', 'أَبِي ثَابِتٍ الثَّعْلَبِيِّ قَالَ', 'അബൂസ്സാബിത്തു സ്സഅ്ലബി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قال: وَاللَّهِ مَا تُحِلُّ النَّارُ شَيْئًا وَلَا تُحَرِّمُهُ. قَالَ: ثُمَّ فَسَّرَ لِي قَوْلَهُ: لَا تُحِلُّ شَيْئًا، لِقَوْلِهِمْ فِي الطِّلَاءِ. وَلَا تُحَرِّمُهُ: الْوُضُوءُ مِمَّا مَسَّتِ النَّارُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അല്ലാഹു തന്നെ സത്യം, തീ ഒരു വസ്തുവിനെയും അനുവദനീയമോ നിഷിദ്ധമോ ആക്കുകയില്ല. നിവേദകൻ പറയുന്നു. പിന്നീട് അദ്ദേഹം തന്റെ പ്രസ്താവന എനിക്ക് വിശദീകരിച്ചുതന്നു. തിളപ്പിച്ച് വെള്ളം വറ്റിച്ച് രണ്ടിൽ മൂന്നു ഭാഗമാക്കിയ മുന്തിരിച്ചാറി(ത്വിലാഅ്)ന്റെ കാര്യത്തിലുള്ള അവരുടെ വാദത്തിനു മറുപടിയായി തീ ഒന്നിനെയും അനുവദനീയമോ നിഷിദ്ധമോ ആക്കുകയില്ല, അംഗശുദ്ധി (വുളൂഅ്) അഗ്നി സ്പർശിച്ചതിനാലാണ്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ قَالَ: اشْرَبِ الْعَصِيرَ مَا لَمْ يُزْبِدْ. (ن)', 'സഈദുബ്നു മുസയ്യബ്(റ): പതയുണ്ടാകാത്തിടത്തോളം കാലം നീ പിഴിഞ്ഞെടുത്തനീര് കുടിക്കുക. (ന)', 'سَعِيدِ بْنِ الْمُسَيِّبِ قَالَ', 'സഈദുബ്നു മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ هِشَامِ بْنِ عَائِذٍ الْأَسَدِيِّ قَالَ: سَأَلْتُ إِبْرَاهِيمَ عَنِ الْعَصِيرِ؟ قَالَ: اشْرَبْهُ حَتَّى يَغْلِيَ مَا لَمْ يَتَغَيَّرْ. (ن)', 'ഹിഷാമുബ്നു ആഇദിൽ അസദി(റ): ഞാൻ ഇബ്റാഹീമിനോടു പിഴിഞ്ഞെടുത്തനീരിനെ കുറിച്ച് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: വൃതിയാനം സംഭവിക്കാത്തിടത്തോളം, നുരഞ്ഞു പൊന്തുന്നതു വരെ നീയത് കുടിക്കുക. (ന)', 'هِشَامِ بْنِ عَائِذٍ الْأَسَدِيِّ قَالَ', 'ഹിഷാമുബ്നു ആഇദിൽ അസദി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 617, 617, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنِ الشَّعْبِي قَالَ: اشْرَبْهُ ثَلَاثَةَ أَيَّامٍ إِلاَّ أَنْ يَغْلِيَ. (ن)', 'ശഅ്ബി(റ): നുരഞ്ഞുപൊന്തിയില്ലായെങ്കിൽ മൂന്നുദിവസം നീയത് പാനം ചെയ്യുക. (ന)', 'الشَّعْبِي قَالَ', 'ശഅ്ബി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ فَيْرُوزَ الدَّيْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّا أَصْحَابُ كَرْمٍ، وَقَدْ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ تَحْرِيمَ الْخَمْرِ، فَمَاذَا نَصْنَعُ؟ قَالَ: "تَتَّخِذُونَهُ زَبِيبًا" قُلْتُ: فَنَصْنَعُ بِالزَّبِيبِ مَاذَا؟ قَالَ: "تُنْقِعُونَهُ عَلَى غَدَائِكُمْ وَتَشْرَبُونَهُ عَلَى عَشَائِكُمْ، وَتُنْقِعُونَهُ عَلَى عَشَائِكُمْ وَتَشْرَبُونَهُ عَلَى غَدَائِكُمْ" قُلْتُ: أَفَلَا نُوَخِّرُهُ حَتَّى يَشْتَدَّ؟ قَالَ: "لَا تَجْعَلُوهُ فِي الْقُلَلِ وَاجْعَلُوهُ فِي الشِّنَانِ، فَإِنَّهُ إِنْ تَأَخَّرَ صَارَ خَلًّا". وفي رواية قال: قلنا: يَا رَسُولَ اللَّهِ، إِنَّ لَنَا أَعْنَابًا، فَمَاذَا نَصْنَعُ بِهَا؟ قَالَ: "زَبِّبُوهَا" قُلْنَا:: فَمَا نَصْنَعُ بِالزَّبِيبِ؟ قَالَ: "انْبِذُوهُ عَلَى غَدَائِكُمْ وَاشْرَبُوهُ عَلَى عَشَائِكُمْ، وَانْبِذُوهُ عَلَى عَشَائِكُمْ وَاشْرَبُوهُ عَلَى غَدَائِكُمْ، وَانْبِذُوهُ فِي الشِّنَانِ وَلَا تَنْبِذُوهُ فِي الْقِلَالِ، فَإِنَّهُ إِنْ تَأَخَّرَ صَارَ خَلًّا". (ن)', 'ഫൈറൂസുദ്ദയ്ലമി(റ): ഞാൻ റസൂൽ(സ)യുടയടുത്ത് ചെന്നിട്ട് പറഞ്ഞു: പ്രവാചകരേ, ഞങ്ങൾ മുന്തിരിയുടെ ഉപജീവകരാണ്. അല്ലാഹു മദ്യം നിഷിദ്ധമാക്കുന്ന സൂക്തം അവതരിപ്പിച്ചിരിക്കുന്ന ഈ വേളയിൽ ഞങ്ങളെന്ത് ചെയ്യണം? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളതിനെ ഉണക്കമുന്തിരിയാക്കുക." ഞാൻ ചോദിച്ചു: ഉണക്കമുന്തരിയാക്കിയിട്ട് ഞങ്ങളെന്തുചെയ്യും? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളത് പ്രഭാതത്തിൽ വെള്ളത്തിലിട്ട് കുതിർത്തിയിട്ട് പ്രദോഷത്തിൽ പാനം ചെയ്യുക. പ്രദോഷത്തിൽ വെള്ളത്തിലിട്ട് കുതിർത്തിയിട്ട് പ്രഭാതത്തിലും പാനം ചെയ്യുക." ഞാൻ ചോദിച്ചു. അത് വീര്യമുള്ളതാകുന്നതു വരെ ഞങ്ങൾക്ക് പിന്തിക്കാമോ? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളത് വലിയ മൺഭരണികളിലാക്കാതെ പഴകിയ തോൽ പാത്രങ്ങളിലാക്കുക. കാരണം അത് പിന്തിയാൽ സുർക്കയായി മാറുന്നതാണ്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=112), 1, 'وَفِي رِوَايَةٍ قال: قلنا: يَا رَسُولَ اللَّهِ، إِنَّ لَنَا أَعْنَابًا، فَمَاذَا نَصْنَعُ بِهَا؟ قَالَ: "زَبِّبُوهَا" قُلْنَا:: فَمَا نَصْنَعُ بِالزَّبِيبِ؟ قَالَ: "انْبِذُوهُ عَلَى غَدَائِكُمْ وَاشْرَبُوهُ عَلَى عَشَائِكُمْ، وَانْبِذُوهُ عَلَى عَشَائِكُمْ وَاشْرَبُوهُ عَلَى غَدَائِكُمْ، وَانْبِذُوهُ فِي الشِّنَانِ وَلَا تَنْبِذُوهُ فِي الْقِلَالِ، فَإِنَّهُ إِنْ تَأَخَّرَ صَارَ خَلًّا". (ن)', 'മറ്റൊരു നിവേദനം: ഞങ്ങൾ ചോദിച്ചു: റസൂലെ, ഞങ്ങൾക്ക് മുന്തിരികളുണ്ട്. ഞങ്ങൾ അവ എന്തു ചെയ്യണം. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളത് ഉണക്കമുന്തിരിയാക്കുക." ഞങ്ങൾ ചോദിച്ചു: ഉണക്കമുന്തിരി ഞങ്ങൾ എന്തുചെയ്യും. അവിടന്ന് പറഞ്ഞു: "നിങ്ങളത് പ്രഭാതത്തിൽ വെള്ളത്തിലിട്ട് കുതിർത്തി വൈകുന്നേരം കുടിക്കുക. വൈകുന്നേരം വെള്ളത്തിലിട്ട് കുതിർത്തി പ്രഭാതത്തിൽ കുടിക്കുക. വലിയ മൺഭരണികളിലാക്കാതെ പഴകിയ തോൽപാത്രത്തിലാക്കുക. കാരണമത് താമസിച്ചാൽ സുർക്കയാകും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْبَذُ لَهُ نَبِيذُ الزَّبِيبِ مِنَ اللَّيْلِ، فَيَجْعَلُهُ فِي سِقَاءٍ، فَيَشْرَبُهُ يَوْمَهُ ذَلِكَ وَالْغَدَ وَبَعْدَ الْغَدِ، فَإِذَا كَانَ مِنْ آخِرِ الثَّالِثَةِ سَقَاهُ أَوْ شَرِبَهُ، فَإِنْ أَصْبَحَ مِنْهُ شَيْءٌ أَهْرَاقَهُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)ക്ക് വേണ്ടി ഉണക്കമുന്തിരിയുടെ ജ്യൂസ് രാത്രിയിലുണ്ടാക്കുമായിരുന്നു. അനന്തരമത് തോൽ പാത്രത്തിലാക്കും. പ്രവാചകനത് ആ ദിവസവും പിറ്റേന്നും മൂന്നാം ദിവസവും കുടിക്കും. മൂന്നാം ദിവസത്തിന്റെ അവസാനത്തിലും പ്രവാചകനത് കുടിപ്പിക്കുകയോ, അവിടന്ന് കുടിക്കുകയോ ചെയ്യുമായിരുന്നു. പ്രഭാതത്തിലുമത് അവശേഷിച്ചാൽ ഒഴിച്ചുകളയും. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 618, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ كَانَ يُنْبَذُ لَهُ فِي سِقَاءٍ الزَّبِيبُ غُدْوَةً فَيَشْرَبُهُ مِنَ اللَّيْلِ، وَيُنْبَذُ لَهُ عَشِيَّةً فَيَشْرَبُهُ غُدْوَةً، وَكَانَ يَغْسِلُ الْأَسْقِيَةَ وَلَا يَجْعَلُ فِيهَا دُرْدِيًّا وَلَا شَيْئًا. قَالَ نَافِعٌ: فَكُنَّا نَشْرَبُهُ مِثْلَ الْعَسَلِ. (ن)', 'ഇബ്നുഉമർ(റ): പ്രഭാതത്തിൽ അവർക്ക് വേണ്ടി തോൽ പാത്രത്തിൽ ഉണക്കമുന്തിരിയുടെ നീര് ഉണ്ടാക്കുകയും രാത്രിയിലത് കുടിക്കുകയും ചെയ്യുമായിരുന്നു. അപ്രകാരം സായാഹ്നത്തിൽ നീരുണ്ടാക്കി പ്രഭാത്തിൽ പാനം ചെയ്യും. മട്ടോ (അവശിഷ്ടം), മറ്റ് വസ്തുക്കളോ അവശേഷിക്കാത്ത നിലയിൽ തോൽപ്പാത്രങ്ങളവർ കഴുകാറുണ്ടായിരുന്നു. നാഫിഅ് പറയുന്നു. തേൻ പോലുള്ളത് ഞങ്ങൾ കുടിക്കാറുണ്ടായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 618, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ يُنْبَذُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سِقَاءٍ يُوكَأُ أَعْلَاهُ، وَلَهُ عَزْلَاءُ، يُنْبَذُ غُدْوَةً فَيَشْرَبُهُ عِشَاءً، وَيُنْبَذُ عِشَاءً فَيَشْرَبُهُ غُدْوَةً. (م,د,ن)', 'ആഇശ(റ): അടിഭാഗത്ത് ദ്വാരമുള്ളതും ഉപരിഭാഗം കെട്ടപ്പെട്ടതുമായ ഒരു തോൽപാത്രത്തിൽ റസൂൽ(സ)ക്ക് ജ്യൂസുണ്ടാക്കാറുണ്ടായിരുന്നു. പ്രഭാതത്തിൽ വെള്ളത്തിലിട്ട് നീരെടുക്കുകയും പ്രദോഷത്തിൽ പ്രവാചകൻ(സ) അത് പാനം ചെയ്യുകയും അപ്രകാരം പ്രദോഷത്തിൽ വെള്ളത്തിലിട്ട് നീരെടുക്കുകയും പ്രഭാതത്തിൽ പ്രവാചകകൻ(സ) അത് കുടിക്കുകയും ചെയ്യും. (മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا كَانَتْ تَنْبِذُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غُدْوَةً، فَإِذَا كَانَ مِنَ الْعَشِيِّ فَتَعَشَّى شَرِبَ عَلَى عَشَائِهِ، وَإِنْ فَضَلَ شَيْءٌ صَبَبْتُهُ أَوْ فَرَّغْتُهُ. ثُمَّ تَنْبِذُ لَهُ بِاللَّيْلِ، فَإِذَا أَصْبَحَ تَغَدَّى فَشَرِبَ عَلَى غَدَائِهِ، قَالَتْ: يُغْسَلُ السِّقَاءُ غُدْوَةً وَعَشِيَّةً. (د)', 'ആഇശ(റ): തിരുമേനി(സ)ക്ക് അവർ പ്രഭാതത്തിൽ ജ്യൂസുണ്ടാക്കുമായിരുന്നു. വൈകുന്നേരമായാൽ രാത്രി ഭക്ഷണം കഴിക്കുന്നതോടൊപ്പം അത് പാനം ചെയ്തിരുന്നു. എന്തെങ്കിലും ബാക്കിവന്നാൽ ഞാനത് ഒഴിച്ചു കളയുമായിരുന്നു. പിന്നീട് രാത്രിയും റസൂൽ(സ)ക്ക് അവർ ജ്യൂസുണ്ടാക്കുമായിരുന്നു. പ്രഭാതമായാൽ പ്രാതൽ കഴിക്കുന്നതോടൊപ്പം അത് പാനം ചെയ്തിരുന്നു. തുടർന്നു ആഇശ(റ) പറയുന്നു: ആ തോൽപാത്രം രാവിലെയും വൈകുന്നേരവും വൃത്തിയാക്കാറുണ്ട്. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ قَالَ فِي النَّبِيذِ: خَمْرُهُ دُرْدِيُّهُ. (ن)', 'സഈദുബ്നു മുസയ്യബ്(റ): വീഞ്ഞിന്റെ വിഷയത്തിൽ അദ്ദേഹം പ്രസ്താവിച്ചു: അതിലെ മദ്യം അതിന്റെ മട്ടാകുന്നു (ഊറൽ). (ന)', 'سَعِيدِ بْنِ الْمُسَيِّبِ', 'സഈദുബ്നു മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّمَا سُمِّيَتِ الْخَمْرُ لِأَنَّهَا تُرِكَتْ حَتَّى مَضَى صَفْوُهَا وَبَقِيَ كَدَرُهَا. وَكَانَ يَكْرَهُ كُلَّ شَيْءٍ يُنْبَذُ عَلَى عَكَرٍ. (ن)', 'സഈദുബ്നു മുസയ്യബ്(റ): തെളിഞ്ഞ അവസ്ഥ പോയി കലക്ക് ശേഷിക്കുവോളം വെക്കുന്നതുകൊണ്ടാണ് മദ്യത്തിന് ആ നാമം നൽകിയത്. മട്ടിന്റെ മേൽ വീഞ്ഞുണ്ടാക്കുന്ന എല്ലാ വസ്തുക്കളെയും അദ്ദേഹം വെറുത്തിരുന്നു. (ന)', 'سَعِيدِ بْنِ الْمُسَيِّبِ', 'സഈദുബ്നു മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ سُوَيْدِ بْنِ غَفَلَةَ قَالَ: كَتَبَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ إِلَى بَعْضِ عُمَّالِهِ: أَنِ ارْزُقِ الْمُسْلِمِينَ مِنَ الطِّلَاءِ، مَا ذَهَبَ ثُلُثَاهُ وَبَقِيَ ثُلُثُهُ. (ن)', 'സുവൈദുബ്നു ഗഫലത്: ഉമർ(റ) തന്റെ ചില ഉദ്യോഗസ്ഥന്മാർക്കെഴുതി: മൂന്നിൽ രണ്ട് വറ്റിച്ച ശേഷം അവശേഷിച്ച മൂന്നിലൊന്നു മുന്തിരിച്ചാർ മുസ്ലിംകൾക്ക് നൽകുക. (ന)', 'سُوَيْدِ بْنِ غَفَلَةَ قَالَ', 'സുവൈദുബ്നു ഗഫലത്', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ يَكْرَهُ أَنْ يَجْعَلَ نَطْلَ النَّبِيذِ فِي النَّبِيذِ، لِيَشْتَدَّ بِالنَّطْلِ. (ن)', 'സഈദുബ്നു മുസയ്യബ്(റ): വീഞ്ഞ്, വീര്യമുള്ളതാകുന്നതിനു വേണ്ടി അവശേഷിച്ച വീഞ്ഞിനെ അതിൽ ചേർക്കുന്നത് അദ്ദേഹം വെറുത്തിരുന്നു. (ന)', 'سَعِيدِ بْنِ الْمُسَيِّبِ', 'സഈദുബ്നു മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 619, 619, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عَامِرِ بْنِ عَبْدِ اللَّهِ أَنَّهُ قَالَ: قَرَأْتُ كِتَابَ عُمَرَ بْنِ الْخَطَّابِ – رَضِيَ اللَّهُ عَنْهُ – إِلَى أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ: أَمَّا بَعْدُ، فَإِنَّهَا قَدِمَتْ عَلَيَّ عِيرٌ مِنَ الشَّامِ تَحْمِلُ شَرَابًا غَلِيظًا أَسْوَدَ كَطِلَاءِ الْإِبِلِ. وَإِنِّي سَأَلْتُهُمْ عَلَى كَمْ يَطْبُخُونَهُ؟ فَأَخْبَرُونِي أَنَّهُمْ يَطْبُخُونَهُ عَلَى الثُّلُثَيْنِ، ذَهَبَ ثُلُثَاهُ الْأَخْبَثَانِ: ثُلُثٌ بِبَغْيِهِ وَثُلُثٌ بِرِيحِهِ، فَمُرْ مَنْ قِبَلَكَ يَشْرَبُونَهُ. (ن)', 'ആമിറുബ്നു അബ്ദില്ല(റ): അബൂമൂസ(റ)വിന് ഉമർ(റ) അയച്ച കത്ത് ഞാൻ വായിച്ചു: ആമുഖത്തിന് ശേഷം, ചൊറിയുള്ള ഒട്ടകത്തിന് പുരട്ടുന്നകുഴമ്പ് പോലെയുള്ള ഒരു കറുത്തകട്ടിയുള്ള ദ്രാവകം വഹിച്ചുകൊണ്ട് സിറിയയിൽനിന്നുള്ള ഒരു കച്ചവടസംഘം എന്റെ അടുക്കൽ വന്നു. ഞാൻ അവരോടു ചോദിച്ചു: ആ ദ്രാവകം എത്രത്തോളം തിളപ്പിച്ചു? അവരെന്നെ അറിയിച്ചു: മൂന്നിൽ രണ്ട് പോകുന്നത് വരെ തിളപ്പിച്ചു. അങ്ങനെ അതിന്റെ ഏറ്റവുംമോശമായ മൂന്നിൽ രണ്ട് പോകും: മൂന്നിലൊന്നു തിളച്ചുമറിഞ്ഞും മൂന്നിലൊന്നു ഗന്ധമായുമാണ് പോകുന്നത്. നിന്റെ അടുക്കലുള്ള കുടിക്കന്നവരോടും ഇപ്രകാരമറിയിക്കുക. (ന)', 'عَامِرِ بْنِ عَبْدِ اللَّهِ أَنَّهُ قَالَ', 'ആമിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَتَبَ إِلَيْنَا عُمَرُ ابْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: أَمَّا بَعْدُ، فَاطْبُخُوا شَرَابَكُمْ حَتَّى يَذْهَبَ مِنْهُ نَصِيبُ الشَّيْطَانِ، فَإِنَّ لَهُ اثْنَيْنِ، وَلَكُمْ وَاحِدٌ. (ن)', 'അബ്ദുല്ലാഹിബ്നു യസീദുൽഖത്മി(റ): ഉമർ(റ) ഞങ്ങൾക്കെഴുതി: ആമുഖത്തിന് ശേഷം, പിശാചിന്റെ ഓഹരി പാനീയത്തിൽ നിന്ന് പോകുന്നതുവരെ നിങ്ങളതിനെ തിളപ്പിക്കുക. കാരണം അതിൽ പിശാചിന് രണ്ടും, നിങ്ങൾക്ക് ഒന്നുമാണുള്ളത്. (ന)', 'عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ', 'അബ്ദുല്ലാഹിബ്നു യസീദുൽഖത്മി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنِ الشَّعْبِيِّ قَالَ: كَانَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ يَرْزُقُ النَّاسَ الطِّلَاءَ، يَقَعُ فِيهِ الذُّبَابُ وَلَا يَسْتَطِيعُ أَنْ يَخْرُجَ مِنْهُ. (ن)', 'ശഅ്ബി(റ) പറയുന്നു: ഈച്ച വീണാൽ അതിന് രക്ഷപ്പെടാൻ കഴിയാത്ത നിലയിലായ മൂന്നിലൊന്ന് വറ്റിച്ച മുന്തിരിച്ചാർ അലി(റ) ജനങ്ങൾക്കു നൽകിയിരുന്നു. (ന)', 'الشَّعْبِيِّ قَالَ', 'ശഅ്ബി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قال: إِنَّ نُوحًا نَازَعَهُ الشَّيْطَانُ فِي عُودِ الْكَرْمِ، فَقَالَ: هَذَا لِي. وَقَالَ: هَذَا لِي. فَاصْطَلَحَا عَلَى أَنَّ لِنُوحٍ ثُلُثَهَا وَلِلشَّيْطَانِ ثُلُثَيْهَا. (ن)', 'അനസുബ്നു മാലിക്(റ): മുന്തിരിയുടെ കാണ്ഡത്തെക്കുറിച്ച് പിശാച് നൂഹ്(അ)മിനോടു തർക്കിച്ചു. അവരിരുവരും ഇതെനിക്ക് വേണം, ഇതെനിക്ക് വേണം എന്നു പറഞ്ഞു. അങ്ങനെ നൂഹ്(അ)മിന് മൂന്നിലൊന്ന്, പിശാചിന് മൂന്നിൽ രണ്ട് എന്ന വ്യവസ്ഥയിൽ അവരിരുവരും യോജിപ്പിലെത്തി. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ طَاوُسٍ: أَنَّهُ كَانَ يَكْرَهُ أَنْ يَبِيعَ الزَّبِيبَ لِمَنْ يَتَّخِذُهُ نَبِيذًا. (ن)', 'ത്വാഊസ്(റ): വീഞ്ഞ് നിർമ്മിക്കുന്നവന് ഉണക്കമുന്തിരി വിൽക്കൽ അദ്ദേഹം വെറുക്കുമായിരുന്നു.(ന)', 'طَاوُسٍ', 'ത്വാഊസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 620, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ مُصْعَبِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ – رَضِيَ اللَّهُ عَنْهُ – قَالَ: كَانَ لِسَعْدٍ كُرُومٌ وَأَعْنَابٌ كَثِيرَةٌ، وَكَانَ لَهُ فِيهَا أَمِينٌ، فَحَمَلَتْ عِنَبًا كَثِيرًا، فَكَتَبَ إِلَيْهِ: إِنِّي أَخَافُ عَلَى الْأَعْنَابِ الضَّيْعَةَ، فَإِنْ رَأَيْتَ أَنْ أَعْصِرَهُ عَصَرْتُهُ. فَكَتَبَ إِلَيْهِ سَعْدٌ: إِذَا جَاءَكَ كِتَابِي هَذَا فَاعْتَزِلْ ضَيْعَتِي، فَوَاللَّهِ لَا أَئْتَمِنُكَ عَلَى شَيْءٍ بَعْدَهُ أَبَدًا. فَعَزَلَهُ عَنْ ضَيْعَتِهِ. (ن)', 'മുസ്അബുബ്നു സഅദിബ്നു അബീവഖാസ്(റ): സഅ്ദ്(റ)വിന് ധാരാളം മുന്തിരി വള്ളികളും മുന്തിരിയുമുണ്ടായിരുന്നു. അദ്ദേഹത്തിന് അതിൽ ഒരു കാവൽക്കാരനുണ്ടായിരുന്നു. മുന്തിരി വള്ളികളിൽ ധാരാളം മുന്തിരിയുമുണ്ട്. അങ്ങനെ ആ കാവൽക്കാരൻ സഅ്ദ്(റ)വിനു എഴുതി: നിശ്ചയം മുന്തിരി നശിക്കുമെന്ന് ഞാൻ ഭയപ്പെടുന്നു. അത് പിഴിഞ്ഞ് നീരെടുക്കണമെന്നാണ് താങ്കളുടെ അഭിപ്രായമെങ്കിൽ ഞാനപ്രകാരം ചെയ്യുന്നതാണ്. അപ്പോൾ സഅ്ദ്(റ) അദ്ദേഹത്തിന് മറുപടി എഴുതി: എന്റെ കത്ത് നിനക്ക് കിട്ടിയാൽ നീ ജോലിയിൽനിന്ന് ഒഴിഞ്ഞ് പോകുക. അല്ലാഹു സത്യം! ഇതിനു ശേഷം ഒരുകാര്യത്തിലും നിന്നെ എനിക്ക് വിശ്വാസത്തിലെടുക്കാനാവില്ല. അങ്ങനെ സഅ്ദ്(റ) അദ്ദേഹത്തെ ജോലിയിൽനിന്നും പിരിച്ചുവിട്ടു. (ന)', 'مُصْعَبِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ –', 'മുസ്അബുബ്നു സഅദിബ്നു അബീവഖാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 620, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ جابرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُنْبَذُ لَهُ فِي تَوْرٍ مِنْ حِجَارَةٍ. (ن)', 'ജാബിർ(റ): പ്രവാചകൻ(സ)ക്ക് വേണ്ടി വലിയ കൽപാത്രങ്ങളിൽ ജ്യൂസുണ്ടാക്കാറുണ്ടായിരുന്നു. (ന)', 'جابرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10001, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ لِأُمِّ سُلَيْمٍ قَدَحٌ مِنْ عَيْدَانٍ، فَقَالَتْ: سَقَيْتُ فِيهِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّ الشَّرَابِ: الْمَاءَ وَالْعَسَلَ وَاللَّبَنَ وَالنَّبِيذَ. (م,ن)', 'അനസ്(റ): ഉമ്മുസലൈം(റ)ക്ക് മരക്ഷണത്താലുള്ള ഒരു പാത്രമുണ്ടായിരുന്നു. അവർ പറയുന്നു: ഞാൻ ആ പാത്രത്തിൽ വെള്ളം, തേൻ, പാൽ, ജ്യൂസ് തുടങ്ങി എല്ലാപാനീയങ്ങളും റസൂൽ(സ)ക്ക് കുടിക്കാൻ കൊടുത്തു. (മു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, 'بدون رقم (بعد 127)', array['م','ن']::text[], array['മു','ന']::text[], null, null, 621, 621, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ أُبَيَّ بْنَ كَعْبٍ عَنِ النَّبِيذِ؟ فَقَالَ: اشْرَبِ الْمَاءَ وَاشْرَبِ الْعَسَلَ، وَاشْرَبِ السَّوِيقَ، وَاشْرَبِ اللَّبَنَ الَّذِي نُجِعْتَ بِهِ، فَعَاوَدْتُهُ. فَقَالَ: الْخَمْرَ تُرِيدُ، الْخَمْرَ تُرِيدُ. (ن)', 'അബ്ദുറഹ്മാനുബ്നു അബ്സാ(റ): ഞാൻ ഉബയ്യുബ്നു കഅ്ബ്(റ)വിനോടു ജ്യൂസിനെക്കുറിച്ച് ചോദിച്ചു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: വെള്ളവും തേനും തരിക്കഞ്ഞിയും (ധാന്യപ്പൊടികൊണ്ടുള്ള കഞ്ഞി) നിനക്ക് ഗുണപ്രദമായ പാലും നീ പാനം ചെയ്യുക. അപ്പോൾ ഞാൻ അദ്ദേഹത്തോടു ചോദ്യമാവർത്തിച്ചു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: മദ്യമാണോ നീ ഉദ്ദേശിക്കുന്നത്. മദ്യമാണോ നീ ഉദ്ദേശിക്കുന്നത്. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى', 'അബ്ദുറഹ്മാനുബ്നു അബ്സാ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عبد الله بن مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَحْدَثَ النَّاسُ أَشْرِبَةً مَا أَدْرِي مَا هِيَ، فَمَا لِي شَرَابٌ مُنْذُ عِشْرِينَ سَنَةً – أَوْ قَالَ: أَرْبَعِينَ سَنَةً – إِلَّا الْمَاءُ وَالسَّوِيقُ. غَيْرَ أَنَّهُ لَمْ يَذْكُرِ النَّبِيذَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ജനങ്ങൾ ചില പാനീയങ്ങൾ പുതുതായി നിർമ്മിക്കുന്നു. അവയെന്താണെന്നെനിക്കറിയില്ല. വെള്ളവും തരിക്കഞ്ഞിയുമല്ലാതെ മറ്റൊരുപാനീയവും ഇരുപത് വർഷമായിട്ട് അല്ലെങ്കിൽ നാല്പത് വർഷമായിട്ട് എനിക്കില്ല അദ്ദേഹം വീഞ്ഞിനെ ക്കുറിച്ച് പരാമർശിച്ചില്ല. (ന)', 'عبد الله بن مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 621, 621, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عَبِيدَةَ بْنِ عَمْرٍو السلماني قَالَ: أَحْدَثَ النَّاسُ أَشْرِبَةً مَا أَدْرِي مَا هِيَ، وَمَا لِي شَرَابٌ مُنْذُ عِشْرِينَ سَنَةً إِلَّا الْمَاءُ وَاللَّبَنُ وَالْعَسَلُ. (ن)', 'അബീദത്തുബ്നു അംറ്(റ): ജനങ്ങൾ ചില പാനീയങ്ങൾ പുതുതായി ഉണ്ടാക്കുന്നു. അവയെന്താണെന്ന് എനിക്കറിയില്ല. ഇരുപത് വർഷമായിട്ട് വെള്ളവും പാലും തേനുമല്ലാതെ ഒരുപാനീയവും ഞാൻ ഉപയോഗിച്ചിട്ടില്ല. (ന)', 'عَبِيدَةَ بْنِ عَمْرٍو السلماني قَالَ', 'അബീദത്തുബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 621, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَبْدِ اللَّهِ بْنِ شُبْرُمَةَ قَالَ: قَالَ طَلْحَةُ رَضِيَ اللَّهُ عَنْهُ لِأَهْلِ الْكُوفَةِ: فِي النَّبِيذِ فِتْنَةٌ يَرْبُو فِيهَا الصَّغِيرُ وَيَهْرَمُ فِيهَا الْكَبِيرُ. قَالَ: وَكَانَ إِذَا كَانَ فِيهِمْ عُرْسٌ كَانَ طَلْحَةُ وَزُبَيْرٌ يَسْقِيَانِ اللَّبَنَ وَالْعَسَلَ. فَقِيلَ لِطَلْحَةَ: أَلَا تَسْقِيهِمُ النَّبِيذَ؟ قَالَ: إِنِّي أَكْرَهُ أَنْ يَسْكَرَ مُسْلِمٌ فِي سَبَبِي. قَالَ: كَانَ ابْنُ شُبْرُمَةَ لَا يَشْرَبُ إِلَّا الْمَاءَ وَاللَّبَنَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ശുബ്റുമത്(റ): ത്വൽഹ(റ) കൂഫാനിവാസികളോടു പറഞ്ഞു: ജ്യൂസിൽ ചില ദൂഷ്യങ്ങളുണ്ട്. ആ ദൂഷ്യത്തിൽ ചെറിയവൻ വളരുകയും വലിയവൻ വൃദ്ധനാവുകയും ചെയ്യും. നിവേദകൻ പറയുന്നു. അവരിൽ വവാഹസദ്യ ഉണ്ടായാൽ ത്വൽഹ(റ)യും സുബൈർ(റ)വും പാലും തേനും കുടിപ്പിക്കാറുണ്ടായിരുന്നു. ത്വൽഹ(റ)യോടു ചോദിക്കപ്പെട്ടു: അവർക്ക് ജ്യൂസ് കുടിപ്പിക്കുന്നില്ലേ? അദേഹം പറഞ്ഞു: ഞാൻ കാരണമായി ഒരു മുസ്ലിം ലഹരി ബാധിതനാകുന്നത് ഞാൻ വെറുക്കുന്നു. ജരീർ(റ) പറയുന്നു: ഇബ്നുശുബ്റുമത്(റ) വെള്ളവും പാലുമല്ലാതെ മറ്റൊന്നും കുടിച്ചിരുന്നില്ല. (ന)', 'عَبْدِ اللَّهِ بْنِ شُبْرُمَةَ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ശുബ്റുമത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ لَيْلَةَ أُسْرِيَ بِهِ بِإِيلِيَاءَ بِقَدَحَيْنِ مِنْ خَمْرٍ وَلَبَنٍ، فَنَظَرَ إِلَيْهِمَا فَأَخَذَ اللَّبَنَ، فَقَالَ لَهُ جِبْرِيلُ عَلَيْهِ السَّلَامُ: الْحَمْدُ لِلَّهِ الَّذِي هَدَاكَ لِلْفِطْرَةِ، لَوْ أَخَذْتَ الْخَمْرَ غَوَتْ أُمَّتُكَ . (م)', 'അബൂഹുറൈറ(റ): നിശാസഞ്ചാരം നടത്തിയ രാത്രിയിൽ ഈലിയാവിൽ വെച്ച് മദ്യത്തിന്റെയും പാലിന്റെയും രണ്ട് പാത്രങ്ങൾ പ്രവാചകൻ(സ)ക്ക് നൽകപ്പെട്ടു. റസൂൽ(സ) രണ്ടും വീക്ഷിച്ചതിനു ശേഷം പാലിന്റെ പാത്രം വാങ്ങി.. തൽസമയം ജിബ്രീൽ(അ) പ്രവാചകൻ(സ)യോടു പറഞ്ഞു: ശുദ്ധ പ്രകൃതിയിലേക്ക് താങ്കൾക്ക് മാർഗദർശനം നൽകിയ അല്ലാഹുവിനാകുന്നു സർവ്വസ്തുതിയും. താങ്കൾ മദ്യം തിരഞ്ഞെടുത്തിരുന്നുവെങ്കിൽ താങ്കളുടെ സമുദായം വഴിപിഴക്കുമായിരുന്നു. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا أَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ، قَالَ: فَأَتْبَعَهُ سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ، قَالَ: فَدَعَا عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَاخَتْ فَرَسُهُ، فَقَالَ: ادْعُ اللَّهَ لِي وَلَا أَضُرُّكَ، قَالَ: فَدَعَا اللَّهَ، قَالَ: فَعَطِشَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَرُّوا بِرَاعِي غَنَمٍ، قَالَ أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ: فَأَخَذْتُ قَدَحًا، فَحَلَبْتُ فِيهِ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُثْبَةً مِنْ لَبَنٍ، فَأَتَيْتُهُ بِهِ فَشَرِبَ حَتَّى رَضِيتُ. (م)', 'ബറാഅ്(റ): റസൂൽ(സ) മക്കയിൽ നിന്നു മദീനയിലേക്ക് പോയപ്പോൾ സുറാകതുബ്നു മാലികിബ്നി ജുഅ്ഷം എന്ന വ്യക്തി റസൂൽ(സ)യെ അനുഗമിച്ചു. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തിനെതിരെ പ്രാർത്ഥിക്കുകയും തൽഫലമായി അദ്ദേഹത്തിന്റെ കുതിരയുടെ കാല് ഭൂമിയിലേക്ക് ആണ്ട് പോവുകയും ചെയ്തു. അപ്പോൾ അയാൾ തിരുമേനി(സ)യോട് അപേക്ഷിച്ചു: താങ്കൾ എനിക്കനുകൂലമായി പ്രാർത്ഥിച്ചാലും, ഞാൻ താങ്കളെ ഉപദ്രവിക്കുകയില്ല. അങ്ങനെ അവിടന്ന് അല്ലാഹുവിനോടു പ്രാർത്ഥിച്ചു. അനന്തരം പ്രവാചകൻ(സ)ക്ക് ദാഹം അനുഭവപ്പെടുകയും അവർ ഒരാട്ടിടയന്റെ സമീപത്ത് എത്തുകയും ചെയ്തു. അബൂബക്കർ(റ) പറയുന്നു: ഞാനൊരുപാത്രമെടുത്ത് പ്രവാചകൻ(സ)ക്ക് വേണ്ടി കുറച്ച് പാൽ കറന്നെടുത്ത് പ്രവാചകൻ(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുവന്നു. അപ്പോൾ എനിക്ക് സംതൃപ്തി തോന്നുന്നത് വരെ റസൂൽ(സ) കുടിച്ചു. (മു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 622, 622, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنْتُ فِي بَيْتِ مَيْمُونَةَ رَضِيَ اللَّهُ عَنْهَا، فَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ خَالِدُ ابْنُ الْوَلِيدِ، فَجَاءُوا بِضَبَّيْنِ مَشْوِيَّيْنِ عَلَى ثُمَامَتَيْنِ، فَتَبَزَّقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ خَالِدٌ: إِخَالُكَ تَقْذُرُهُ يَا رَسُولَ اللَّهِ؟ قَالَ: "أَجَلْ". ثُمَّ أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بلبن فشرب، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلْيَقُلْ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ، وَأَطْعِمْنَا خَيْرًا مِنْهُ. وَإِذَا سُقِيَ لَبَنًا فَلْيَقُلْ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ، وَزِدْنَا مِنْهُ. فَإِنَّهُ لَيْسَ شَيْءٌ يُجْزِئُ مِنَ الطَّعَامِ وَالشَّرَابِ إِلَّا اللَّبَنُ". (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ മൈമുന(റ)യുടെ വീട്ടിലായിരുന്നു. അപ്പോൾ റസൂൽ(സ) ഖാലിദുബ്നു വലീദ്(റ)വിനോടൊപ്പം കടന്നുവന്നു. രണ്ട് ചാമപ്പുല്ലുകളുടെ മേൽ ചുട്ട രണ്ട് ഉടുമ്പിനെ അവർ കൊണ്ടുവന്നു. തൽസമയം റസൂൽ(സ) തുപ്പി. അപ്പോൾ ഖാലിദ്(റ) ചോദിച്ചു: ദൈവദൂതരേ, താങ്കൾ അത് വെറുക്കുന്നുവെന്ന് എനിക്ക് തോന്നുന്നല്ലോ? റസൂൽ(സ) "അതെ" എന്ന് മറുപടി പറഞ്ഞു. പിന്നീട് പ്രവാചകൻ(സ)ക്ക് കുറച്ച് പാൽ കൊണ്ടുവരുകയും അവിടന്ന് അത് കുടിക്കുകയും ചെയ്തു. ശേഷം അവിടന്നരുളി: "നിങ്ങളാരെങ്കിലും ഭക്ഷണം കഴിച്ചാൽ അവൻ പറയട്ടെ, അല്ലാഹുവേ നീ ഞങ്ങൾക്കിതിൽ ഐശ്വര്യം ചൊരിയുകയും ഇതിനേക്കാൾ വിശിഷ്ടമായത് ഭക്ഷിപ്പിക്കുകയും ചെയ്യേണമേ. ആർക്കെങ്കിലും പാല് കുടിപ്പിക്കപ്പെട്ടാൽ അവൻ പറഞ്ഞുകൊള്ളട്ടെ, അല്ലാഹുവേ നീ ഞങ്ങൾക്കിതിൽ ഐശ്വര്യം ചൊരിയുകയും ഇത് വർദ്ധിപ്പിക്കുകയും ചെയ്യേണമേ. കാരണം തീർച്ചയായും ഭക്ഷണ പാനീയങ്ങളിൽ പാലിനോളം പര്യാപ്തമായ മറ്റൊരു വസ്തുവുമില്ല." (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 622, 623, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نِعْمَ الصَّدَقَةُ اللِّقْحَةُ الصَّفِيُّ مِنْحَةً، وَالشَّاةُ الصَّفِيُّ مِنْحَةً، تَغْدُو بِإِنَاءٍ، وَتَرُوحُ بِآخَرَ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രഭാതത്തിലും സായാഹ്നത്തിലും ഓരോ പാത്രം പാൽ പ്രധാനം ചെയ്യുന്ന ധാരാളം പാലുള്ള ഒട്ടകവും ധാരാളം പാലുള്ള ആടും ദാനം ചെയ്യുന്നത് ഒരുത്തമ ദാനമത്രെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 623, 623, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْكُثُ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ فَيَشْرَبُ عِنْدَهَا عَسَلًا، فَتَوَاصَيْتُ أَنَا وَحَفْصَةُ: أَيَّتُنَا مَا دَخَلَ عَلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلْتَقُلْ: إِنِّي أَجِدُ مِنْكَ رِيحَ مَغَافِيرَ فَدَخَلَ عَلَى إِحْدَاهُنَّ، فَقَالَتْ لَهُ ذَلِكَ، فَقَالَ: "شَرِبْتُ عَسَلًا عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، وَلَنْ أَعُودَ لَهُ". فَنَزَلَتْ: {لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي} إِلَى: {إِنْ تَتُوبَا إِلَى اللَّهِ} لِعَائِشَةَ وَحَفْصَةَ رَضِيَ اللَّهُ عَنْهُمَا: {وَإِذْ أَسَرَّ النَّبِيُّ إِلَى أَزْوَاجِهِ حَدِيثًا} لِقَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَلْ شَرِبْتُ عَسَلًا". (ق,د,ن)', 'ആഇശ(റ): റസൂൽ(സ) സൈനബബിൻതു ജഹ്ശ്(റ)വിന്റെ അടുക്കൽ താമസിക്കുകയും അവിടെനിന്ന് തേൻ കുടിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഞാനും ഹഫ്സ(റ)യും കൂടി ഒരു തീരുമാനമെടുത്തു. നമ്മിൽ ആരുടെ അടുക്കൽ നബി(സ) കടന്നുവന്നാലും അവർ ഇപ്രകാരം പറയണം: എനിക്ക് താങ്കളിൽ നിന്ന് മഗാഫീറി (ഒരുവൃക്ഷത്തിന്റെ കറയാണത്. രുചി മധുരവും ഗന്ധം മോശവുമാണ്) ന്റെ വാസന അനുഭവപ്പെടുന്നുവല്ലൊ? അങ്ങനെ നബി(സ) ഒരാളുടെയടുക്കൽ ചെന്നപ്പോൾ അവർ അപ്രകാരം പറഞ്ഞു. തദവസരത്തിൽ നബി(സ) പറഞ്ഞു: "ഞാൻ സൈനബയുടെയടുക്കൽ നിന്ന് തേൻ കഴിച്ചിരുന്നു. ഇനി അതിന് (തേനിന്) വേണ്ടി ഞാൻ പോകുകയില്ല." അപ്പോൾ ''അല്ലാഹു താങ്കൾക്ക് അനുവദിച്ചു തന്നത് എന്തിനാണ് താങ്കൾ നിഷിദ്ധമാക്കുന്നത്'' എന്നത് മുതൽ ''നിങ്ങൾ അല്ലാഹുവിലേക്ക് പശ്ചാത്തപിച്ചു മടങ്ങുന്നുവെങ്കിൽ'' എന്നതു വരെയുള്ള സൂക്തങ്ങൾ ആഇശ(റ)യുടെയും ഹഫ്സ(റ)യുടെയും പേരിൽ അവതീർണ്ണമായി. എന്നാൽ "ഞാൻ തേൻ കുടിച്ചു" എന്ന പ്രവാചക വചനം കാരണമായി, ''റസൂൽ(സ) തന്റെ ഭാര്യമാരോട് രഹസ്യമായി ഒരുകാര്യം പറഞ്ഞു'' എന്നസൂക്തം അവതരിച്ചു. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 623, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ الْحَلْوَاءَ وَالْعَسَلَ، فَذَكَرَ بَعْضَ هَذَا الْخَبَرِ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْتَدُّ عَلَيْهِ أَنْ تُوجَدَ مِنْهُ الرِّيحُ، وَفِي هَذَا الْحَدِيثِ قَالَتْ سَوْدَةُ: بَلْ أَكَلْتَ مَغَافِيرَ، قَالَ: "بَلْ شَرِبْتُ عَسَلًا، سَقَتْنِي حَفْصَةُ". فَقُلْتُ: جَرَسَتْ نَحْلُهُ الْعُرْفُطَ نَبْتٌ مِنْ نَبْتِ النَّحْلِ. (ق,د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) തേനും ഹലുവയും ഇഷ്ടപ്പെട്ടിരുന്നു. അനന്തരം നിവേദകൻ ഈ ഹദീസിന്റെ കുറച്ചുഭാഗം പരാമർശിച്ചു... തന്നിൽ നിന്ന് ദുർഗന്ധം ആനുഭവപ്പെടുകയെന്നത് പ്രവാചകൻ(സ)ക്ക് അസഹ്യമായിരുന്നു. സൗദ(റ) പറഞ്ഞു: താങ്കൾ മഗാഫീറാണ് കഴിച്ചത്. റസൂൽ(സ) മറുപടി നൽകി. "അല്ല, ഹഫ്സയെന്നെ കുടിപ്പിച്ച തേനാണ് ഞാൻ കുടിച്ചത്." ഞാൻ പറഞ്ഞു: പ്രസ്തുത തേനിന്റെ ഈച്ച ''ഉർഫുത്'' ചെടിയിൽ നിന്നാണ് തേൻ ശേഖരിച്ചിരുന്നത്. സാധാരണയായി ഈച്ചകൾ തേൻ ശേഖരിക്കാറുള്ള ചെടിയാണ് ''ഉർഫുത്''. (ബു,മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَبِي بُرْدَةَ بْنِ نِيَارٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اشْرَبُوا فِي الظُّرُوفِ وَلَا تَسْكَرُوا". وَهَذَا حَدِيثٌ مُنْكَرٌ. (ن)', 'അബൂബുർദതുബ്നു നിയാർ(റ): റസൂൽ(സ) അരുൾ ചെയ്തു: "പാത്രങ്ങളിൽ നിങ്ങൾ പാനം ചെയ്യുക. (പക്ഷേ) നിങ്ങൾ ലഹരി ബാധിതരാകരുത്." ഈ ഹദീസ് മുൻകർ (അസ്വീകാര്യം) ആണ്. (ന)', 'أَبِي بُرْدَةَ بْنِ نِيَارٍ', 'അബൂബുർദതുബ്നു നിയാർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: اشْرَبُوا وَلَا تَسْكُرُوا. قَالَ أَبُو عَبْدِ الرَّحْمَنِ: وَهَذَا أَيْضًا غَيْرُ ثَابِتٍ. (ن)', 'ആയിശ(റ): നിങ്ങൾ കുടിക്കുക. നിങ്ങൾ ലഹരി ബാധിതരാകരുത്.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: سَأَلَهَا أُنَاسٌ، كُلُّهُمْ يَسْأَلُ عَنِ النَّبِيذِ، يَقُولُ: نَنْبِذُ التَّمْرَ غُدْوَةً وَنَشْرَبُهُ عَشِيًّا، وَنَنْبِذُهُ عَشِيًّا وَنَشْرَبُهُ غُدْوَةً؟ قَالَتْ: لَا أُحِلُّ مُسْكِرًا وَإِنْ كَانَ خُبْزًا، وَإِنْ كَانَتْ مَاءً. قَالَتْهَا ثَلَاثَ مَرَّاتٍ. (ن)', 'ആഇശ(റ): ചില ആളുകൾ അവരോടു ചോദിച്ചു, എല്ലാവരും ചോദിക്കുന്നത് വീഞ്ഞിനെ സംബന്ധിച്ചാണ്. അവർ പറയും: ഞങ്ങൾ കാരക്ക പ്രഭാതത്തിൽ വെള്ളത്തിലിട്ട് നീരെടുക്കുകയും പ്രദോഷത്തിൽ കുടിക്കുകയും ചെയ്യുന്നു. അപ്രകാരം സായാഹ്നത്തിൽ വെള്ളത്തിലിട്ട് നീരെടുക്കുകയും പ്രഭാതത്തിൽ കുടിക്കുകയും ചെയ്യുന്നു. ആഇശ(റ) മറുപടി പറഞ്ഞു: ലഹരിയുണ്ടാക്കുന്നതിനെ ഞാൻ അനുവദനീയമാക്കുകയില്ല. അത് റൊട്ടിയായാലും, വെള്ളമായാലും ശരി.. ആഇശ(റ) മൂന്നു പ്രാവശ്യം ഇപ്രകാരം പറഞ്ഞു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: نُهِيتُمْ عَنِ الدُّبَّاءِ، نُهِيتُمْ عَنِ الْحَنْتَمِ، نُهِيتُمْ عَنِ الْمُزَفَّتِ. ثُمَّ أَقْبَلَتْ عَلَى النِّسَاءِ فَقَالَتْ: إِيَّاكُنَّ وَالْجَرَّ الْأَخْضَرَ، وَإِنْ أَسْكَرَكُنَّ مَاءُ حُبِّكُنَّ فَلَا تَشْرَبْنَهُ. (ن)', 'ആഇശ(റ): ചുരങ്ങപ്പാത്രം, പച്ചഭരണി, ടാർപൂശിയ പാത്രം എന്നിവയെല്ലാം നിങ്ങൾക്ക് നിരോധിക്കപ്പെട്ടിരിക്കുന്നു. അനന്തരമവർ സ്ത്രീകളുടെ അടുക്കൽ ചെന്നിട്ട് പറഞ്ഞു: നിങ്ങളെയും പച്ചഭരണികളെയും സൂക്ഷിക്കുക, നിങ്ങളുടെ വലിയതൊട്ടിയിലെ വെള്ളം ലഹരിയുണ്ടാക്കുന്നതാണെങ്കിൽ നിങ്ങളത് കുടിക്കരുത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سُئِلَتْ عَنِ الْأَشْرِبَةِ؟ فَقَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ كُلِّ مُسْكِرٍ. (ن)', 'ആഇശ(റ): അവരോടു പാനീയങ്ങളെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു: അവർ പറഞ്ഞു: റസൂൽ(സ) ലഹരിയുണ്ടാക്കുന്നതെല്ലാം നിരോധിച്ചിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: حُرِّمَتِ الْخَمْرُ – بِعَيْنِهَا – قَلِيلُهَا وَكَثِيرُهَا. وَالسُّكْرُ مِنْ كُلِّ شَرَابٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): മദ്യം അതെത്ര അൽപമായാലും അധികമായാലും നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കുന്നു. അപ്രകാരംതന്നെ എല്ലാ പാനീയങ്ങളിൽ നിന്നുമുള്ള ലഹരിയും. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، سُئِلَ – وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى الْكَعْبَةِ – عَنِ الْبَاذَقِ؟ فَقَالَ: سَبَقَ مُحَمَّدٌ الْبَاذَقَ، وَمَا أَسْكَرَ فَهُوَ حَرَامٌ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): കഅബയിലേക്ക് ചാരിയിരിക്കുന്ന സന്ദർഭത്തിൽ അവരോട് ബാദകി (ചൂടാക്കിയ മുന്തിരിവീഞ്ഞ്)നെ ക്കുറിച്ചു ചോദിച്ചു. അപ്പോളദ്ദേഹം പറഞ്ഞു: മുഹമ്മദ് (സ) ബാദകിനെ സംബന്ധിച്ച് മുമ്പേ പരാമർശിച്ചിട്ടുണ്ട്. ലഹരിയുണ്ടാക്കുന്നത് നിഷിദ്ധമാകുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَنْ سَرَّهُ أَنْ يُحَرِّمَ – إِنْ كَانَ مُحَرِّمًا مَا حَرَّمَ اللهُ وَرَسُولُهُ – فَلْيُحَرِّمِ النَّبِيذَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അല്ലാഹുവും അവന്റെ ദൂതനും നിഷിദ്ധമാക്കിയതിനെ, നിഷിദ്ധമാക്കുന്നത് വല്ലവനെയും സന്തോഷിപ്പിക്കുന്നുവെങ്കിൽ അവൻ വീഞ്ഞിനെ നിഷിദ്ധമാക്കികൊള്ളട്ടെ. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ جُوشَنٍ الْغَطَفَانِي قَالَ: قَالَ رَجُلٌ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا إِنِّي امْرُؤٌ مِنْ أَهْلِ خُرَاسَانَ، وَإِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ، وَإِنَّا نَتَّخِذُ شَرَابًا نَشْرَبُهُ مِنَ الزَّبِيبِ وَالْعِنَبِ وَغَيْرِهِ، وَقَدْ أُشْكِلَ عَلَيَّ؟ فَذَكَرَ لَهُ ضُرُوبًا مِنَ الْأَشْرِبَةِ فَأَكْثَرَ حَتَّى ظَنَنْتُ أَنَّهُ لَمْ يَفْهَمْهُ. فَقَالَ لَهُ ابْنُ عَبَّاسٍ: إِنَّكَ قَدْ أَكْثَرْتَ عَلَيَّ، اجْتَنِبْ مَا أَسْكَرَ مِنْ تَمْرٍ أَوْ زَبِيبٍ أَوْ غَيْرِهِ. (ن)', 'അബ്ദുറഹ്മാൻ(റ): ഒരാൾ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് പറഞ്ഞു: ഞാൻ ഖുറാസാൻ കാരനാണ്. ഞങ്ങളുടെ നാട് നല്ല തണുപ്പുസ്ഥലമാണ്. ഉണക്കമുന്തിരി, മുന്തിരി മുതലായവയിൽനിന്ന് കുടിക്കാൻ ചില പാനീയങ്ങൾ ഞങ്ങളുണ്ടാക്കാറുണ്ട്. ഇതിന്റെ വിധി എനിക്ക് അവ്യക്തമാണല്ലോ. ഇബ്നുഅബ്ബാസ്(റ)വിന് മസസ്സിലാകാതിരിക്കുമോയെന്ന് എനിക്ക് തോന്നുന്നിടത്തോളം അദ്ദേഹം വിവിധതരം പാനീയങ്ങളെക്കു റിച്ചു പറഞ്ഞുകൊണ്ടിരുന്നു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) അദ്ദേഹത്തോടു പറഞ്ഞു: നീ എന്നോട് ഒരുപാട് പറഞ്ഞു: കാരക്കയോ, ഉണക്കമുന്തിരിയോ, മറ്റെന്തിൽ നിന്നായാലും ലഹരിയുണ്ടാക്കുന്നതിനെ നീ വർജ്ജിക്കുക. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ جُوشَنٍ الْغَطَفَانِي قَالَ', 'അബ്ദുറഹ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 625, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَبِيذُ الْبُسْرِ بَحْتٌ لَا يَحِلُّ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): പഴുക്കാത്ത ഈത്തപ്പഴത്തിന്റെ വീഞ്ഞ് നിഷിദ്ധമാകുന്നു. അതനുവദനീയമല്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي جَمْرَةَ – نَصْرِ بْنِ عِمْرَانِ الضُّبَعِيِّ – قَالَ: كُنْتُ أُتَرْجِمُ بَيْنَ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا وَبَيْنَ النَّاسِ، فَأَتَتْهُ امْرَأَةٌ تَسْأَلُهُ عَنْ نَبِيذِ الْجَرِّ، فَنَهَى عَنْهُ، قُلْتُ: يَا أَبَا عَبَّاسٍ، إِنِّي أَنْتَبِذُ فِي جَرَّةٍ خَضْرَاءَ نَبِيذًا حُلْوًا، فَأَشْرَبُ مِنْهُ فَيَقَرْقِرُ بَطْنِي. قَالَ: لَا تَشْرَبْ مِنْهُ، وَإِنْ كَانَ أَحْلَى مِنَ الْعَسَلِ. (ن)', 'അബൂജംറ(റ): ഇബ്നുഅബ്ബാസ്(റ)വിന്റെയും ജനങ്ങളുടെയും ഇടയിൽ വിവർത്തനം ചെയ്യുന്നയാളായിരുന്നു ഞാൻ. അപ്പോൾ ഒരു സ്ത്രീവന്ന് മൺഭരണികളിലെ വീഞ്ഞിനെ സംബന്ധിച്ച് അവരോട് ചോദിച്ചു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) അത് വിലക്കി. ഞാൻ ചോദിച്ചു: അബൂഅബ്ബാസേ, പച്ചഭരണിയിൽ ഞാൻ മധുരമുള്ളവീഞ്ഞുണ്ടാക്കിക്കുടിക്കാറുണ്ട്. അതെന്റെ ഉദരത്തിൽ ഇരമ്പലുണ്ടാക്കുന്നു. അപ്പോഴവർ പറഞ്ഞു: നീയതിൽ നിന്ന് കുടിക്കരുത്. അത് തേനിനേക്കാൾ മധുരമുള്ളതാണെങ്കിലും ശരി. (ന)', 'أَبِي جَمْرَةَ – نَصْرِ بْنِ عِمْرَانِ الضُّبَعِيِّ – قَالَ', 'അബൂജംറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي جَمْرَةَ – نَصْرِ بْنِ عِمْرَانِ الضُّبَعِيِّ – قَالَ: قُلْتُ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: إِنَّ جَدَّةً لِي تَنْبِذُ نَبِيذًا فِي جَرٍّ أَشْرَبُهُ حُلْوًا، إِنْ أَكْثَرْتُ مِنْهُ فَجَالَسْتُ الْقَوْمَ خَشِيتُ أَنْ أَفْتَضِحَ. فَقَالَ: قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَرْحَبًا بِالْوَفْدِ لَيْسَ بِالْخَزَايَا وَلَا النَّادِمِينَ". قَالُوا: يَا رَسُولَ اللهِ، إِنَّ بَيْنَنَا وَبَيْنَكَ الْمُشْرِكِينَ، وَإِنَّا لَا نَصِلُ إِلَيْكَ إِلَّا فِي أَشْهُرِ الْحُرُمِ، فَحَدِّثْنَا بِأَمْرٍ إِنْ عَمِلْنَا بِهِ دَخَلْنَا الْجَنَّةَ، وَنَدْعُو بِهِ مَنْ وَرَاءَنَا. قَالَ: "آمُرُكُمْ بِثَلَاثٍ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: آمُرُكُمْ بِالْإِيمَانِ بِاللهِ، وَهَلْ تَدْرُونَ مَا الْإِيمَانُ بِاللهِ". قَالُوا: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: "شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَإِقَامُ الصَّلَاةِ، وَإِيتَاءُ الزَّكَاةِ، وَأَنْ تُعْطُوا مِنَ الْمَغَانِمِ الْخُمُسَ. وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: عَمَّا يُنْبَذُ فِي الدُّبَّاءِ وَالنَّقِيرِ وَالْحَنْتَمِ وَالْمُزَفَّتِ". (ن)', 'അബൂജംറ(റ): ഇബ്നുഅബ്ബാസ്(റ)വിനോടു ഞാൻ പറഞ്ഞു: എന്റെ വലിയുമ്മ മൺഭരണികളിൽ ജ്യൂസുണ്ടാക്കുകയും ഞാനത് മധുരത്തോടെ കുടിക്കുകയും ചെയ്യാറുണ്ട്. ഞാനത് കൂടുതൽ കുടിച്ചിട്ട് സമൂഹത്തിൽ ഇരുന്നാൽ മാനം കെടുമോയെന്ന് ഭയപ്പെട്ടുന്നു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അബ്ദുൽബൈസ് നിവേദകസംഘം പ്രവാചകൻ(സ)യുടെ അടുക്കൽ വന്നു. തദവസരത്തിൽ റസൂൽ(സ) പറഞ്ഞു: "നിവേദകസംഘത്തിന് സ്വാഗതം; നിങ്ങൾ നിന്ദിതരും ദുഃഖിതരുമല്ല." അവർ പറഞ്ഞു: ഞങ്ങളുടെയും താങ്കളുടെയും മദ്ധ്യേ ബഹുദൈവവിശ്വാസികളുണ്ട്. തന്മൂലം യുദ്ധം നിഷിദ്ധമായ മാസങ്ങളിലല്ലാതെ നിങ്ങളുടെയടുക്കൽ ഞങ്ങൾക്ക് എത്താൻ കഴിയുകയില്ല. ആയതിനാൽ, അനുഷ്ഠിച്ചാൽ സ്വർഗപ്രവേശത്തിനുതകുന്ന ഒരുകാര്യം ഞങ്ങൾക്ക് പറഞ്ഞു തന്നാലും. ഞങ്ങളുടെ പിന്നിലുള്ളവരെ അതുകൊണ്ട് ഞങ്ങൾ ക്ഷണിക്കുന്നതാണ്. റസൂൽ(സ) പ്രതിവചിച്ചു: "ഞാൻ നിങ്ങളോടു മൂന്നു കാര്യങ്ങൾ കൽപിക്കുകയും നാല് കാര്യങ്ങൾ നിരോധിക്കുകയും ചെയ്യുന്നു. അല്ലാഹുവിനെ കൊണ്ട് വിശ്വസിക്കാൻ ഞാൻ നിർദ്ദേശിക്കുന്നു. അല്ലാഹുവിലുള്ള വിശ്വാസം എന്താണെന്ന് നിങ്ങൾക്കറിയാമോ?" അവർ പറഞ്ഞു: ഏറ്റവുംകൂടുതൽ അറിയുന്നവൻ അല്ലാഹുവും അവന്റെ ദൂതനുമാകുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്ന് സാക്ഷ്യം വഹിക്കുകയും നമസ്കാരം മുറപ്രകാരം നിലനിർത്തുകയും സകാത്ത് നൽകുകയും സമരാർജ്ജിത സമ്പത്തിൽ നിന്ന് അഞ്ചിൽ ഒരു ഭാഗം നൽകുകയും ചെയ്യലാകുന്നു വിശ്വാസം. നാല് കാര്യങ്ങൾ ഞാൻ നിങ്ങൾക്ക് നിരോധിക്കുന്നു: ചുരങ്ങാപ്പാത്രം, ഈത്തപ്പനമുരട് തുരന്നുണ്ടാക്കിയ പാത്രം, പച്ചഭരണി, ടാർ പൂശിയപാത്രം എന്നിവയിലുണ്ടാക്കുന്ന വീഞ്ഞ്." (ന)', 'أَبِي جَمْرَةَ – نَصْرِ بْنِ عِمْرَانِ الضُّبَعِيِّ – قَالَ', 'അബൂജംറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ قَيْسِ بْنِ وَهْبَانَ قَالَ: سَأَلْتُ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قُلْتُ: إِنَّ لِي جُرَيْرَةً أَنْتَبِذُ فِيهَا، حَتَّى إِذَا غَلَى وَسَكَنَ شَرِبْتُهُ. قَالَ: مُذْ كَمْ هَذَا شَرَابُكَ؟ قُلْتُ: مُذْ عِشْرُونَ سَنَةً. أَوْ قَالَ: مُذْ أَرْبَعُونَ سَنَةً. قَالَ: طَالَمَا تَرَوَّتْ عُرُوقُكَ مِنَ الْخَبَثِ. (ن)', 'ഖൈസുബ്നു വഹ്ബാൻ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോടു ചോദിച്ചു: എന്റെ കൊച്ചു മൺപാത്രത്തിൽ ഞാൻ വീഞ്ഞുണ്ടാക്കും. അങ്ങനെയത് പതഞ്ഞുപൊന്തിയടങ്ങിയാൽ ഞാൻ കുടിക്കും. ഇബ്നുഅബ്ബാസ്(റ) ചോദിച്ചു: ഈ പാനീയം ഉപയോഗിക്കാൻ തുടങ്ങിയിട്ട് എത്രനാളായി? ഞാൻ പറഞ്ഞു: ഇരുപതു വർഷമോ(നിവേദകന് സംശയമുണ്ട്) നാല്പത് വർഷമോ ആയിരിക്കുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: നാളുകളായി നിന്റെ ഞരമ്പുകൾ മാലിന്യത്താൽ ഉറച്ചിരിക്കുന്നു. (ന)', 'قَيْسِ بْنِ وَهْبَانَ قَالَ', 'ഖൈസുബ്നു വഹ്ബാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, 'നിവേദകന് സംശയമുണ്ട്', 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَجُلًا جَاءَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقَدَحٍ فِيهِ نَبِيذٌ، وَهُوَ عِنْدَ الرُّكْنِ، وَدَفَعَ إِلَيْهِ الْقَدَحَ فَرَفَعَهُ إِلَى فِيهِ فَوَجَدَهُ شَدِيدًا فَرَدَّهُ عَلَى صَاحِبِهِ، فَقَالَ لَهُ رَجُلٌ مِنَ الْقَوْمِ: يَا رَسُولَ اللهِ، أَحَرَامٌ هُوَ؟ فَقَالَ: "عَلَيَّ بِالرَّجُلِ". فَأُتِيَ بِهِ، فَأَخَذَ مِنْهُ الْقَدَحَ ثُمَّ دَعَا بِمَاءٍ فَصَبَّهُ فِيهِ، فَرَفَعَهُ إِلَى فِيهِ فَقَطَّبَ، ثُمَّ دَعَا بِمَاءٍ أَيْضًا فَصَبَّهُ فِيهِ، ثُمَّ قَالَ: "إِذَا اغْتَلَمَتْ عَلَيْكُمْ هَذِهِ الْأَوْعِيَةُ فَاكْسِرُوا مُتُونَهَا بِالْمَاءِ". (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഒരു റുക്നിനടുത്ത് ഇരിക്കുമ്പോൾ ഒരാൾ ഒരുപാത്രത്തിൽ വീഞ്ഞു കൊണ്ടുവന്ന് പ്രവാചകൻ(സ)ക്ക് കൊടുക്കുന്നത് ഞാൻ കണ്ടു. റസൂൽ(സ) തന്റെ വായിലേക്ക് വെച്ചപ്പോൾ അത് വീര്യമുള്ളതാണെന്ന് അറിഞ്ഞതിനാൽ അതിന്റെ ഉടമക്ക് അത് തിരിച്ച് നൽകി. തദവസരത്തിൽ കൂട്ടത്തിലൊരാൾ പ്രവാചകൻ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അത് നിഷിദ്ധമാണോ? റസൂൽ(സ) പ്രതിവചിച്ചു: "അദ്ദേഹത്തെ എന്റെ അടുക്കൽ കൊണ്ടുവരൂ." അങ്ങനെ അദ്ദേഹത്തെ കൊണ്ടുവന്നപ്പോൾ റസൂൽ(സ) ആ പാത്രം അദ്ദേഹത്തിൽ നിന്നു വാങ്ങി കുറച്ചുവെള്ളം ആവശ്യപ്പെട്ടു. അനന്തരമത് ആ പാത്രത്തിൽ ഒഴിച്ച് വായിലേക്ക് ഉയർത്തി. അപ്പോൾ റസൂൽ(സ) മുഖം ഉയർത്തി. വീണ്ടും വെള്ളം ആവശ്യപ്പെടുകയും അതിലേക്ക് ഒഴിക്കുകയും ചെയ്തു. പിന്നീട് റസൂൽ(സ) അരുളി: "ഈ പാത്രങ്ങളിലെ പാനീയം വീര്യമുള്ളതായി നിങ്ങൾക്ക് അനുഭവപ്പെട്ടാൽ വെള്ളം കൊണ്ട് അതിന്റെ ശക്തി ഇല്ലാതാക്കുക." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ رُقَيَّةَ بِنْتِ عَمْرِو بْنِ سَعِيدٍ قَالَتْ: كُنْتُ فِي حَجْرِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، فَكَانَ يُنْقَعُ لَهُ الزَّبِيبُ فَيَشْرَبُهُ مِنَ الْغَدِ، ثُمَّ يُجَفَّفُ الزَّبِيبُ وَيُلْقَى عَلَيْهِ زَبِيبٌ آخَرُ وَيُجْعَلُ فِيهِ مَاءٌ، فَيَشْرَبُهُ مِنَ الْغَدِ، حَتَّى إِذَا كَانَ بَعْدَ الْغَدِ طَرَحَهُ. (ن)', 'റുഖയ്യ ബിൻത് അംറിബ്നി സഈദ്: ഞാൻ ഇബ്നുഉമർ(റ)വിന്റെ സംരക്ഷണത്തിലായിരുന്നു. അദ്ദേഹത്തിനുവേണ്ടി ഉണക്കമുന്തിരി വെള്ളത്തിലിട്ടു വെക്കുകയും അടുത്തദിവസം അദ്ദേഹം കുടിക്കുകയും ചെയ്യുമായിരുന്നു. പിന്നീട് ഉണക്കമുന്തിരി വറ്റിച്ചതിനുശേഷം അതിൽ വേറെ ഉണക്കമുന്തിരി ഇടുകയും വെള്ളം ചേർക്കുകയും ചെയ്യും. അദ്ദേഹമത് അടുത്തദിവസം കുടിക്കും. അങ്ങനെ രണ്ടാം ദിവസമായാൽ ഒഴിച്ചുകളയുമായിരുന്നു. (ന)', 'رُقَيَّةَ بِنْتِ عَمْرِو بْنِ سَعِيدٍ قَالَتْ', 'റുഖയ്യ ബിൻത് അംറിബ്നി സഈദ്', null, null, array['ن']::text[], array['ന']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَطِشَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَوْلَ الْكَعْبَةِ، فَاسْتَسْقَى، فَأُتِيَ بِنَبِيذٍ مِنَ السِّقَايَةِ، فَشَمَّهُ فَقَطَّبَ، فَقَالَ: "عَلَيَّ بِذَنُوبٍ مِنْ زَمْزَمَ". فَصَبَّ عَلَيْهِ ثُمَّ شَرِبَ. فَقَالَ رَجُلٌ: أَحَرَامٌ هُوَ يَا رَسُولَ اللهِ؟ قَالَ: "لَا". قَالَ النَّسَائِي: وَهَذَا خَبَرٌ ضَعِيفٌ. (ن)', 'അബൂമസ്ഊദ്(റ): കഅ്ബയുടെ പരിസരത്ത് വെച്ച് റസൂൽ(സ)ക്ക് ദാഹം അനുഭവപ്പെടുകയും വെള്ളം ആവശ്യപ്പെടുകയും ചെയ്തു. അപ്പോൾ തോൽപാത്രത്തിലെ മുന്തിരിച്ചാറ് കൊണ്ടുവന്നുകൊടുത്തു. റസൂൽ(സ) അത് മണത്തുനോക്കിയശേഷം അതിൽ വെള്ളം കലർത്തിയിട്ട് പറഞ്ഞു: "ഒരു തൊട്ടി സംസം കൊണ്ടുവരൂ." അനന്തരം റസൂൽ(സ) അത് ഒഴിച്ചതിനുശേഷം കുടിച്ചു. തദവസരത്തിൽ ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അത് നിഷിദ്ധമാണോ? റസൂൽ(സ) പറഞ്ഞു: "അല്ല." (നസാഈ പറയുന്നു: ഇത് ദുർബ്ബലമായ ഹദീസാണ്.) (ന)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, 'നസാഈ പറയുന്നു: ഇത് ദുർബ്ബലമായ ഹദീസാണ്.', 627, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أَبِي رَافِعٍ نُفَيْعِ بْنِ رَافِعٍ الصَّائِغِ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: إِذَا خَشِيتُمْ مِنْ نَبِيذٍ شِدَّتَهُ فَاكْسِرُوهُ بِالْمَاءِ. قَالَ عَبْدُ اللهِ: مِنْ قَبْلِ أَنْ يَشْتَدَّ. (ن)', 'അബൂറാഫിഅ്(റ): ഉമറുബ്‌നു ഖത്താബ്(റ) പറഞ്ഞു: വീഞ്ഞിലെ വീര്യത്തെ നിങ്ങൾ ഭയപ്പെടുന്നുവെങ്കിൽ വെള്ളം ചേർത്ത് നിങ്ങളതിന്റെ ശക്തിയില്ലാതാക്കുക. അബ്ദുല്ല(റ) പറയുന്നു: ഈ പ്രക്രിയ വീര്യം പ്രാപിക്കുന്നതിനു മുമ്പാകുന്നു. (ന)', 'أَبِي رَافِعٍ نُفَيْعِ بْنِ رَافِعٍ الصَّائِغِ', 'അബൂറാഫിഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ قَالَ: تَلَقَّتْ ثَقِيفٌ عُمَرَ رَضِيَ اللهُ عَنْهُ بِشَرَابٍ، فَدَعَا بِهِ، فَلَمَّا قَرَّبَهُ إِلَى فِيهِ كَرِهَهُ، فَدَعَا بِهِ فَكَسَرَهُ بِالْمَاءِ، فَقَالَ: هَكَذَا فَافْعَلُوا. (ن)', 'സഈദുബ്‌നു മുസയ്യബ്(റ): സഖീഫ് ഗോത്രക്കാർ ഒരു പാനീയവുമായി ഉമർ(റ)വിനെ സ്വീകരിച്ചപ്പോൾ അദ്ദേഹം ആ പാനീയം ആവശ്യപ്പെട്ടു. അങ്ങനെ തന്റെ വായിലേക്ക് അടുപ്പിച്ചപ്പോൾ അദ്ദേഹത്തിനത് അനിഷ്ടകരമായി തോന്നി. അനന്തരം വെള്ളം ആവശ്യപ്പെട്ടിട്ട് അതുമുഖേന ശക്തിക്ഷയിപ്പിച്ചതിനു ശേഷം പറഞ്ഞു: ഇപ്രകാരം നിങ്ങൾ പ്രവർത്തിക്കുക. (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ قَالَ', 'സഈദുബ്‌നു മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عُتْبَةَ بْنِ فَرْقَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيذُ الَّذِي يَشْرَبُهُ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَدْ خُلِّلَ. (ن)', 'ഉത്ബത്‌ബിനു ഫർഖദ്(റ): ഉമർ(റ) കുടിക്കുന്ന വീഞ്ഞ് വെള്ളം കലർത്തപ്പെട്ടതായിരുന്നു. (ന)', 'عُتْبَةَ بْنِ فَرْقَدٍ', 'ഉത്ബത്‌ബിനു ഫർഖദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنِ السَّائِبِ بْنِ يَزِيدَ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ خَرَجَ عَلَيْهِمْ فَقَالَ: إِنِّي وَجَدْتُ مِنْ فُلَانٍ رِيحَ شَرَابٍ، فَزَعَمَ أَنَّهُ شَرَابُ الطِّلَاءِ، وَأَنَا سَائِلٌ عَمَّا شَرِبَ، فَإِنْ كَانَ مُسْكِرًا جَلَدْتُهُ. فَجَلَدَهُ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ الْحَدَّ تَامًّا. (ن)', 'സാഇബുബ്‌നു യസീദ്(റ): ഉമർ(റ) ജനങ്ങളുടെ അടുത്തേക്ക് വന്നിട്ടുപറഞ്ഞു: ഇന്നയാളിൽ നിന്നും ഞാൻ ലഹരിപാനീയത്തിന്റെ ഗന്ധം അനുഭവിക്കുന്നു. അവനെന്താണ് കുടിച്ചതെന്ന് ഞാൻ ചോദിച്ചപ്പോൾ അത് ''ത്വല്ലാഅ്'' (വറ്റിച്ച മുന്തിരിവീഞ്ഞ്) ആണെന്ന് അവൻ വാദിക്കുന്നു. അത് ലഹരിയുണ്ടാക്കുന്നതാണെങ്കിൽ ഞാനവനെ അടിക്കുന്നതാണ്. അങ്ങനെ ഉമർ(റ) പൂർണ്ണശിക്ഷ നടപ്പാക്കി. (ന)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്‌നു യസീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ إِبْرَاهِيمَ قَالَ: كَانُوا يَرَوْنَ أَنَّ مَنْ شَرِبَ شَرَابًا فَسَكِرَ مِنْهُ لَمْ يَصْلُحْ لَهُ أَنْ يَعُودَ فِيهِ. وفي رواية قَالَ: لَا بَأْسَ بِنَبِيذِ الْبُخْتُج (ن)', 'ഇബ്‌റാഹീം(റ): ആരെങ്കിലും ഒരു പാനീയം കുടിക്കുകയും അതുവഴി ലഹരി ബാധിതനാകുകയും ചെയ്താൽ വീണ്ടും അത് പാനം ചെയ്യൽ അവന് ഗുണകരമല്ല. മറ്റൊരു നിവേദനം: പാകം ചെയ്ത മുന്തിരിച്ചാർ ഉപയോഗിക്കുന്നതു കൊണ്ട് കുഴപ്പമില്ല. (ന)', 'إِبْرَاهِيمَ قَالَ', 'ഇബ്‌റാഹീം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 628, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=158), 1, 'وَفِي رِوَايَةٍ قَالَ: لَا بَأْسَ بِنَبِيذِ الْبُخْتُج (ن)', 'മറ്റൊരു നിവേദനം: പാകം ചെയ്ത മുന്തിരിച്ചാർ ഉപയോഗിക്കുന്നതു കൊണ്ട് കുഴപ്പമില്ല. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي مِسْكِينٍ قَالَ: سَأَلْتُ إِبْرَاهِيمَ قُلْتُ: إِنَّا نَأْخُذُ دُرْدِيَّ الْخَمْرِ أَوِ الطَّلَاءِ فَنُنَظِّفُهُ، ثُمَّ نَنْقَعُ فِيهِ الزَّبِيبَ ثَلَاثًا، ثُمَّ نُصَفِّيهِ، ثُمَّ نَدَعُهُ حَتَّى يَبْلُغَ فَنَشْرَبُهُ؟ قَالَ: يُكْرَهُ. (ن)', 'അബൂമിസ്കീൻ(റ): ഞാൻ ഇബ്റാഹിമിനോടു ചോദിച്ചു: ഞങ്ങൾ മദ്യത്തിന്റെ മട്ടോ വറ്റിച്ചമുന്തിരിച്ചാറോ എടുത്ത് സംസ്കരിച്ചതിനു ശേഷം അതിൽ മൂന്ന് ദിവസം ഉണക്കമുന്തിരി ഇട്ടുവെക്കുമായിരുന്നു. പിന്നീട് അത് അരിച്ചെടുത്തതിനിശേഷം പാകമാകുന്നതുവരെ വെക്കും. അനന്തരം ഞങ്ങളത് പാനം ചെയ്യും. അദ്ദേഹം പറഞ്ഞു: അത് അനിഷ്ടകരമാണ്. (ന)', 'أَبِي مِسْكِينٍ قَالَ', 'അബൂമിസ്കീൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنِ ابْنِ شُبْرُمَةَ قَالَ: رَحِمَ اللَّهُ إِبْرَاهِيمَ، شَدَّدَ النَّاسُ فِي النَّبِيذِ وَرَخَّصَ فِيهِ. (ن)', 'ഇബ്നുശുബ്റുമ(റ): അല്ലാഹു ഇബ്റാഹിമിനെ അനുഗ്രഹിക്കട്ടെ. ജനങ്ങൾ വീഞ്ഞിന്റെ കാര്യത്തിൽ കണിശത പുലർത്തിയപ്പോൾ അദ്ദേഹമതിൽ ഇളവു കാണിച്ചു. (ന)', 'ابْنِ شُبْرُمَةَ قَالَ', 'ഇബ്നുശുബ്റുമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنِ ابْنِ الْمُبَارَكِ قَالَ: مَا وَجَدْتُ الرُّخْصَةَ فِي الْمُسْكِرِ عَنْ أَحَدٍ صَحِيحًا إِلَّا عَنْ إِبْرَاهِيمَ. (ن)', 'ഇബ്നുമുബാറക്(റ): ലഹരിയുണ്ടാക്കുന്ന വസ്തുക്കളുടെ വിഷയത്തിലുള്ള ഇളവിനെ പൂർണ്ണമായും ശരിയായി ഞാൻ കണ്ടത് ഇബ്റാഹീമിൽ നിന്നു മാത്രമാണ്. (ന)', 'ابْنِ الْمُبَارَكِ قَالَ', 'ഇബ്നുമുബാറക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الْحَلَالَ بَيِّنٌ وَإِنَّ الْحَرَامَ بَيِّنٌ، وَإِنَّ بَيْنَ ذَلِكَ أُمُورًا مُشْتَبِهَاتٍ. وَرُبَّمَا قَالَ: مُشْتَبِهَةً. وَسَأَضْرِبُ فِي ذَلِكَ مَثَلًا: إِنَّ اللَّهَ عَزَّ وَجَلَّ حَمَى حِمًى، وَإِنَّ حِمَى اللَّهِ مَا حَرَّمَ، وَإِنَّهُ مَنْ يَرْعَ حَوْلَ الْحِمَى يُوشِكُ أَنْ يُخَالِطَ الْحِمَى وَرُبَّمَا قَالَ: أَنْ يَرْتَعَ. وَإِنَّ مَنْ خَالَطَ الرِّيبَةَ يُوشِكُ أَنْ يَجْسُرَ". (ن)', 'നുഅ്മാനുബ്നു ബശീർ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അനുവദനീയ കാര്യങ്ങൾ വ്യക്തമാണ്. നിഷിദ്ധവും വ്യക്തമാണ്. തീർച്ചയായും അതിനിടയിൽ സംശയകര(സദൃശ്യമായ)മായ ചിലകാര്യങ്ങളുണ്ട്. ഒരു പക്ഷേ സംശയകരമായ കാര്യം എന്നാകാം പറഞ്ഞത്. ഞാൻ ആ വിഷയത്തിൽ ഒരു ഉദാഹരണം പറയാം: നിശ്ചയം, അല്ലാഹു ഒരു പ്രദേശത്തെ സംരക്ഷിത മേഖലയാക്കിയിരിക്കുന്നു. അല്ലാഹു നിഷിദ്ധമാക്കിയ കാര്യങ്ങളാണ് അവന്റെ സുരക്ഷിതമേഖല. ആരെങ്കിലും ആ സംരക്ഷിത പ്രദേശത്തിനു ചുറ്റും മേച്ചിൽനടത്തിയാൽ താമസംവിനാ അവനതുമായി കൂടി കലർന്നേക്കാം ഒരുപക്ഷേ അതിൽ ചെന്നുവീഴും എന്നാകാം പറഞ്ഞത്. സംശയകരമായ കാര്യവുമായി ബന്ധപ്പെട്ടവൻ സമീപ ഭാവിയിൽതന്നെ അതിൽ പ്രവേശിക്കുന്നതാണ്." (ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَبِي الْحَوْرَاءِ السَّعْدِيِّ قَالَ: قُلْتُ لِلْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُمَا: مَا حَفِظْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: حَفِظْتُ مِنْهُ: "دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ". (ن)', 'അബുൽഹൗറാ(റ): ഞാൻ ഹസൻ(റ)വിനോടു ചോദിച്ചു. താങ്കൾ പ്രവാചകർ(സ)യിൽ നിന്ന് എന്താണ് ഹൃദ്യസ്ഥമാക്കിയത്? അദ്ദേഹം പറഞ്ഞു: "നിനക്ക് സംശയമുള്ളതിനെ വെടിഞ്ഞ് സംശയരഹിതമായ കാര്യങ്ങളിലേക്ക് ചെല്ലുക." എന്നതാണ് ഞാൻ റസൂൽ(സ)യിൽ നിന്ന് മനപ്പാഠമാക്കിയത്.(ന)', 'أَبِي الْحَوْرَاءِ السَّعْدِيِّ قَالَ', 'അബുൽഹൗറാ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 629, 629, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: ذُكِرَ لِرَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ امْرَأَةٌ مِنَ الْعَرَبِ، فَأَمَرَ أَبَا أُسَيْدٍ أَنْ يُرْسِلَ إِلَيْهَا، فَأَرْسَلَ إِلَيْهَا فَقَدِمَتْ فَنَزَلَتْ، فِي أُجُمِ بَنِي سَاعِدَةَ، فَخَرَجَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ حَتَّى جَاءَهَا فَدَخَلَ عَلَيْهَا، فَإِذَا امْرَأَةٌ مُنَكِّسَةٌ رَأْسَهَا، فَلَمَّا كَلَّمَهَا رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَتْ: أَعُوذُ بِاللَّهِ مِنْكَ، قَالَ: "قَدْ أَعَذْتُكِ مِنِّي". فَقَالُوا لَهَا: أَتَدْرِينَ مَنْ هَذَا؟ فَقَالَتْ: لَا، فَقَالُوا: هَذَا رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ جَاءَكِ لِيَخْطُبَكِ، قَالَتْ: أَنَا كُنْتُ أَشْقَى مِنْ ذَلِكَ. قَالَ سَهْلٌ: فَأَقْبَلَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ حَتَّى جَلَسَ فِي سَقِيفَةِ بَنِي سَاعِدَةَ هُوَ وَأَصْحَابُهُ، ثُمَّ قَالَ: "اسْقِنَا" لِسَهْلٍ قَالَ: فَأَخْرَجْتُ لَهُمْ هَذَا الْقَدَحَ فَأَسْقَيْتُهُمْ فِيهِ. قَالَ أَبُو حَازِمٍ: فَأَخْرَجَ لَنَا سَهْلٌ ذَلِكَ الْقَدَحَ فَشَرِبْنَا فِيهِ، قَالَ: ثُمَّ اسْتَوْهَبَهُ بَعْدَ ذَلِكَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ رَضِيَ اللهُ عَنْهُ، فَوَهَبَهُ لَهُ. (م)', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ): ഒരു അറബി സ്ത്രീയെക്കുറിച്ച് പ്രവാചകർ(സ)യോട് പറയപ്പെട്ടു. അപ്പോൾ അബൂഉസൈദ്(റ)വിനോട് അവളെ കൊണ്ടുവരാൻ ഒരാളെ അയക്കാൻ നബി(സ) കൽപിച്ചു. തദവസരം അവൾ വന്നു. ബനൂസാഇദക്കാരുടെ ഒരു കൂടാരത്തിലാണ് അവൾ വന്നിറങ്ങിയത്. റസൂൽ(സ) അവളുടെയടുക്കൽ ചെന്നപ്പോൾ അവൾ തലതാഴ്ത്തി. നബി അവളോടു സംസാരിച്ചപ്പോൾ അവൾ പറഞ്ഞു: താങ്കളിൽ നിന്ന് ഞാൻ അല്ലാഹുവിൽ അഭയം തേടുന്നു. നബി(സ) പറഞ്ഞു: "ഞാൻ നിന്നെ സൂക്ഷിച്ചിരിക്കുന്നു." (നീ സ്വകുടുംബത്തിൽക്ക് മടങ്ങുക.) അപ്പോൾ ജനങ്ങൾ അവളോടു ചോദിച്ചു: ഇതാരാണെന്ന് നിനക്കറിയുമോ? അവൾ പറഞ്ഞു: അറിയില്ല. അപ്പോൾ അവർ പറഞ്ഞു. ഇത് അല്ലാഹുവിന്റെ റസൂൽ(സ)യാണ്. നിന്നോട് വിവാഹാഭ്യർത്ഥന നടത്താൻ വന്നതാണ്. അവൾ പറഞ്ഞു: ഞാനതിൽ വലിയ നിർഭാഗ്യവതിയായി. സഹ്ൽ(റ) പറയുന്നു: അന്ന് പ്രവാചകർ(സ)യും അനുചരന്മാരും ബനൂസാഇദ ഗോത്രക്കാരുടെ പന്തലിൽ ചെന്നിരുന്നു. പിന്നീട് റസൂൽ(സ) സഹ്‌ലിനോട് പറഞ്ഞു. "ഞങ്ങളെ കുടിപ്പിക്കൂ." സഹ്ൽ പറയുന്നു: ഞാൻ ഈ കപ്പ് പുറത്തെടുത്തു. അവരെയെല്ലാം കുടിപ്പിച്ചു. അബൂഹാസിം പറയുന്നു: സഹ്ൽ ഞങ്ങൾക്ക് വേണ്ടി ആ കപ്പ് പുറത്തെടുക്കുകയും ഞങ്ങളതിൽ കുടിക്കുകയും ചെയ്തു. പിന്നീട് ഈ കപ്പ് ഉമറുബ്‌നു അബ്ദിൽ അസീസ് ആവശ്യപ്പെട്ടതനുസരിച്ച് സഹ്ൽ അദ്ദേഹത്തിന് കൊടുത്തു. (മു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّه عَلَيْهِ وَسَلَّمَ عَنِ الشُّرْبِ مِنْ ثُلْمَةِ الْقَدَحِ، وَأَنْ يُنْفَخَ فِي الشَّرَابِ. (د)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): പാത്രത്തിന്റെ വിള്ളലിൽ കൂടി പാനംചെയ്യലും പാനീയത്തിൽ ഊതുന്നതും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 630, 630, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَاصِمٍ الْأَحْوَلِ رَحِمَهُ الله تعالى قَالَ: رَأَيْتُ قَدَحَ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ عِنْدَ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، قَالَ: قَالَ أَنَسٌ: لَقَدْ سَقَيْتُ رَسُولَ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ فِي هَذَا الْقَدَحِ أَكْثَرَ مِنْ كَذَا وَكَذَا. قَالَ: كَانَ فِيهِ حَلْقَةٌ مِنْ حَدِيدٍ، فَأَرَادَ أَنَسٌ أَنْ يَجْعَلَ مَكَانَهَا حَلْقَةً مِنْ ذَهَبٍ أَوْ فِضَّةٍ، فَقَالَ لَهُ أَبُو طَلْحَةَ: لَا تُغَيِّرَنَّ شَيْئًا صَنَعَهُ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَتَرَكَهُ. (خ)', 'ആസിമുൽ അഹ്‌വൽ(റ): നബി(സ)യുടെ കോപ്പ അനസുബ്‌നു മാലിക്(റ)വിന്റെയടുക്കൽ ഞാൻ കണ്ടു. ആസിം പറയുന്നു. അനസ് പ്രസ്താവിച്ചു: ഞാൻ ധാരാളം പ്രാവശ്യം ഈ കോപ്പയിൽ പ്രവാചകൻ(സ)യെ കുടിപ്പിച്ചിട്ടുണ്ട്. അതിന് ഒരു ഇരുമ്പിന്റെ ചിറ്റ്(വളയം) ഉണ്ടായിരുന്നു. അനസ് ആ ഇരുമ്പ് വളയത്തിന്റെ സ്ഥാനത്ത് വെള്ളിയുടെയോ സ്വർണ്ണത്തിന്റെയോ വളയം പിടിപ്പിക്കാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ ത്വൽഹ(റ) അദ്ദേഹത്തോടു പറഞ്ഞു: റസൂൽ(സ) ചെയ്തതൊന്നും നീ മാറ്റരുത്. അങ്ങനെ അനസ്(റ) ആ ശ്രമം ഉപേക്ഷിച്ചു. (ബു)', 'عَاصِمٍ الْأَحْوَلِ رَحِمَهُ الله تعالى قَالَ', 'ആസിമുൽ അഹ്‌വൽ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 630, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى رَجُلٍ مِنَ الْأَنْصَارِ وَمَعَهُ صَاحِبٌ لَهُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنْ كَانَ عِنْدَكَ مَاءٌ بَاتَ هَذِهِ اللَّيْلَةَ فِي شَنَّةٍ وَإِلَّا كَرَعْنَا. قَالَ: وَالرَّجُلُ يُحَوِّلُ الْمَاءَ فِي حَائِطِهِ، قَالَ: فَقَالَ الرَّجُلُ: يَا رَسُولَ اللَّهِ، عِنْدِي مَاءٌ بَائِتٌ. فَانْطَلِقْ إِلَى الْعَرِيشِ، قَالَ: فَانْطَلَقَ بِهِمَا، فَسَكَبَ فِي قَدَحٍ، ثُمَّ حَلَبَ عَلَيْهِ مِنْ دَاجِنٍ لَهُ، قَالَ: فَشَرِبَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ شَرِبَ الرَّجُلُ الَّذِي جَاءَ مَعَهُ. (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) ഒരു അൻസാരിയുടെ അടുക്കൽ ചെന്നു. കൂടെ നബി(സ)യുടെ ഒരു അനുചരനും ഉണ്ടായിരുന്നു. നബി(സ) അരുളി: "ഇക്കഴിഞ്ഞ രാത്രി മുഴുവനും തോൽപ്പാത്രത്തിലിരുന്ന വെള്ളം നിന്റെയടുക്കൽ ഉണ്ടെങ്കിൽ കൊണ്ടുവരിക. അതില്ലെങ്കിൽ ഞങ്ങൾ കോരി കുടിച്ചുകൊള്ളാം." നിവേദകൻ പറയുന്നു: ആ വീട്ടുകാരൻ തോട്ടം നനച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെയടുക്കൽ രാത്രി എടുത്തുവെച്ച വെള്ളമുണ്ട്. താങ്കൾ പന്തലിലേക്ക് വന്നാലും. അവർ രണ്ട് പേരെയും അദ്ദേഹം പന്തലിലേക്ക് കൂട്ടികൊണ്ടുപോയി. ഒരു കോപ്പയിൽ അൽപം വെള്ളമൊഴിച്ചു. ശേഷം അതിലേക്ക് തന്റെ ഒരാടിനെ കറന്നു. നബി(സ) അത് കുടിച്ചു. ശേഷം അവിടത്തെ കൂടെവന്ന വ്യക്തിയും കുടിച്ചു. (ബു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ،', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ لِرَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدَحٌ مِنْ قَوَارِيرَ يَشْرَبُ فِيهِ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)ക്ക് കുടിക്കാൻ ഉപയോഗിക്കുന്ന ഒരു പളുങ്ക് പാത്രമുണ്ടായിരുന്നു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 631, 631, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ أَبِي عَامِرٍ الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيَكُونَنَّ مِنْ أُمَّتِي أَقْوَامٌ، يَسْتَحِلُّونَ الْحِرَ وَالْحَرِيرَ، وَالْخَمْرَ وَالْمَعَازِفَ، وَلَيَنْزِلَنَّ أَقْوَامٌ إِلَى جَنْبِ عَلَمٍ، يَرُوحُ عَلَيْهِمْ بِسَارِحَةٍ لَهُمْ، يَأْتِيهِمْ - يَعْنِي الْفَقِيرُ - لِحَاجَةٍ فَيَقُولُوا: ارْجِعْ إِلَيْنَا غَدًا، فَيُبَيِّتُهُمُ اللَّهُ، وَيَضَعُ الْعَلَمَ، وَيَمْسَخُ آخَرِينَ قِرَدَةً وَخَنَازِيرَ إِلَى يَوْمِ الْقِيَامَةِ". (خ)', 'അബൂആമിരിൽ അശ്അരി(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "എന്റെ സമുദായത്തിൽ ഒരു ജനവിഭാഗം ഉടലെടുക്കും. വ്യഭിചാരവും, പട്ടും, മദ്യവും, അശ്ലീലഗാനങ്ങളും അവർ അനുവദനീയമായി പ്രഖ്യാപിക്കും. മറ്റൊരു ജനവിഭാഗം മലഞ്ചെരിവുകളിലാണ് താമസമുറപ്പിക്കുക. അവരുടെ നാൽക്കാലികളെ മേച്ചിൽ സ്ഥലങ്ങളിൽ നിന്ന് സായാഹ്നത്തിൽ തിരിച്ചുകൊണ്ടു വരുമ്പോൾ സഹായമഭ്യർത്ഥിച്ച് കൊണ്ട് ഒരു ദരിദ്രൻ അവരുടെയടുക്കൽ ചെല്ലും. അപ്പോൾ അവർ പറയും: നാളെ വരൂ. അങ്ങനെ അല്ലാഹു പർവ്വതത്തെ അവരുടെ മീതെ താഴ്ത്തി രാത്രിതന്നെ അവരെ നശിപ്പിച്ചുകളയും. അവശേഷിച്ചവരെ അന്ത്യനാൾ വരേക്കും കുരങ്ങന്മാരും പന്നികളുമാക്കി മാറ്റുകയും ചെയ്യും." (ബു)', 'أَبِي عَامِرٍ الْأَشْعَرِيِّ', 'അബൂആമിരിൽ അശ്അരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 631, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَشْرَبَ عَلَى بُطُونِنَا، وَهُوَ الْكَرْعُ، وَنَهَانَا أَنْ نَغْتَرِفَ بِالْيَدِ الْوَاحِدَةِ، وَقَالَ: "لَا يَلَغْ أَحَدُكُمْ كَمَا يَلَغُ الْكَلْبُ. وَلَا يَشْرَبْ بِالْيَدِ الْوَاحِدَةِ كَمَا يَشْرَبُ الْقَوْمُ الَّذِينَ سَخِطَ اللَّهُ عَلَيْهِمْ، وَلَا يَشْرَبْ بِاللَّيْلِ مِنْ إِنَاءٍ حَتَّى يُحَرِّكَهُ، إِلَّا أَنْ يَكُونَ إِنَاءً مُخَمَّرًا. وَمَنْ شَرِبَ بِيَدِهِ، وَهُوَ يَقْدِرُ عَلَى إِنَاءٍ، يُرِيدُ التَّوَاضُعَ، كَتَبَ اللَّهُ لَهُ بِعَدَدِ أَصَابِعِهِ حَسَنَاتٍ. وَهُوَ إِنَاءُ عِيسَى بْنِ مَرْيَمَ عَلَيْهِمَا السَّلَامُ، إِذْ طَرَحَ الْقَدَحَ فَقَالَ: أُفٍّ، هَذَا مَعَ الدُّنْيَا". [ز: في سنده مجهول ومدلس عنعنه] (جه)', 'അബ്ദുല്ലഹിബ്നു ഉമർ(റ): ഉദരങ്ങളുടെ മേൽ (കിടന്നുകൊണ്ട്) പാനം ചെയ്യൽ റസൂൽ(സ) വിലക്കി. അതാണു തലയിട്ടു കുടിക്കൽ. ഒറ്റകൈകൊണ്ട് വെള്ളം കോരിയെടുക്കലും അവിടന്ന് നിരോധിച്ചു. തുടർന്നു തിരുമേനി(സ) അരുളി: "നായ നക്കിക്കുടിക്കുന്നതുപോലെ (പാത്രത്തിൽ തലയിട്ട്) നിങ്ങളാരും കുടിക്കരുത്. അല്ലാഹുവിന്റെ കോപത്തിനിരയായ സമൂഹം കുടിക്കുന്നതുപോലെ ആരും ഒറ്റകൈകൊണ്ട് കുടിക്കുകയുമരുത്. പാത്രം മൂടിവെക്കപ്പെട്ടതല്ലെങ്കിൽ അതിനെ അനക്കിയിട്ടല്ലാതെ അതിൽ നിന്നാരും രാത്രി പാനം ചെയ്യരുത്. പാത്രത്തിൽ പാനം ചെയ്യാൻ കഴിവുള്ളതോടുകൂടി വിനയം ലക്ഷ്യമാക്കിയാരെങ്കിലും സ്വന്തം കരം കൊണ്ട് കുടിച്ചാൽ അവന്റെ വിരലുകളുടെ എണ്ണത്തിനനുസൃതമായി അല്ലാഹു നന്മകൾ രേഖപ്പെടുത്തുന്നതാണ്. അതാണെങ്കിൽ (കൈ) ഈസ(അ)മിന്റെ പാത്രമാണ്. പാനപാത്രം വലിച്ചെറിഞ്ഞു കൊണ്ട് ഈസ(അ) പറഞ്ഞു: ഛെ, ഇത് ഐഹിക ജീവിതത്തോടൊപ്പമുള്ളതാണ്." (ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലഹിബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مجهول ومدلس عنعنه', null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَرَرْنَا عَلَى بِرْكَةٍ، فَجَعَلْنَا نَكْرَعُ فِيهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَكْرَعُوا، وَلَكِنِ اغْسِلُوا أَيْدِيَكُمْ، ثُمَّ اشْرَبُوا فِيهَا، فَإِنَّهُ لَيْسَ إِنَاءٌ أَطْيَبَ مِنَ الْيَدِ". (جه)', 'ഇബ്നുഉമർ(റ): ഞങ്ങൾ ഒരു ജലാശയത്തിന് സമീപത്തുകൂടെ സഞ്ചരിച്ചപ്പോൾ അതിൽ തലയിട്ടു കുടിക്കാൻ തുടങ്ങി. തൽസമയം പ്രവാചകർ(സ) അരുളി: "നിങ്ങൾ തലയിട്ട് കുടിക്കരുത്. മറിച്ച് നിങ്ങളുടെ കരങ്ങൾ കഴുകിയതിനു ശേഷം അതിൽ പാനം ചെയ്യുക. നിശ്ചയം കൈയ്യിനേക്കാൾ മികച്ച മറ്റൊരുപാത്രവുമില്ല." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 632, 632, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ مِنَ الْأَنْصَارِ، وَهُوَ يُحَوِّلُ الْمَاءَ فِي حَائِطِهِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ كَانَ عِنْدَكَ مَاءٌ بَاتَ فِي شَنٍّ فَاسْقِنَا، وَإِلَّا كَرَعْنَا". قَالَ: عِنْدِي مَاءٌ بَاتَ فِي شَنٍّ. فَانْطَلَقَ وَانْطَلَقْنَا مَعَهُ إِلَى الْعَرِيشِ، فَحَلَبَ لَهُ شَاةً عَلَى مَاءٍ بَاتَ فِي شَنٍّ، فَشَرِبَ، ثُمَّ فَعَلَ مِثْلَ ذَلِكَ بِصَاحِبِهِ الَّذِي مَعَهُ. (خ،د،جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): തന്റെ തോട്ടത്തിൽ വെള്ളം നനച്ചുകൊണ്ടിരുന്ന ഒരു അൻസാരിയുടെ അടുക്കൽ റസൂൽ(സ) പ്രവേശിച്ചിട്ട് അദ്ദേഹത്തോടു ചോദിച്ചു: "താങ്കളുടെയടുക്കൽ രാത്രി മുഴുവൻ തോൽ പാത്രത്തിലിരുന്ന വെള്ളമുണ്ടങ്കിൽ ഞങ്ങളെ കുടിപ്പിക്കുക. ഇല്ലെങ്കിൽ (ഒഴുകുന്നവെള്ളത്തിൽനിന്ന്) ഞങ്ങൾ കോരി കുടിച്ചുകൊള്ളാം." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: രാത്രി മുഴുവൻ തോൽ പാത്രത്തിലിരുന്ന വെള്ളം എന്റെയടുക്കൽ ഉണ്ട്. അങ്ങനെ അദ്ദേഹത്തോടൊപ്പം ഞങ്ങൾ പന്തലിലേക്ക് പോയി. അദ്ദേഹം പ്രവാചകർ(സ)ക്കു വേണ്ടി ഒരാടിനെ കറക്കുകയും രാത്രി തോൽ പാത്രത്തിലിരുന്ന വെള്ളവുമായി കലർത്തുകയും ചെയ്തു. അനന്തരം നബി(സ) അത് കുടിച്ചു. ശേഷം പ്രവാചകർ(സ)യുടെ കൂടെയുള്ള അനുചരന്നും അപ്രകാരം നൽകി. (ബു,ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 632, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عِيسَى بْنِ عَبْدِ اللهِ - رَجُلٌ مِنَ الْأَنْصَارِ - عَنْ أَبِيهِ: أَنَّ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ دَعَا بِإِدَاوَةٍ يَوْمَ أُحُدٍ، فَقَالَ: "اخْنَثْ فَمَ الْإِدَاوَةِ"، ثُمَّ شَرِبَ مِنْ فِيهَا. (د،ت)', 'ഈസബ്‌നു അബ്ദില്ല(റ) (അദ്ദേഹം അൻസാരികളിൽ പെട്ടയാളാണ്.) തന്റെ പിതാവിൽ നിന്നുദ്ധരിക്കുന്നു: ഉഹ്ദ് ദിവസം തിരുമേനി(സ) തോലിന്റെ ജലപ്പാത്രം കൊണ്ടുവരാനാവശ്യപ്പെട്ട് പറഞ്ഞു: "നീയതിന്റെ വായ വിടർത്തുക." അനന്തരം റസൂൽ(സ) അതിന്റെ വായിൽനിന്നു പാനം ചെയ്തു. (ദ,തു)', 'عِيسَى بْنِ عَبْدِ اللهِ - رَجُلٌ مِنَ الْأَنْصَارِ - عَنْ أَبِيهِ', 'ഈസബ്‌നു അബ്ദില്ല(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اخْتِنَاثِ الْأَسْقِيَةِ أَنْ يُشْرَبَ مِنْ أَفْوَاهِهَا. وفي رواية: وَاخْتِنَاثُهَا أَنْ يُقْلَبَ رَأْسُهَا ثُمَّ يُشْرَبَ مِنْهُ. (م)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): തോൽ പാത്രങ്ങളുടെ വായ വിടർത്തി അതിന്റെ വായിൽ നിന്ന് കുടിക്കൽ റസൂൽ(സ) നിരോധിച്ചു. മറ്റൊരു നിവേദനം: ഇഖ്തിനാസ് എന്നാൽ തോൽ പാത്രം തലകീഴായിമറിച്ച് ശേഷം അതിൽനിന്നു പാനം ചെയ്യലാണ്. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=174), 1, 'وَفِي رِوَايَةٍ: وَاخْتِنَاثُهَا أَنْ يُقْلَبَ رَأْسُهَا ثُمَّ يُشْرَبَ مِنْهُ. (م)', 'മറ്റൊരു നിവേദനം: ഇഖ്തിനാസ് എന്നാൽ തോൽ പാത്രം തലകീഴായിമറിച്ച് ശേഷം അതിൽനിന്നു പാനം ചെയ്യലാണ്. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اخْتِنَاثِ الْأَسْقِيَةِ، وَإِنَّ رَجُلًا بَعْدَ مَا نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ قَامَ مِنَ اللَّيْلِ إِلَى سِقَاءٍ فَاخْتَنَثَهُ، فَخَرَجَتْ عَلَيْهِ مِنْهُ حَيَّةٌ. (جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): പാത്രങ്ങളുടെ വായതുറന്നു കുടിക്കൽ റസൂൽ(സ) നിരോധിച്ചു. അവിടന്നത് വിലക്കിയ ശേഷം ഒരാൾ രാത്രിയിൽ തന്റെ തോൽ പാത്രത്തിന്റെ വായ വലിച്ചുതുറന്ന് കുടിക്കാൻ ശ്രമിച്ചപ്പോൾ അയാളുടെ നേരെ അതിൽ നിന്നൊരു പാമ്പ് പുറത്തുവന്നു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ إِلَى قِرْبَةٍ مُعَلَّقَةٍ، فَخَنَثَهَا ثُمَّ شَرِبَ مِنْ فِيهَا. (د،ت)', 'അബ്ദുല്ലാഹിബ്‌നു ഉനൈസ്(റ): റസൂൽ(സ) തൂക്കിയിട്ടിരുന്ന ഒരു തോൽ പാത്രത്തിന്റെ അടുക്കൽ ചെന്ന് അതിന്റെ വായ വിടർത്തി അതിൽനിന്ന് പാനംചെയ്യുന്നത് ഞാൻ കണ്ടു. (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ أُنَيْسٍ', 'അബ്ദുല്ലാഹിബ്‌നു ഉനൈസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ كَبْشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشَرِبَ مِنْ فِي قِرْبَةٍ مُعَلَّقَةٍ قَائِمًا، فَقُمْتُ إِلَى فِيهَا فَقَطَعْتُهُ. حَسَنٌ صَحِيحٌ (ت،جه)', 'കബ്ശ(റ): റസൂൽ(സ) എന്റെയടുക്കൽ കടന്നുവന്നു. തൂക്കിയിട്ടിരുന്ന തോൽ പാത്രത്തിന്റെ വായിൽകൂടി നബി(സ) നിന്നുകൊണ്ട് കുടിച്ചു. തൽസമയം ഞാൻ എഴുന്നേറ്റ് അതിന്റെ വായ മുറിച്ചെടുത്തു. (തു,ജ)', 'كَبْشَةَ', 'കബ്ശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 633, 633, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الشُّرْبِ مِنْ فِي السِّقَاءِ، وَعَنْ رُكُوبِ الْجَلَّالَةِ وَالْمُجَثَّمَةِ؟. (خ،د،ت،ن،جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): തോൽപ്പാത്രത്തിന്റെ വായിലൂടെ കുടിക്കുന്നതിനെയും കാഷ്ടം സ്ഥിരം കഴിക്കുന്ന ജീവിയെ വാഹനമായി ഉപയോഗിക്കുന്നതിനെയും അടയാളക്കുറിയായി സ്ഥാപിച്ച് ജീവിയെ കൊല്ലുന്നതിനെയും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الَّذِي يَشْرَبُ فِي إِنَاءِ الْفِضَّةِ إِنَّمَا يُجَرْجِرُ فِي بَطْنِهِ نَارَ جَهَنَّمَ". (ق،جه)', 'പ്രവാചകപത്നി ഉമ്മുസലമ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയമായും വെള്ളിയുടെ പാത്രത്തിൽ കുടിക്കുന്നവൻ തന്റെ ഉദരത്തിൽ നരകാഗ്നിയാണ് നിറക്കുന്നത്." (ബു,മു,ജ)', 'أُمِّ سَلَمَةَ', 'പ്രവാചകപത്നി ഉമ്മുസലമ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الشُّرْبِ فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ وَقَالَ: "هِيَ لَهُمْ فِي الدُّنْيَا وَهِيَ لَكُمْ فِي الْآخِرَةِ." [ز: ٣٥٩٠] (ق،د،ت،ن،جه)', 'ഹുദൈഫ(റ): റസൂൽ(സ) സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും പാത്രത്തിൽ നിന്ന് പാനം ചെയ്യുന്നത് നിരോധിച്ചിട്ട് പറഞ്ഞു: "അത് ഇഹലോകത്ത് അവർക്കുള്ളതും (സത്യനിഷേധികൾക്ക്) പരലോകത്ത് നിങ്ങൾക്കുള്ളതുമാകുന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'ز: ٣٥٩٠', null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنِ ابْنِ أَبِي لَيْلَى قَالَ: كَانَ حُذَيْفَةُ بِالْمَدَائِنِ، فَاسْتَسْقَى، فَأَتَاهُ دِهْقَانٌ بِإِنَاءٍ مِنْ فِضَّةٍ، فَرَمَاهُ بِهِ، وَقَالَ: إِنِّي لَمْ أَرْمِهِ بِهِ إِلَّا أَنِّي قَدْ نَهَيْتُهُ فَلَمْ يَنْتَهِ، وَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْحَرِيرِ وَالدِّيبَاجِ، وَعَنِ الشُّرْبِ فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، وَقَالَ: "هِيَ لَهُمْ فِي الدُّنْيَا وَلَكُمْ فِي الْآخِرَةِ". (ق،د،ت،جه)', 'ഇബ്‌നു അബീലൈല(റ): ഹുദൈഫ(റ) മദായിനിൽ ആയിരുന്ന സന്ദർഭത്തിൽ കുടിക്കാൻ വെള്ളം ആവശ്യപ്പെട്ടു. അപ്പോൾ അദ്ദേഹത്തിന്റെയടുത്ത് വെള്ളിയുടെ പാത്രവുമായി ഗ്രാമമുഖ്യൻ വന്നു. തൽസമയം ഹുദൈഫ(റ) അദ്ദേഹത്തെ അതുകൊണ്ടെറിഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: നിശ്ചയം ഞാൻ അദ്ദേഹത്തെ വിലക്കിയിട്ടും അദ്ദേഹമതിൽ നിന്ന് പിന്മാറാത്തതുകൊണ്ട് മാത്രമാണ് പാത്രം കൊണ്ട് ഞാനദ്ദേഹത്തെ എറിഞ്ഞത്. തീർച്ചയായും റസൂൽ(സ) നേരിയപട്ടും കട്ടിയുള്ളപട്ടും സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും പാത്രത്തിൽ പാനം ചെയ്യലും നിരോധിച്ചു. എന്നിട്ട് പറഞ്ഞു: "അവ ഇഹലോകത്ത് അവർക്കും പരലോകത്ത് നിങ്ങൾക്കും (സത്യവിശ്വാസികൾക്കും) ആകുന്നു." (ബു,മു,ദ,തു,ജ)', 'ابْنِ أَبِي لَيْلَى قَالَ', 'ഇബ്‌നു അബീലൈല(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 634, 634, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَشْرَبَ الرَّجُلُ قَائِمًا، فَقِيلَ: الْأَكْلُ؟ قَالَ: "ذَاكَ أَشَدُّ". حَسَنٌ صَحِيحٌ (م, د, ت)', 'അനസ്(റ): നിന്നു പാനംചെയ്യൽ റസൂൽ(സ) നിരോധിച്ചു. അപ്പോൾ ചോദിക്കപ്പെട്ടു. തീറ്റയോ? റസൂൽ(സ) പ്രതിവചിച്ചു: "അത് ഏറ്റവും ഗുരുതരമാണ്." (മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 634, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نَأْكُلُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَمْشِي، وَنَشْرَبُ وَنَحْنُ قِيَامٌ. صَحِيحٌ (ت, جه)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ)യുടെ കാലഘട്ടത്തിൽ ഞങ്ങൾ നടന്നു ഭക്ഷിക്കുകയും നിന്നു കുടിക്കുകയും ചെയ്തിരുന്നു. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنِ النَّزَّالِ بْنِ سَبْرَةَ: أَنَّ عَلِيًّا دَعَا بِمَاءٍ فَشَرِبَهُ وَهُوَ قَائِمٌ، ثُمَّ قَالَ: إِنَّ رِجَالًا يَكْرَهُ أَحَدُهُمْ أَنْ يَفْعَلَ هَذَا، وَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَفْعَلُ مِثْلَ مَا رَأَيْتُمُونِي أَفْعَلُهُ. (خ, د, ن)', 'നസ്സാലുബ്‌നുസബ്‌റ(റ): അലി(റ) വെള്ളം ആവശ്യപ്പെടുകയും നിന്നുകൊണ്ട് കുടിക്കുകയും ചെയ്തു. പിന്നീടദ്ദേഹം പറഞ്ഞു: ചിലർ ഇപ്രകാരം ചെയ്യുന്നതിനെ വെറുക്കുന്നു. എന്നാൽ ഞാൻ ചെയ്യുന്നതു നിങ്ങൾ കാണുന്നതുപോലെ, റസൂൽ(സ) ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു,ദ,ന)', 'النَّزَّالِ بْنِ سَبْرَةَ', 'നസ്സാലുബ്‌നുസബ്‌റ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَشْرَبَنَّ أَحَدٌ مِنْكُمْ قَائِمًا، فَمَنْ نَسِيَ فَلْيَسْتَقِئْ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരും നിന്നുകൊണ്ട് കുടിക്കരുത്. ആരെങ്കിലും വിസ്മരിച്ചാൽ അവൻ ചർദ്ദിച്ചുകൊള്ളട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَن كَبْشَةَ الْأَنْصَارِيَّةِ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَعِنْدَهَا قِرْبَةٌ مُعَلَّقَةٌ، فَشَرِبَ مِنْهَا وَهُوَ قَائِمٌ، فَقَطَعَتْ فَمَ الْقِرْبَةِ، تَبْتَغِي بَرَكَةَ مَوْضِعِ فِي رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ. (ت, جه)', 'കബ്ശത്തുൽ അൻസാരിയ(റ): റസൂൽ(സ) അവരുടെ അടുക്കൽ കടന്നുവന്നു. അവരുടെയടുക്കൽ തൂക്കിയിട്ടിരുന്ന ഒരുതോൽ പാത്രവുമുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) നിന്നുകൊണ്ടതിൽനിന്നു പാനംചെയ്യുകയുണ്ടായി. തത്സമയം പ്രവാചകർ(സ)യുടെ വായ സ്പർശിച്ച സ്ഥലത്തിന്റെ ബറക്കത്ത് ആഗ്രഹിച്ചുകൊണ്ട് അവർ ആ തോൽ പാത്രത്തിന്റെ വായ മുറിച്ചെടുത്തു. (തു,ജ)', 'كَبْشَةَ الْأَنْصَارِيَّةِ', 'കബ്ശത്തുൽ അൻസാരിയ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ شَرِبَ مِنْ زَمْزَمَ وَهُوَ قَائِمٌ. حَسَنٌ صَحِيحٌ (ق, ت, ن, جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ) സംസംവെള്ളം നിന്നു കുടിച്ചു. (ബു,മു,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَشْرَبُ قَائِمًا وَقَاعِدًا، حَسَنٌ صَحِيحٌ (م)', 'അബ്ദുല്ലാഹിബ്‌നു അംറ്(റ): റസൂൽ(സ) നിന്നും ഇരുന്നും കുടിക്കുന്നതു ഞാൻകണ്ടിട്ടുണ്ട്. (മു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്‌നു അംറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 635, 635, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَقَيْتُ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ مِنْ زَمْزَمَ فَشَرِبَ قَائِمًا، وَاسْتَسْقَى وَهُوَ عِنْدَ الْبَيْتِ. (م)', 'ഇബ്‌നുഅബ്ബാസ്(റ): ഞാൻ റസൂൽ(സ)യെ സംസംവെള്ളം കുടിപ്പിച്ചു. അപ്പോൾ അവിടന്ന് നിന്നാണ് പാനം ചെയ്തത്. കഅ്ബയുടെ സമീപത്തുവെച്ച് കുടിക്കാൻ വെള്ളം ആവശ്യപ്പെടുകയും ചെയ്തു. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 635, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَبَنٍ، وَعَنْ يَمِينِهِ ابْنُ عَبَّاسٍ وَعَنْ يَسَارِهِ خَالِدُ بْنُ الْوَلِيدِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِابْنِ عَبَّاسٍ: "أَتَأْذَنُ لِي أَنْ أَسْقِيَ خَالِدًا؟". قَالَ ابْنُ عَبَّاسٍ: مَا أُحِبُّ أَنْ أُوثِرَ بِسُؤْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى نَفْسِي أَحَدًا. فَأَخَذَ ابْنُ عَبَّاسٍ فَشَرِبَ، وَشَرِبَ خَالِدٌ. (جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ)ക്ക് കുറച്ച് പാൽ നൽകപ്പെട്ടു. വലതുഭാഗത്ത് ഇബ്‌നുഅബ്ബാസ്(റ)വും ഇടതുഭാഗത്ത് ഖാലിദുബിനു വലീദ്(റ)വും ഉണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) ഇബ്‌നുഅബ്ബാസ്(റ)വിനോടു ചോദിച്ചു: "ഖാലിദിനെ കുടിപ്പിക്കാൻ നീ എനിക്കനുവാദം തരുമോ?" ഇബ്‌നുഅബ്ബാസ്(റ) പറഞ്ഞു: റസൂൽ(സ)യുടെ മിച്ചത്തിൽ ഞാനെന്നെ അവഗണിച്ചുകൊണ്ട് മറ്റൊരാളെ തിരഞ്ഞെടുക്കാൻ ഇഷ്ടപ്പെടുന്നില്ല. ശേഷം ഇബ്‌നുഅബ്ബാസ്(റ) വാങ്ങി കുടിച്ചു. ശേഷം ഖാലിദ്(റ)വും പാനം ചെയ്തു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي دَارِنَا فَاسْتَسْقَى، فَحَلَبْنَا لَهُ شَاةً، ثُمَّ شُبْتُهُ مِنْ مَاءِ بِئْرِي هَذِهِ، قَالَ: فَأَعْطَيْتُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَشَرِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَبُو بَكْرٍ عَنْ يَسَارِهِ، وَعُمَرُ وَجَاهَهُ، وَأَعْرَابِيٌّ عَنْ يَمِينِهِ، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ شُرْبِهِ، قَالَ عُمَرُ: هَذَا أَبُو بَكْرٍ يَا رَسُولَ اللَّهِ، يُرِيهِ إِيَّاهُ، فَأَعْطَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْأَعْرَابِيَّ وَتَرَكَ أَبَا بَكْرٍ وَعُمَرَ، وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْأَيْمَنُونَ الْأَيْمَنُونَ الْأَيْمَنُونَ". قَالَ أَنَسٌ: فَهِيَ سُنَّةٌ، فَهِيَ سُنَّةٌ، فَهِيَ سُنَّةٌ. (ق،د،ت،جه)', 'അനസുബ്‌നുമാലിക്(റ): റസൂൽ(സ) ഞങ്ങളുടെ വീട്ടിൽ വന്ന് പാനീയം ആവശ്യപ്പെട്ടു. അപ്പോൾ ഞങ്ങൾ അവിടത്തേക്ക് വേണ്ടി ഒരാടിനെ കറന്നു. ശേഷം ആ പാൽ എന്റെ ഈ കിണറിലെ വെള്ളവുമായി കലർത്തി. അനസ്(റ) പറയുന്നു: ഞാനത് റസൂൽ(സ)ക്ക് നൽകുകയും അവിടന്നത്. കുടിക്കുകയും ചെയ്തു. അവിടത്തെ ഇടതുഭാഗത്ത് അബൂബക്കർ(റ)വും അഭിമുഖമായിട്ട് ഉമർ(റ)വും വലതുഭാഗത്ത് ഒരു ഗ്രാമീണനുമാണ് ഉണ്ടായിരുന്നത്. അവിടന്നത് കുടിച്ചുകഴിഞ്ഞപ്പോൾ ഉമർ(റ) അബൂബക്കർ(റ)വിനെ കാണിച്ചുകൊടുത്ത്കൊണ്ടു പറഞ്ഞു: ദൈവദൂതരേ, ഇത് അബൂബക്കറാണ്. എന്നാൽ, തിരുമേനി(സ) അബൂബക്കർ(റ)വിനെയും ഉമർ(റ)വിനെയും ഒഴിവാക്കി ഗ്രാമീണന് പാൽ നൽകിയിട്ട് പറഞ്ഞു: "വലതുഭാഗത്തുള്ളവർ, വലതുഭാഗത്തുള്ളവർ, വലതുഭാഗത്തുള്ളവർ." (അവരെ മുന്തിക്കണം) അനസ്(റ) പറഞ്ഞു: അതാണ് പ്രവാചകചര്യ, അതാണ് പ്രവാചകചര്യ, അതാണ് പ്രവാചകചര്യ. (ബു,മു,ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നുമാലിക്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 636, 636, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِشَرَابٍ فَشَرِبَ مِنْهُ، وَعَنْ يَمِينِهِ غُلَامٌ وَعَنْ يَسَارِهِ أَشْيَاخٌ، فَقَالَ لِلْغُلَامِ: "أَتَأْذَنُ لِي أَنْ أُعْطِيَ هؤُلَاءِ". فَقَالَ الْغُلَامُ: لَا وَاللَّهِ، لَا أُوثِرُ بِنَصِيبِي مِنْكَ أَحَدًا. قَالَ: فَتَلَّهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي يَدِهِ. (م)', 'സഹ്‌ല്‌ബ്‌നു സഅദിസ്സാഇദി(റ): റസൂൽ(സ)ക്ക് കുറച്ച് പാനീയം നൽകപ്പെട്ടു. അവിടന്നതിൽ നിന്ന് അൽപം കുടിച്ചു. നബിയുടെ വലതുഭാഗത്ത് ഒരു യുവാവും ഇടതുഭാഗത്ത് കുറെ വൃദ്ധന്മാരും ഉണ്ടായിരുന്നു. നബി(സ) യുവാവിനോടു ചോദിച്ചു: "ഇവർക്ക് (വൃദ്ധന്മാർക്ക്) ആദ്യം നൽകാൻ നീ എനിക്ക് അനുവാദം നൽകുമോ?" യുവാവ് പറഞ്ഞു: ഇല്ല, അല്ലാഹു സത്യം! താങ്കളിൽ നിന്ന് എനിക്കുള്ള ഓഹരിക്ക് ഞാനാരെയും തെരഞ്ഞെടുക്കുകയില്ല. ഉടൻതന്നെ നബി(സ) അതദ്ദേഹത്തിന്റെ കൈയ്യിൽ ഒഴിച്ചുകൊടുത്തു. (മു)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്‌ല്‌ബ്‌നു സഅദിസ്സാഇദി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 636, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَاقِي الْقَوْمِ آخِرُهُمْ شُرْبًا". (م,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്‌നു അബീഔഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളെ കുടിപ്പിക്കുന്നവൻ അവരിൽ അവസാനമാണ് കുടിക്കേണ്ടത്." (മു,ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്‌നു അബീഔഫ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَشْرَبُوا وَاحِدًا كَشُرْبِ الْبَعِيرِ، وَلَكِنِ اشْرَبُوا مَثْنَى وَثُلَاثَ، وَسَمُّوا إِذَا أَنْتُمْ شَرِبْتُمْ، وَاحْمَدُوا إِذَا أَنْتُمْ رَفَعْتُمْ". (ت)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ) അരുളി: "ഒട്ടകം കുടിക്കുന്നതു പോലെ ഒറ്റ പ്രാവശ്യമായി നിങ്ങൾ കുടിക്കരുത്. മറിച്ച് രണ്ടോ മൂന്നോ പ്രാവശ്യമായിട്ട് നിങ്ങൾ പാനം ചെയ്യുക. പാനം ചെയ്യുമ്പോൾ നിങ്ങൾ ബിസ്മി ചൊല്ലുകയും പാത്രം എടുത്തു മാറ്റുമ്പോൾ അല്ലാഹുവിനെ സ്തുതിക്കുകയും ചെയ്യുക." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَنَفَّسُ فِي الشَّرَابِ ثَلَاثًا، وَيَقُولُ: "إِنَّهُ أَرْوَى وَأَبْرَأُ وَأَمْرَأُ". قَالَ أَنَسٌ: فَأَنَا أَتَنَفَّسُ فِي الشَّرَابِ ثَلَاثًا. (م,د,ت,ن)', 'അനസ്(റ): കുടിക്കുന്നതിനിടയിൽ റസൂൽ(സ) മൂന്നുപ്രാവശ്യം ശ്വാസിക്കുമായിരുന്നു. അവിടന്ന് പറയും: "തീർച്ചയായുമത് ഏറ്റവും ദാഹം ശമിപ്പിക്കുന്നതും ദാഹപാരവശ്യത്തിൽനിന്ന് മോചനം നൽകുന്നതും ഏറ്റവും ആസ്വാദ്യകരവുമാകുന്നു." അനസ്(റ) പറയുന്നു: കുടിക്കുമ്പോൾ ഞാൻ മൂന്നു പ്രാവശ്യം ശ്വാസിക്കാറുണ്ട്. (മു,ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَرِبَ، فَتَنَفَّسَ فِيهِ مَرَّتَيْنِ. (ت,جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂൽ(സ) പാനം ചെയ്യുകയും രണ്ട് പ്രാവശ്യമതിൽ ശ്വാസം വിടുകയും ചെയ്തു. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 637, 637, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ النَّفْخِ فِي الشُّرْبِ. فَقَالَ رَجُلٌ: الْقَذَاةُ أَرَاهَا فِي الْإِنَاءِ؟ قَالَ: "أَهْرِقْهَا". قَالَ: فَإِنِّي لَا أَرْوَى مِنْ نَفَسٍ وَاحِدٍ؟ قَالَ: "فَأَبِنِ الْقَدَحَ إِذَنْ عَنْ فِيكَ". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): പാനീയത്തിൽ ഊതുന്നത് റസൂൽ(സ) വിലക്കി. ഒരാൾ ചോദിച്ചു: പാത്രത്തിൽ കരട് കണ്ടാലോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ ആ കരട് ഒഴിച്ചു കളയുക." അദ്ദേഹം പറഞ്ഞു: ഒറ്റ വലിക്ക് (ഒറ്റ ശ്വാസത്തിൽ) എനിക്ക് ദാഹം തീരുകയില്ലല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "അപ്പോൾ നീ പാത്രം വായിൽനിന്ന് അകറ്റിപ്പിടിക്കുക." (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنْفَخَ فِي الْإِنَاءِ. وَفِي رِوَايَةٍ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْفُخُ فِي الشَّرَابِ. (جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): പാത്രത്തിൽ ഊതൽ റസൂൽ(സ) നിരോധിച്ചു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) പാനീയത്തിൽ ഊതാറില്ലായിരുന്നു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=198), 1, 'وَفِي رِوَايَةٍ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْفُخُ فِي الشَّرَابِ. (جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പാനീയത്തിൽ ഊതാറില്ലായിരുന്നു. (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ، فَإِذَا أَرَادَ أَنْ يَعُودَ فَلْيُنَحِّ الْإِنَاءَ، ثُمَّ لِيُعَدْ إِنْ كَانَ يُرِيدُ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും കുടിക്കുമ്പോൾ ആ പാത്രത്തിലേക്ക് ശ്വാസം വിടാതിരിക്കട്ടെ. അവൻ വീണ്ടും മടങ്ങാൻ (കുടിക്കാൻ) ഉദ്ദേശിച്ചാൽ പാത്രം അവൻ മാറ്റിക്കളയേണ്ടതാണ്. വീണ്ടും അവൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അത് ആവർത്തിച്ചുകൊള്ളട്ടെ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ التَّنَفُّسِ فِي الْإِنَاءِ. (ق, جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): പാത്രത്തിലേക്ക് ശ്വാസം വിടുന്നതിനെ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَغْطِيَةِ الْإِنَاءِ، وَإِيكَاءِ السِّقَاءِ، وَإِكْفَاءِ الْإِنَاءِ. (جه)', 'അബൂഹുറൈറ(റ): പാത്രം മൂടിവെക്കാനും തോൽ പാത്രം കെട്ടിവെക്കാനും പാത്രം ചെരിച്ചുവെക്കാനും റസൂൽ(സ) ഞങ്ങളോടു കൽപ്പിച്ചു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 638, 638, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ أَضَعُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ آنِيَةٍ مِنَ اللَّيْلِ مُخَمَّرَةً: إِنَاءً لِطَهُورِهِ، وَإِنَاءً لِسِوَاكِهِ، وَإِنَاءً لِشَرَابِهِ. [ز: في سيده ضعيف] (جه)', 'ആഇശ(റ): മൂടികളുള്ള മൂന്നു പാത്രങ്ങൾ രാത്രി പ്രവാചകൻ(സ)യുടെ ആവശ്യത്തിന് ഞാൻ വെക്കാറുണ്ടായിരുന്നു. ഒരു പാത്രം ശുദ്ധീകരണത്തിനും മറ്റൊന്നു ദന്തശുദ്ധീകരണത്തിനും മൂന്നാമത്തേത് പാനം ചെയ്യുന്നതിനുമായിരുന്നു. (പരമ്പരയിൽ ബലഹീനനുണ്ട്). (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سيده ضعيف', null, 638, 639, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "غَطُّوا الإِنَاءَ وَأَوْكُوا السِّقَاءَ، فَإِنَّ فِي السَّنَةِ لَيْلَةً يَنْزِلُ فِيهَا وَبَاءٌ، لَا يَمُرُّ بِإِنَاءٍ لَيْسَ عَلَيْهِ غِطَاءٌ أَوْ سِقَاءٍ لَيْسَ عَلَيْهِ وِكَاءٌ إِلَّا نَزَلَ فِيهِ مِنْ ذَلِكَ الْوَبَاءِ". وفي رواية :قَالَ اللَّيْثُ - يعني ابن سعد - : فَالْأَعَاجِمُ عِنْدَنَا يَتَّقُونَ ذَلِكَ فِي كَانُونِ الْأَوَّلِ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾ പാത്രം മൂടിവെക്കുകയും തോൽപാത്രം കെട്ടിവെക്കുകയും ചെയ്യുക. കാരണം തീർച്ചയായും വർഷത്തിലൊരു രാത്രി പകർച്ചവ്യാധി ഇറങ്ങാറുണ്ട്. മൂടിവെക്കാത്ത ആഹാരപ്പാത്രത്തിലും കെട്ടിവെക്കാത്ത തോൽപാത്രാത്രത്തിലും അതിറങ്ങുക തന്നെ ചെയ്യുന്നതാണ്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=203), 1, 'وَفِي رِوَايَةٍ :قَالَ اللَّيْثُ - يعني ابن سعد - : فَالْأَعَاجِمُ عِنْدَنَا يَتَّقُونَ ذَلِكَ فِي كَانُونِ الْأَوَّلِ. (م)', 'മറ്റൊരു നിവേദനത്തിൽ: ഇബ്നുസഅ്ദ് എന്ന ലൈസ് പറയുന്നു: ഞങ്ങളുടെയടുക്കലുള്ള അനറബികൾ ശൈത്യകാലത്ത് അത് സൂക്ഷിക്കുമായിരുന്നു. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَغْلِقْ بَابَكَ وَاذْكُرِ اسْمَ اللَّهِ، فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ بَابًا مُغْلَقًا، وَأَطْفِ مِصْبَاحَكَ وَاذْكُرِ اسْمَ اللَّهِ، وَخَمِّرْ إِنَاءَكَ - وَلَوْ بِعُودٍ تَعْرُضُهُ عَلَيْهِ - وَاذْكُرِ اسْمَ اللَّهِ، وَأَوْكِ سِقَاءَكَ وَاذْكُرِ اسْمَ اللَّهِ". وفي رواية: "فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ بَابًا غَلَقًا، وَلَا يَحُلُّ وِكَاءً، وَلَا يَكْشِفُ إِنَاءً، وَإِنَّ الْفُوَيْسِقَةَ تُضْرِمُ عَلَى النَّاسِ بَيْتَهُمْ". أَوْ: "بُيُوتَهُمْ". (ق, د, ت, جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "നീ നിന്റെ വാതിൽ അടക്കുകയും അല്ലാഹുവിന്റെ പേര് പറയുകയും ചെയ്യുക. കാരണം അടക്കപ്പെട്ട വാതിൽ പിശാച് തുറക്കുകയില്ല തന്നെ. നീ വിളക്ക് കെടുത്തുകയും അല്ലാഹുവിന്റെ പേര് പറയുകയും ചെയ്യുക. വിലങ്ങനെ വെക്കുന്ന ഒരു കൊള്ളി കൊണ്ടെങ്കിലും നീ പാത്രം മൂടുകയും അല്ലാഹുവിന്റെ പേര് പറയുകയും ചെയ്യുക. വെള്ളം വെക്കുന്ന തോൽപ്പാത്രം കെട്ടുകയും അല്ലാഹുവിന്റെ പേര് പറയുകയും ചെയ്യുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=204), 1, 'وَفِي رِوَايَةٍ: "فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ بَابًا غَلَقًا، وَلَا يَحُلُّ وِكَاءً، وَلَا يَكْشِفُ إِنَاءً، وَإِنَّ الْفُوَيْسِقَةَ تُضْرِمُ عَلَى النَّاسِ بَيْتَهُمْ". أَوْ: "بُيُوتَهُمْ". (ق, د, ت, جه)', 'മറ്റൊരു നിവേദനം: "നിശ്ചയം ശൈത്വാൻ അടഞ്ഞ വാതിൽ തുറക്കുകയില്ല, കെട്ടഴിക്കുകയുമില്ല, പാത്രം തുറക്കുകയുമില്ല. നിശ്ചയം, എലി ജനങ്ങൾക്കുമേൽ അവരുടെ വീടുകളെ കത്തിക്കും." (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ جُنْحُ اللَّيْلِ - أَوْ أَمْسَيْتُمْ - فَكُفُّوا صِبْيَانَكُمْ، فَإِنَّ الشَّيْطَانَ يَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيْلِ فَخَلُّوهُمْ، وَأَغْلِقُوا الْأَبْوَابَ، وَاذْكُرُوا اسْمَ اللَّهِ، فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ بَابًا مُغْلَقًا، وَأَوْكُوا قِرَبَكُمْ وَاذْكُرُوا اسْمَ اللَّهِ، وَخَمِّرُوا آنِيَتَكُمْ وَاذْكُرُوا اسْمَ اللَّهِ، وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئًا، وَأَطْفِئُوا مَصَابِيحَكُمْ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "രാത്രി ഇരുട്ടുകയോ സന്ധ്യയാകുകയോ ചെയ്താൽ നിങ്ങളുടെ കുട്ടികളെ തടഞ്ഞുകൊള്ളുക. കാരണം, ആ സമയത്ത് പിശാച് ഭൂമിയിൽ പരക്കും. രാത്രി കുറച്ചു സമയം കഴിഞ്ഞാൽ നിങ്ങൾ അവരെ വിട്ടേക്കുക. വാതിലുകൾ അടച്ച് ബിസ്മി ചൊല്ലുകയും ചെയ്യുക. തീർച്ചയായും പിശാച് അടക്കപ്പെട്ട വാതിൽ തുറക്കുകയില്ല. തോൽ പാത്രത്തിന്റെ വായ് കെട്ടുകയും അല്ലാഹുവിന്റെ പേര് പറയുകയും ചെയ്യുക. നിങ്ങളുടെ ആഹാരപാത്രം മൂടിവെക്കുകയും അല്ലാഹുവിന്റെ പേര് പറയുകയും ചെയ്യുക, (മൂടി വെക്കാൻ ഒന്നും ലഭിച്ചില്ലെങ്കിൽ) അതിന്റെ മേൽ എന്തെങ്കിലും സാധനം വിലങ്ങനെ എടുത്ത്വെക്കുകയും നിങ്ങളുടെ വിളക്കുകൾ അണക്കുകയും ചെയ്യുക." (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 639, 639, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا - رَفَعَهُ - قَالَ: "وَاكْفِتُوا صِبْيَانَكُمْ عِنْدَ العِشَاءِ - وفي رواية: عِنْدَ الْمَسَاءِ - فَإِنَّ لِلْجِنِّ انْتِشَارًا وَخَطْفَةً". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അദ്ദേഹം നബി(സ)യിലേക്ക് ഉയർത്തിയിരിക്കുന്നു. "നിങ്ങൾ ഇശാ സമയത്ത് - മറ്റൊരു നിവേദനം: വൈകുന്നേര സമയത്ത് - കുട്ടികളെ വീടുകളിൽ ഒതുക്കിനിർത്തുക. കാരണം, ജിന്നുകൾക്ക് ഒരു സൈര വിഹാരം നടത്തലും റാഞ്ചലുമുണ്ട്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=7 and h.hadith_no=206), 1, 'وَفِي رِوَايَةٍ: عِنْدَ الْمَسَاءِ - فَإِنَّ لِلْجِنِّ انْتِشَارًا وَخَطْفَةً". (د)', 'മറ്റൊരു നിവേദനം: വൈകുന്നേര സമയത്ത് - കുട്ടികളെ വീടുകളിൽ ഒതുക്കിനിർത്തുക. കാരണം, ജിന്നുകൾക്ക് ഒരു സൈര വിഹാരം നടത്തലും റാഞ്ചലുമുണ്ട്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَسْقَى، فَقَالَ رَجُلٌ مِنَ القَوْمِ: أَلَا نَسْقِيكَ نَبِيذًا؟ قَالَ: "بَلَى". قَالَ: فَخَرَجَ الرَّجُلُ يَشْتَدُّ فَجَاءَ بِقَدَحٍ فِيهِ نَبِيذٌ، فَقَالَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "أَلَا خَمَّرْتَهُ، وَلَوْ أَنْ تَعْرُضَ عَلَيْهِ عُودًا". (ق,د)', 'ജാബിർ(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെയായിരുന്നു. അവിടന്ന് കുടിക്കുവാൻ പാനീയം ആവശ്യപ്പെട്ടു. കൂട്ടത്തിൽ ഒരാൾ ചോദിച്ചു: ഞങ്ങൾ അവിടത്തേക്ക് മുന്തിരിച്ചാറ് കൊണ്ട് തരട്ടെയോ? നബി(സ)പറഞ്ഞു: "അതെ." ആ മനുഷ്യൻ ധൃതിയിൽ പോയി മുന്തിരിച്ചാറള്ള ഒരു പാത്രവുമായി വന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു. "ഒരു കൊള്ളി വിലങ്ങനെ വെച്ച് കൊണ്ടെങ്കിലും നിനക്കത് മൂടിവെക്കാമായിരുന്നില്ലേ?" (ബു,മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ كَانَ يُسْتَعْذَبُ لَهُ الْمَاءُ مِنْ بُيُوتِ السُّقْيَا. (د)', 'ആഇശ(റ): നബി(സ)ക്ക് ബുയൂതുസ്സുഖ്യാ (മദീനയിൽ നിന്ന് രണ്ടു ദിവസത്തെ വഴിദൂരത്തിൽ സ്ഥിതി ചെയ്യുന്ന അരുവി) യിൽ നിന്ന് നല്ല തെളിനീര് കൊണ്ട് വരാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ بِقَدَحٍ لَبَنٍ مِنَ النَّقِيعِ لَيْسَ مُخَمَّرًا، فَقَالَ: "أَلَّا خَمَّرْتَهُ، وَلَوْ تَعْرُضُ عَلَيْهِ عُودًا". قَالَ أَبُو حُمَيْدٍ: إِنَّمَا أُمِرَ بِالْأَسْقِيَةِ أَنْ تُوكَأَ لَيْلًا، وَبِالْأَبْوَابِ أَنْ تُغْلَقَ لَيْلًا. (م)', 'അബൂഹുമൈദുസ്സാഇദി(റ): ''നകീഅ്'' എന്ന സ്ഥലത്തു നിന്ന് മൂടിവെക്കാത്ത ഒരു പാൽപ്പാത്രം ഞാൻ നബി(സ)ക്ക് കൊണ്ടുവന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളെന്തുകൊണ്ട് ഇതു മൂടി കൊണ്ട്വന്നില്ല. ഒരു കൊള്ളിക്കഷ്ണമെങ്കിലും മീതെ വെക്കാമായിരുന്നില്ലേ." അബൂഹുമൈദ്(റ) പറയുന്നു: രാത്രിയിൽ തോൽപ്പാത്രങ്ങൾ കെട്ടിവെക്കാനും വാതിലുകൾ അടക്കാനും ഞങ്ങൾ നിർദ്ദേശിക്കപ്പെട്ടിരിക്കുന്നു. (മു)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദുസ്സാഇദി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ أَحَبُّ الشَّرَابِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْحُلْوَ الْبَارِدَ. (ت)', 'ആഇശ(റ): റസൂൽ(സ)ക്ക് ഏറ്റവും പ്രിയങ്കരമായ പാനീയം ശീതളമധുരപാനീയമായിരുന്നു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنِ الزُّهْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الشَّرَابِ أَطْيَبُ؟ قَالَ: "الْحُلْوُ الْبَارِدُ". (ت)', 'സുഹ്‌രി(റ): റസൂൽ(സ)യോടു ചോദിച്ചു: ഏറ്റവും ഹൃദ്യമായ പാനീയമേതാണ്. റസൂൽ(സ) പറഞ്ഞു: "ശീതളമധുര പാനീയം." (തു)', 'الزُّهْرِيِّ', 'സുഹ്‌രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 640, 640, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
