മറ്റൊരു നിവേദനം: പ്രവാചകൻ(സ)ക്ക് വേണ്ടി തോൽപ്പാത്രത്തിൽ ജ്യൂസുണ്ടാക്കാറുണ്ടായിരുന്നു. തോൽപ്പാത്രം ലഭിച്ചില്ലായെങ്കിൽ കൽച്ചട്ടിയിലായിരുന്നു ഞങ്ങൾ അവിടത്തേക്ക് ജ്യൂസുണ്ടാക്കിയിരുന്നത്. അദ്ദേഹം പറയുന്നു: ചുരങ്ങാപ്പാത്രം, ഈത്തപ്പനമുരട് തുരന്നുണ്ടാക്കിയ പാത്രം, ടാർപൂശിയ പാത്രം എന്നിവ റസൂൽ(സ) നിരോധിച്ചു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 609, 610, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
